// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":89,"question":"هل من النياحة اجتماعُ أهل الميت في بيتٍ واستقبالهم للناس ثلاثة أيام؛ تسهيلًا على الأقرباء؟","title":"هل من النياحة استقبال المعزِّين لثلاثة أيام؟","answer":"الجواب: النياحة لا تجوز، لكن إذا جلس في البيت لاستقبال المُعزِّين فلا بأس، فيجلس في البيت في أوقاتٍ مناسبةٍ حتى يزوره أقاربه وغيرهم من المُعزين، لا بأس بذلك، لكن لا يحتفلون بطعام أهل الميت، فيذبحون للناس، أو يصنعون طعامًا للميت، لا، هذه بدعة، لا أصل لها، لكن إذا جلس صاحبُ البيت في الأوقات المناسبة بين المغرب والعشاء، أو ضُحًى، أو غير ذلك؛ ليزوره إخوانه فيُعزونه، حتى لا يشقَّ عليهم، أو عزَّوه في الطريق، أو في المقبرة، أو في المسجد؛ كفى ذلك.","link":"https://binbaz.org.sa/fatwas/3094/هل-من-النياحة-استقبال-المعزين-لثلاثة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0066.mp3","categories":["أحكام التعزية"]},{"id":90,"question":"سائلٌ يقول: ما حكم نشر العزاء في الصحف، ورده أيضًا في الصحف، وكتابة الآيات الكريمة التي فيها تزكية للميت؟","title":"حكم التَّعزية في الصُّحف والمجلات","answer":"الجواب: في الصحف فيما بلغني أنه يُكلِّف كثيرًا، ويُخشى من التَّكلف، ومن النفقات الطائلة بلا حاجةٍ، وإلا فلو كتب: \"أحسن الله عزاء آل فلان في ميتهم، وغفر الله له\" ما يضرُّ، لكن بلغني أنه تكون فيه كُلفة، فتركه أوْلى إذا كانت فيه كُلفة، فيُرسل لهم رسالةً أو برقيةً ويكفي، إذا كانت هناك مشقة ونفقات في النشر في الجريدة. وليس من النَّعي الذي نهى عنه النبيُّ ﷺ، والنعي الذي نهى عنه النبيُّ ﷺ أنه كان أهل الجاهلية إذا مات ميتٌ أركبوا إنسانًا يطوف بين القبائل ينعى إليهم ميتهم، هذا من عمل الجاهلية، أما إذا كتب كتابًا يُعزيه، أو كتب في الجريدة: \"أحسن الله عزاء آل فلان\"، فلا بأس، لكن إذا كان يُكلِّف وفيه مؤونة فينبغي تركه؛ لأن الرسول ﷺ نهى عن إضاعة المال، وهذا من إضاعة المال، ويكفي كتابة خطٍّ إليهم، أو برقية، أو مكالمة هاتفية.","link":"https://binbaz.org.sa/fatwas/3098/حكم-التعزية-في-الصحف-والمجلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0067.mp3","categories":["أحكام التعزية"]},{"id":318,"question":"انتشرت في الآونة الأخيرة ظاهرة التَّعزية في الموتى، وذلك بالكتابة في الجرائد، واستغلال التعزية للدعاية: بكتابة العزاء، وكتابة اسم المؤسسة أو الشركة، كما أن العزاء قد يستمر لفترةٍ طويلةٍ، فما رأي سماحتكم في ذلك؟ وما تُوجِّهون المسؤولين في هذه الجرائد؟","title":"ما حكم التعزية بواسطة الجرائد والصحف؟","answer":"الجواب: ما أعلم في هذا بأسًا، كونه يكتب في الجريدة من أهل الميت: أنا نشكر مَن عزَّانا في فلانٍ، أو: نُعزي في فلانٍ، ما نعلم في ذلك بأسًا، النبيُّ ﷺ لما مات النَّجاشي خرج إلى الناس ونعى إليهم النَّجاشي وقال إنه توفي، وصلَّى عليه، وأمر بالصلاة عليه عليه الصلاة والسلام، فلا نعلم بأسًا في هذا.\nوليس للتعزية حدٌّ محدودٌ، ليس لها حدٌّ: ثلاث، ولا أربع، ولا خمس، ولكن المُبادرة فيها أفضل؛ أن يُبادر بالتَّعزية من حين يموت الميت هذا أفضل، حتى يُخفف على أهل الميت ويُعزيهم ويسليهم، ولكن لو ما عزَّاهم إلا بعد يومين أو ثلاثة أو أربعة لا حرج في ذلك، وليس في هذا حدٌّ محدودٌ عن النبي عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/4350/ما-حكم-التعزية-بواسطة-الجراىد-والصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0369.mp3","categories":["أحكام التعزية"]},{"id":784,"question":"يوجد في التَّعزية عند المقبرة أمرٌ مُستحدثٌ، حيث يصفّ أقاربُ الميت من أولاده وإخوانه على جنبٍ مثل صفِّ الصلاة، ثم يقدم لهم المُعزون ويُسلِّمون عليهم واحدًا واحدًا، ما حكم هذه الصِّفة؟ وهل لها أصلٌ في الشريعة؟ ثم ما الكيفية التي يُعزَّى بها أهلُ الميت عند المقبرة؟","title":"ما حكم الاصطفاف عند القبر للتعزية؟","answer":"الجواب: ما نعلم في هذا أصلًا، ولكن الأمر فيه سهلٌ، الناس يُعزُّون، سواء عند المقبرة، أو في الطريق قبل الدفن، أو بعد الدفن في المسجد، في الطريق، في البيت، في أي مكانٍ، التَّعزية أمرها واسعٌ.\nأما كونهم يصفُّونهم صفًّا حتى يُعرفوا، حتى يقصدهم المعزُّون؛ فلا نعلم له أصلًا، لكن الأمرَ فيه خفيفٌ؛ لأنَّ المطلوب التَّسهيل على الناس حتى لا يذهبوا ويدوروا عليهم في بيوتهم يُعزُّونهم، فإن وجدوهم عند المقبرة قريبين فيُعزُّونهم ويستريحون من التَّعب الكثير، فالأمر في هذا فيما يظهر لي أنه ليس بالشَّديد، الأمر فيه واسعٌ إن شاء الله.\nس: ما هو بدعة؟\nالشيخ: ما أعلم فيه شيئًا، لكن لو تُرك يكون حسنًا إن شاء الله، وإلا ما أعلم أنه يعني: أصل معروف، وإنما هذا تسهيلٌ للتَّعزية، والتعزية مشروعة، يُسهلون لهم بهذا التَّعزية، والتعزية مشروعة.","link":"https://binbaz.org.sa/fatwas/20715/ما-حكم-الاصطفاف-عند-القبر-للتعزية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0603حكم التعزية في المقبرة؟ ابن باز فتاوى المحاضرات.mp3","categories":["أحكام التعزية"]},{"id":904,"question":"ما حكم قراءة القرآن عند العزاء؟","title":"ما حكم قراءة القرآن عند العزاء؟","answer":"الجواب: ليس له أصلٌ، ولا نعلم له أصلًا، لكن إذا وقع صدفةً من غير قصدٍ -إذا اجتمعوا وقرأ واحدٌ منهم- فلا بأس، أما أن يُتَّخذ لهذا نظامٌ فهذا ليس له أصلٌ في العزاء، لا وجود القرَّاء، ولا إيجاد المآكل والمطاعم، ولا غير ذلك. لكن أهل الميت إذا نزل بهم الضيفُ لا بأس أن يُكرموه، أو جاءتهم أطعمةٌ كثيرةٌ ودعوا إليها مَن يأكلها لا بأس، أما أن يُقيموا مأتمًا لأجل الميت، فيذبحوا الذَّبائح لأجل الميت، ويدعوا القرَّاء لأجل الميت، هذا ليس له أصلٌ، بل هو من البدع التي أحدثها الناسُ، أما كونهم اجتمعوا وجلسوا في مكانٍ يتذاكرون، أو يُعزِّي بعضُهم بعضًا، وقرأ أحدُهم بعض الآيات، هذا طيبٌ.","link":"https://binbaz.org.sa/fatwas/20939/ما-حكم-قراءة-القران-عند-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0735ما حكم قراءة القرآن عند العزاء؟ ابن باز فتاوى المحاضرات.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":976,"question":"عندما يتوفى المتوفى يقوم أهله بلبس اللباس الأسود، فما رأيكم في ذلك؟","title":"ما حكم لبس الأسود من أهل الميت؟","answer":"الشيخ: لا يجوز هذا إلا لثلاثة أيام فقط، يجوز الإحداد ثلاثة أيام لأخواته وأمه ونحو ذلك، من لباس الخشن، وعدم الطيب. أما المرأة فتحدّ أربعة أشهر وعشرًا، المرأة عليها أن تحدّ أربعة أشهر وعشرًا، اللباس الذي ليس بجميلٍ، الملابس غير الجميلة، ولا يتعين كونها سوداء، سوداء، أو خضراء، ولكن ما هي بجميلة، مع ترك الطيب، وترك الحُلي من الذهب والفضَّة والماس ونحو ذلك، وترك الحناء والكحل، هذا هو الواجب على المحادة. أما أخواته وأمه ونحو ذلك فليس لهن إحداد إلا ثلاثة أيام فقط، سُئل النبيُّ عن هذا عليه الصلاة والسلام فقال: لا تحدّ امرأةٌ على ميتٍ فوق ثلاثٍ، إلا على زوجٍ: أربعة أشهر وعشرًا، فالأخت والأم ونحو ذلك لهن ثلاثة أيام فأقلّ.","link":"https://binbaz.org.sa/fatwas/21034/ما-حكم-لبس-الاسود-من-اهل-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0831ما حكم لبس الأسود من اللباس في العزاء؟ ابن باز فتاوى المحاضرات.mp3","categories":["أحكام التعزية"]},{"id":999,"question":"كذلك يقوم البعض بعملٍ ثالثٍ: أن يقوم أهلُ المتوفى بعمل وليمةٍ في اليوم الثالث، يجتمع فيها أقارب المتوفى، حتى إن أقارب المتوفى غالبًا ما يحضرون الأيام الأولى، فيرون أن يوم الثالث هو يوم الحضور للتعزية، وكأنَّهم يحضرون حفلة زفافٍ بسبب تصرُّفاتهم في ذلك، فما رأي فضيلتكم وفَّقكم الله؟","title":"ما حكم عمل أهل الميت وليمة باليوم الثالث؟","answer":"الجواب: هذا لا يجوز، وكتبنا فيه كتابات كثيرة، وعُمِّمت بواسطة الدُّعاة، فلا يجوز الاحتفال بالموت، ولا صنع الطعام من أهل الميت للناس يوم الموت، أو يوم ثالث، أو يوم عاشر، أو على رأس الأربعين، أو على رأس الحول، كل هذا من الأعمال الجاهلية، لا يجوز إلا طعامه العادي، يصنعون طعامًا لهم عاديًّا، أو لمن ينزل بهم من الضيوف، طعامًا عاديًّا من أجل الضيف، أما من أجل الميت فلا.\nلكن يُشرع لأقاربهم وجيرانهم أن يصنعوا لهم طعامًا يهدونه إليهم أيام المصيبة، كما قال النبيُّ ﷺ لأهله لما جاء نعي جعفر بن أبي طالب وأنه قُتِلَ في مؤتة في الشام، أمر أهله ﷺ أن يصنعوا لآل جعفر طعامًا، قال: اصنعوا لهم طعامًا فقد أتاهم ما يشغلهم، فإذا صنع أقاربُ الميت أو جيرانه لأهل الميت طعامًا وبعثوه إليهم لأنَّهم مشغولون عن صنع الطعام بالمصيبة فلا بأس، وأهل الميت إذا جاءهم الطعام لا بأس أن يدعوا إليه جيرانهم ليأكلوا معهم، أو بعض أقاربهم؛ لأنهم قد يأتون بطعامٍ كثيرٍ يزيد على حاجاتهم، فإذا دعوا إليهم مَن يأكل معهم فلا بأس، أما أنهم يصنعون طعامًا هم من أجل الميت فلا يجوز، نعم.","link":"https://binbaz.org.sa/fatwas/21035/ما-حكم-عمل-اهل-الميت-وليمة-باليوم-الثالث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0832ما حكم عمل أهل المتوفى وليمة في اليوم الثالث؟ ابن باز فتاوى المحاضرات.mp3","categories":["أحكام التعزية"]},{"id":1901,"question":"الثناء على الميت بعد العزاء في المجالس؟","title":"حكم الثناء على الميت في مجلس العزاء","answer":"الجواب:\nإذا ذكره بصفاته الحميدة جبرًا للناس، جبرًا لأهله أنه كان على خير، وأنه صوَّام قوَّام، وأنه داعٍ إلى الله، يُرجى له الخير إن شاء الله، اطمئنُّوا؛ من باب الطُّمأنينة للأقارب والتبشير لهم؛ فهذا لا بأس به.\nس: ما فيه شيء؟\nج: ما فيه شيء، لكن لا يُكثر، لا يُسْهِب.","link":"https://binbaz.org.sa/fatwas/22012/حكم-الثناء-على-الميت-في-مجلس-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الثناء على الميت.mp3","categories":["أحكام التعزية"]},{"id":2631,"question":"إنسان تُوفى له أحد من أقاربه يأتون الأقارب في داره ثم يأتي بقية أقربائه والأصدقاء؟","title":"حكم صنع أهل الميت الطعامَ للمعزِّين","answer":"سُنَّة، يأتون يعزونه.\nس: يعملون فطوراً؟\nالشيخ:إذا قهواهم، أو جاؤوا مِن مكان بعيد وعشّاهم وغدّاهم؛ ما يخالف.\nس: هذا ما يُعتبر من... ما فيه مَنْع؟\nالشيخ: لا ما فيه شيء، إذا جاء الضيف يُكْرَم الضيف. أما أهل الميت يُعِدُّون طعامًا للناس؛ لا، لا يُعِدُّون طعامًا للناس، لكن إذا جاء ضيف مِن بعيد يكرمونه ولو أقام عندهم مائة يوم.","link":"https://binbaz.org.sa/fatwas/22766/حكم-صنع-اهل-الميت-الطعام-للمعزين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بعض أحكام التعزية.mp3","categories":["أحكام التعزية"]},{"id":3080,"question":"امرأة تسأل: توفي زوجها وهي في بيت الحداد، بعض الأخوات يُرِدْن أن يدخلن إليها، مجموعة من النساء يُرِدْن أن يعملوا في بيتها ذِكرى، أحدٌ يتحدث في الدين.يقول: هل هذا الكلام مشروع أو غير مشروع؟","title":"حكم إقامة جلسة للذِّكرى في بيت العزاء","answer":"الجواب: إن كان من أجل العزاء ما له أصل، إن كان يأتون يعملون عزاء من أجل الموت ما يصلح، أما إذا كانوا محتاجين البيت يصنعون طعامًا لهم ولضيوفهم؛ فلا بأس، إذا كان الجيران محتاجين للبيت؛ بيتهم كسيف صغير ويحتاجون لبيت المحادة يطبخون فيه طعامًا لضيوفهم فلا بأس، هذا من باب التعاون.\nس: يعملون فيها ذِكرى، يعني واحد يتحدث وكذا؟\nالشيخ:من أجل الميت أو من أجل أيش؟ الذكرى ويش هي له؟\nالطالب: والله ما أدري هم يقولون هكذا.. يريدون: هل هذا الكلام مشروع أو غير مشروع؟\nالشيخ: لا ما هو بمشروع، أما إذا كان عازمًا أحد إخوانهم لوليمة وأحب أن يذكّر بعضهم بعضًا لا بأس.\nالطالب: أما هذا لا؟\nالشيخ: أما إيجاد ذِكرى ما لها أسباب ما يصلح، جرير  قال: (كنا نعد الاجتماع إلى الميت وصناعة الطعام بعد الموت من النياحة). أما إذا كان لها أسباب؛ إنسان يعزم إخوانه، جايين من سفر، أو قام من مرض، أو يعزم إخوانه يحط لهم وليمة في بيت المحادة؛ لأن بيتهم كسيف وصغير؛ هذا من باب التعاون.","link":"https://binbaz.org.sa/fatwas/23240/حكم-اقامة-جلسة-للذكرى-في-بيت-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إقامة ذكرى في بيت العزاء.mp3","categories":["أحكام التعزية"]},{"id":3082,"question":"اجتماع الأقارب للتعزية في البيت؟","title":"حكم الاجتماع في البيت للتعزية","answer":"الجواب: لا، ما له أصل، كُلٌّ يُعَزّي ويَرُوح، يجيهم يُعَزّي ويروح، تجمع مخصوص ما له أصل، لكن يزورهم أخوهم عمهم خالهم يعزّيهم، دعاهم؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/23242/حكم-الاجتماع-في-البيت-للتعزية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاجتماع في البيت للتعزية.mp3","categories":["أحكام التعزية"]},{"id":3387,"question":"يُصلى على المرأة الحائض في المسجد؟","title":"هل يُصَلّى على الحائض بالمسجد إذا ماتت؟","answer":"الجواب: نعم، لا بأس، النبي ﷺ صلى على النساء في المسجد ولم يسأل.","link":"https://binbaz.org.sa/fatwas/23555/هل-يصلى-على-الحاىض-بالمسجد-اذا-ماتت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُصَلّى على المرأة الحائض في المسجد إذا ماتت.mp3","categories":["المساجد ومواضع السجود","زكاة النقدين","الصلاة على الميت","أحكام التعزية"]},{"id":3484,"question":"هل يجوز السفر من أجل التعزية لو كان قريبًا أو غير قريب؟","title":"هل يجوز السفر من أجل التعزية؟","answer":"الجواب: لا بأس أن يسافر من أجل التعزية أو يصلي على الميت، لا بأس.","link":"https://binbaz.org.sa/fatwas/23661/هل-يجوز-السفر-من-اجل-التعزية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السفر من أجل التعزية.mp3","categories":["أحكام التعزية"]},{"id":5130,"question":"سائل يقول: هل من النياحة اجتماعُ أهل الميت في بيتٍ واستقبالهم للناس ثلاثة أيام؛ تسهيلًا على الأقرباء؟","title":"حكم اجتماعُ أهل الميت في بيتٍ للتعزية ثلاثة أيام","answer":"الجواب: النياحة لا تجوز، لكن إذا جلس في البيت لاستقبال المُعزِّين فلا بأس، فيجلس في البيت في أوقاتٍ مناسبةٍ حتى يزوره أقاربه وغيرهم من المُعزين، لا بأس بذلك، لكن لا يحتفلون بطعام الميت، فيذبحون للناس، أو يصنعون طعامًا للميت، لا، هذه بدعة، لا أصل لها. لكن إذا جلس صاحبُ البيت في الأوقات المناسبة بين المغرب والعشاء، أو ضُحًى، أو غير ذلك؛ ليزوره إخوانه فيُعزونه، حتى لا يشقَّ عليهم، أو عزَّوه في الطريق، أو في المقبرة، أو في المسجد؛ كفى ذلك.","link":"https://binbaz.org.sa/fatwas/30045/حكم-اجتماع-اهل-الميت-في-بيت-للتعزية-ثلاثة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 66.mp3","categories":["أحكام التعزية"]},{"id":5131,"question":"سائلٌ يقول: ما حكم نشر العزاء في الصحف، ورده أيضًا في الصحف، وكتابة الآيات الكريمة التي فيها تزكية للميت؟","title":"هل يجوز نشر العزاء في الصحف؟","answer":"الجواب: في الصحف فيما بلغني أنه يُكلِّف كثيرًا، ويُخشى من التَّكلف، ومن النفقات الطائلة بلا حاجةٍ، وإلا فلو كتب: \"أحسن الله عزاء آل فلان في ميتهم، وغفر الله له\" ما يضرُّ، لكن بلغني أنه تكون فيه كُلفة، فتركه أوْلى إذا كانت فيه كُلفة، فيُرسل لهم رسالةً أو برقيةً ويكفي، إذا كانت هناك مشقة ونفقات في النشر في الجريدة، وليس من النَّعي الذي نهى عنه النبيُّ ﷺ. والنعي الذي نهى عنه النبيُّ ﷺ أنه كان أهل الجاهلية إذا مات ميتٌ أركبوا إنسانًا يطوف بين القبائل ينعى إليهم ميتهم، هذا من عمل الجاهلية، أما إذا كتب كتابًا يُعزيه، أو كتب في الجريدة: \"أحسن الله عزاء آل فلان\"، فلا بأس، لكن إذا كان يُكلِّف وفيه مؤونة فينبغي تركه؛ لأن الرسول ﷺ نهى عن إضاعة المال، وهذا من إضاعة المال، ويكفي كتابة خطٍّ إليهم، أو برقية، أو مكالمة هاتفية تكفي.","link":"https://binbaz.org.sa/fatwas/30046/هل-يجوز-نشر-العزاء-في-الصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 67.mp3","categories":["أحكام التعزية"]},{"id":5716,"question":"ما هي السنة إذا قيل للمصاب: \"إن لله ما أخذ، وله ما أعطى، وكل شيء عنده بأجل مسمى فلتصبر ولتحتسب\" فماذا يقول للمعزي؟","title":"كيفية إجابة المعزين","answer":"الجواب: يقول ما تيسر، ما في شيء محدود، إذا قيل له: أحسن الله عزاءك، أو قيل له: لله ما أخذ، وله ما أعطى، وكل شيء عنده بأجل مسمى، فاصبر واحتسب، يقول: أسأل الله أن يعينني، أسأل الله أن يوفقني، الحمد لله على كل حال، أي كلمة طيبة تناسب، ما في شيء محدود، ما نعلم في هذا شيئًا محدودًا.","link":"https://binbaz.org.sa/fatwas/1029/كيفية-اجابة-المعزين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_151.1.mp3","categories":["أحكام التعزية"]},{"id":5813,"question":"في بعض البلدان إذا مات الميت، ثم دفن يجتمعون في بيت الميت ثلاث ليال، يصلون ويدعون له، فما حكم هذا؟","title":"حكم اجتماع أهل الميت للصلاة والدعاء له","answer":"الجواب: سبق لكم في كلام الشيخين: أن الاجتماع في بيت الميت للأكل، والشرب، ولقراءة القرآن أن هذا بدعة، وهكذا اجتماعهم يصلون له، ويدعون له، كله بدعة، لا وجه لهذا؛ إنما يؤتى لأهل الميت للتعزية، والدعاء لهم، والترحم على ميتهم، وتسليتهم، وتصبيرهم. أما أنهم يؤتون لإقامة مآتهم، وإقامة دعوات خاصة، وصلوات خاصة، وقراءة، فهذا لا أصل له، ولو كان خيرًا لسبقنا إليه سلفنا الصالح -رضي الله عنهم وأرضاهم- فالرسول ما فعله، وقد دفن جعفر بن أبي طالب، وعبدالله بن رواحة، وزيد بن حارثة في غزوة مؤتة، وجاءه الخبر -عليه الصلاة والسلام- جاءه الوحي بذلك، فنعاهم للصحابة، وأخبرهم بموتهم، وترضى عنهم، ودعا لهم، ولم يتخذ من هذا شيئًا -عليه الصلاة والسلام- لا جمع الناس، ولا اتخذ مأدبة، ولا جعل مأتم الأيتام أيام كل هذا ما فعله ﷺ وهؤلاء من خيرة الصحابة، ومن أفضل الصحابة.  مات الصديق، وما جعلوا مأدبة، وهو أفضل الصحابة، وقتل عمر ما جعلوا مأتمًا، ولا جمعوا الناس ينعون عليه، أو يقرؤون له القرآن، وقتل عثمان بعد ذلك، وقتل علي بعد ذلك، ولا جمع الناس لأيام معدودة بعد الوفاة بالدعاء لهم، والترحم عليهم لا، مثل ما سمعتم في الندوة.  ولكن يستحب لأقارب الميت، أو جيرانه أن يصنعوا طعامًا لأهل الميت، يبعثوا به إليهم، مثل ما فعل النبي ﷺ لما نعى جعفر، قال لأهله: اصنعوا لآل جعفر طعامًا فقد أتاهم ما يشغلهم فأهل الميت مشغولون بالمصيبة، فإذا صنع طعام، وأرسل إليهم، وكفوا المؤنة، هذا هو المشروع. أما أن يحملوا بلاء على بلائهم، ويكلفوا أن يصنعوا للناس طعامًا، فهذا خلاف للسنة؛ بل هو بدعة، قال جرير بن عبدالله البجلي : كنا نعد الاجتماع إلى أهل الميت، وصنع الطعام بعد الدفن من النياحة، فالصحابة يعدونه من النياحة المحرمة، والنياحة رفع الصوت، وهذا محرم، فلا يجوز، ويعد هذا من النياحة، والميت يعذب في قبره بما يناح عليهـ كما قاله النبي -عليه الصلاة والسلام- فيجب الحذر من ذلك، أما البكاء بدمع العين؛ فلا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/1136/حكم-اجتماع-اهل-الميت-للصلاة-والدعاء-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_142.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":5845,"question":"ظهر على شاشة التلفاز أحد العلماء، وسئل عن حكم الاحتفال بعيد الزواج؛ فأجاب بأنه لا بأس بذلك ما دام أن هذا الاحتفال لا يأخذ صفة دينية؟","title":"حكم الاحتفال بعيد الزواج ونحوه","answer":"الجواب: الاحتفالات بالأعياد كعيد الأم، وعيد الزواج، أو كذا، أو كذا، هذه منكرات، وحوادث، وبدع لا أساس لها. أما الاحتفال بالزواج نفسه، كأن يقيم وليمة الزواج؛ لأنه بنى بزوجته، أو عقد بها؛ فلا بأس، أما شيء يعتاد في ليلة من الزمان، كلما دار الحول على الزواج؛ يقيم عيدًا كل سنة، هذا منكر، من البدع التي أحدثها الناس، لا وجه لها، ولا أساس لها، أو يقيم عيدًا لولده إذا تمت السنة، هذا عيد فلان، وهذا عيد فلان، هذه ورثوها عن النصارى، واليهود، وأشباههم، ومشابهة لأعداء الله، فلا يجوز هذا، بل هو منكر. ومن أفتى بجوازه؛ فقد غلط، سواء سمي دينًا، أو ما يسمى دينًا؛ فإن الشيء قد يسمى عبادة، وقد لا يسمى عبادة، لكن يمنع؛ لأن فيه تشبهًا بأعداء الله، والنبي -عليه الصلاة والسلام- يقول: من تشبه بقوم فهو منهم فلا يجوز لنا أن نتشبه بأعياد الكفار.","link":"https://binbaz.org.sa/fatwas/1201/حكم-الاحتفال-بعيد-الزواج-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_197.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":5859,"question":"ظهر على شاشة التلفاز أحد العلماء، وسئل عن حكم الاحتفال بعيد الزواج؛ فأجاب بأنه لا بأس بذلك ما دام أن هذا الاحتفال لا يأخذ صفة دينية؟","title":"حكم الاحتفال بعيد الزواج ونحوه","answer":"الجواب: الاحتفالات بالأعياد كعيد الأم، وعيد الزواج، أو كذا، أو كذا، هذه منكرات، وحوادث، وبدع لا أساس لها. أما الاحتفال بالزواج نفسه، كأن يقيم وليمة الزواج؛ لأنه بنى بزوجته، أو عقد بها؛ فلا بأس، أما شيء يعتاد في ليلة من الزمان، كلما دار الحول على الزواج؛ يقيم عيدًا كل سنة، هذا منكر، من البدع التي أحدثها الناس، لا وجه لها، ولا أساس لها، أو يقيم عيدًا لولده إذا تمت السنة، هذا عيد فلان، وهذا عيد فلان، هذه ورثوها عن النصارى، واليهود، وأشباههم، ومشابهة لأعداء الله، فلا يجوز هذا، بل هو منكر. ومن أفتى بجوازه؛ فقد غلط، سواء سمي دينًا، أو ما يسمى دينًا؛ فإن الشيء قد يسمى عبادة، وقد لا يسمى عبادة، لكن يمنع؛ لأن فيه تشبهًا بأعداء الله، والنبي -عليه الصلاة والسلام- يقول: من تشبه بقوم فهو منهم فلا يجوز لنا أن نتشبه بأعياد الكفار.","link":"https://binbaz.org.sa/fatwas/1201/حكم-الاحتفال-بعيد-الزواج-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_197.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6111,"question":"يصنعون في بعض البلاد الإسلامية طعامًا يسمونه صدقة للميت، فهل يجوز الأكل منه؟","title":"حكم صناعة الطعام باسم الصدقة على الميت","answer":"الجواب: ما يعتاده بعض البلاد من المأتم، صدقة يسمونها المأتم، في يوم موته، أو في الرابع، أو في السابع، أو في الأربعين هذه بدعة، ما ينبغي أن .. ولا تجاب الدعوة؛ لأن إجابة الدعوة تشجع على البدع. فهذه المآتم التي يصنع فيها الطعام في أيام معدودة، يوم الميت، سواء كان يوم الموت، أو في اليوم السابع، أو في اليوم العاشر، أو في الأربعين، أو في السنة للميت الميت هذه بدعة، لا ينبغي أن يجيب إليها؛ لأن الإجابة إليها فيها نوع من التشجيع على البدع.","link":"https://binbaz.org.sa/fatwas/1540/حكم-صناعة-الطعام-باسم-الصدقة-على-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_470.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6186,"question":"بعض الذين يقيمون الموالد، ويحتفلون بليلة الإسراء، والمعراج، يقولون: نحن نقصد الذكر، والصلاة على الرسول، ويقولون: إن العلماء لم ينكروا على الاحتفال باليوم الوطني، وغيره من هذا القبيل، فكيف نعترض على المولد؟","title":"شبهة في الاحتفال بالمولد والرد عليها","answer":"الجواب: يقال لهم: إن الرسول ﷺ وأصحابه أحرص منكم، وأرغب في الخير، وأولى بكل فضيلة، فلو كان الاحتفال بالموالد، أو بالإسراء، والمعراج أمرًا مشروعًا، وقربة إلى الله  لكانوا إليه أسرع، لكانوا إليه أسبق، وكانوا به أولى، وقد قال -عليه الصلاة والسلام-: إياكم ومحدثات الأمور وقال: شر الأمور محدثاتها، وكل بدعة ضلالة وليس للناس أن يحدثوا بآرائهم عبادات.  فإذا قالوا هذه المقالة؛ أمكن غيرهم أن يقول أيضًا: نحدث صلاة سادسة، ما أردنا إلا الخير، والذكر، نحدث صلاة سادسة، الضحى فريضة، ندعو الناس إليها أربع ركعات، أو ركعتين، تصلى جماعة سادسة، زيادة في الخير، والفضل. أو يقول آخر: يمكن أن نحدث أيضًا عبادة أخرى، وهو أن نحج في العام مرتين، ما يكفي حج واحد، نحج في العام مرتين، فهذا زيادة فضل، وذكر، وطاعة لله، وطواف، وشبه ذلك، والآخر يقول: نحدث أذانين لكل فريضة، الأذان الواحد ما يكفي؛ لأنه ذكر، وطاعة لله، فيؤذن مرتين في كل مسجد؛ لأن هذا زيادة ذكر، أو يقيم مرتين، أو ثلاثًا، أو يؤذن أربع مرات، أو عشر مرات؛ لأن هذا مزيد ذكر، وطاعة لله. فمعنى هذا: أن يكون الدين على الأهواء، والتلاعب بآراء الناس، ومحدثاتهم، وأفكارهم الضالة، والكاسدة، هذا شيء لا حد له، وهذا هو الذي وقع في اليهود والنصارى حتى تلاعبوا بدينهم، واستحسنوا ما لم يشرعه الله  لهم. وأما ما يتعلق باليوم الوطني، فهذا ليس من العبادات؛ بل هذا اخترعوه لأمور أخرى سياسية، ليس من باب العبادات، ولكنه قد ينهى عنه من جهة أنه تشبه باليهود، والنصارى بما أحدثوا من الأيام الوطنية، وأشباهها، والأعياد، فهذا من باب السياسة، ومن باب التشبه بالمشركين فيما أحدثوا من أعياد وطنية، وليس من باب العبادة، بل من باب الأمور السياسية التي أحدثها بعض الناس؛ تقليدًا لغيره، وتشبهًا بمن فعله من الكفرة، فهو ممنوع يجب منعه لما فيه من التشبه بأعداء الله.","link":"https://binbaz.org.sa/fatwas/1654/شبهة-في-الاحتفال-بالمولد-والرد-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_538.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6380,"question":"ما حكم من يقرأ الفاتحة لله، ثم على روح النبي ﷺ؟","title":"حكم قراءة الفاتحة لله وإلى روح النبي عليه الصلاة والسلام","answer":"الجواب: لا أصل له، هذا النبي ﷺ له مثل أجورنا -عليه الصلاة والسلام- ولم يفعله الصحابة، وهم خير الناس؛ فلا تقرأ الفاتحة على النبي ﷺ ولا على غيره، ولكن تصلي عليه كثيرًا -عليه الصلاة والسلام- تصلي عليه كثيرًا، وتجتهد في اتباع سنته، وتعظيم أمره، ونهيه، والمسارعة إلى ما شرع، كما قال الله سبحانه: قُلْ إِن كُنتُمْ تُحِبُّونَ اللّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ [آل عمران:31].  فالمشروع فعل ما شرع لك من: الصلوات، والزكوات، والصيام، والحج، والأمر بالمعروف، والنهي عن المنكر، والجهاد في سبيل الله، وبر الوالدين، وصلة الرحم، والإكثار من ذكر الله، والصلاة والسلام على رسول الله -عليه الصلاة والسلام- هذا المشروع، أما أن تقرأ الفاتحة، أو يس، أو الأعراف، أو كذا فهذا ما هو مشروع.","link":"https://binbaz.org.sa/fatwas/1956/حكم-قراءة-الفاتحة-لله-والى-روح-النبي-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_743.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6535,"question":"ما حكم الاحتفال باليوم الوطني، وكذلك أيضًا أسبوع الإمام محمد بن عبدالوهاب، وإذا كانت ليست بدعة فما الفرق بينها، وبين البدع؟","title":"حكم الاحتفال باليوم الوطني والأسابيع الدعوية","answer":"الجواب: العيد الوطني بدعة، العيد الوطني بدعة، أما أسبوع العلماء ليس من البدع، هذا أسبوع تعرض فيه كتبهم، ما هو باحتفال، هذا أسبوع تعرض فيه الكتب، إذا قيل أسبوع لكتاب كذا، وأسبوع لكتاب كذا، والأسبوع الذي بعده كذا، والأسبوع الذي بعده كذا، ليس هذا احتفالًا، هذا معرض للكتب، وبيان ما ألفه فلان وما طبع من كتبه، فإذا قيل أسبوع لمحمد، وأسبوع لشيخ الإسلام، وأسبوع للعز بن عبدالسلام، وأسبوع للقرطبي، وأسبوع لكذا، تعرض كتبهم، وتباع بين الناس، ليس هذا بابتداع، هذا إظهار للكتب، وبيع لها، ونشر لها بين الناس . أما اليوم الوطني، والاحتفال بيوم وطني، أو في أي يوم، أو في ليلة الرغائب، كل هذا بدعة، كلها من البدع، ومن التشبه بأعداء الله.","link":"https://binbaz.org.sa/fatwas/2365/حكم-الاحتفال-باليوم-الوطني-والاسابيع-الدعوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_899.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6540,"question":"سماحة شيخي، ما هي الشبه التي يوردها من يقول بسنية أعياد الموالد، وخاصة مولد الرسول ﷺ؟","title":"شبهة من يحتفلون بالموالد والرد عليها","answer":"الجواب: شبهتهم التأسي بأعداء الله، التأسي باليهود، والنصارى، هؤلاء يفعلونه يفعلونه مثلهم، لماذا نعظم نبينا مثل تعظيمهم بالموالد، نبينا معظم -بحمد الله- بما شرعه لنا ربنا على يديه -عليه الصلاة والسلام،- فنعظمه بالصلاة عليه، واتباع سنته، والشهادة له بالرسالة -عليه الصلاة والسلام- والدعوة إلى دينه، والتحذير من مخالفته -عليه الصلاة والسلام- من هذه البدع، وإحداث الموالد.","link":"https://binbaz.org.sa/fatwas/2366/شبهة-من-يحتفلون-بالموالد-والرد-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_900.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6572,"question":"وفي قصاصة من مجلة الأخبار المصرية بتاريخ 17/12/83 الاحتفال بمولد النبي ليس بدعة، يقول البعض: إن الاحتفال بالمولد النبوي بدعة، وحجتهم في ذلك: أن النبي -عليه الصلاة والسلام- أو أحد صحابته الكرام لم يحتفلوا بهذه المناسبة، ووجهت هذا السؤال إلى فضيلة الشيخ عطية صقر عضو مجمع البحوث الإسلامية، وتلقيت منه الجواب الآتي: علينا أن نحدد معاني الألفاظ التي نعطيها حقها في الحكم، سواء بالصحة، أو البطلان، لفظ بدعة فهمه البعض على أنه كل شيء مستحدث، بصرف النظر عن كونه نافعًا، أو ضارًا، لفظ البدع ورد في بعض الأحاديث موصوفًا بأنها ضلالة، وتعني كل مستحدث في الدين، ولكنها في الموضوع الذي نحن بصدده معناها لغوي، أي الشيء المبتدع الذي على غير مثال سبق، وبذلك الفهم نتلافى التضارب الموجود في بعض المنقولات إلى آخر المقالة؟","title":"الرد على من ينفي بدعية الاحتفال بمولد النبي","answer":"الجواب: هو اعترف بما يدل على المقصود، الحديث جاء كل بدعة ضلالة فيكون الاحتفال بالمولد ضلالة؛ لأنه بدعة في الدين، ما فعلها الرسول ﷺ ولا أصحابه، ولا القرون المفضلة القرن الأول، والثاني، والثالث، فيكون بدعة ضلالة. وحب الرسول ﷺ لا يكون بالاحتفال، يكون بطاعته، واتباع شريعته، ودراسة ما جاء عنه، والتفقه في دينه، لا بالبدع التي أنكرها العلماء، وأحدثها الجهلة، أو أحدثها الرافضة، أو أشباههم، فالاحتفال بالموالد من بدع الرافضة، أول من أحدثها الرافضة الفاطميون، ثم تبعهم بعض الناس على ذلك، فهذا بدعة في الدين، ومشابهة للنصارى، واليهود، والرافضة فيما عملوا، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/2390/الرد-على-من-ينفي-بدعية-الاحتفال-بمولد-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_921.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6611,"question":"توجد لدينا عادة جارية حتى الآن، عندما ينتهي الإمام من صلاة المغرب يجلس الإمام، ومعه جماعة من الإخوان، ويقرؤون معًا بصوت واحد سورة يس، وسورة تبارك، وآية الكرسي بين وقت المغرب والعشاء، فما حكم ذلك، نرجو الإفادة؟","title":"حكم قراءة يس والملك وآية الكرسي بعد الصلوات","answer":"الجواب:  هذا بدعة لا أصل له، يجلسون بعد صلاة المغرب، الإمام، وجماعة بصوت واحد، يقرؤون سورة يس، وسورة تبارك، وآية الكرسي، هذا بدعة، حتى ولو قرأ سورة الفاتحة.. لا أصل له في الشريعة. السنة بعد الصلاة أن يقول المؤمن: أستغفر الله ثلاثًا، اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال، والإكرام، هذا أول شيء، ثم ينصرف الإمام إلى الناس، ثم يقول كل واحد: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبد إلا إياه، له النعمة، وله الفضل، وله الثناء الحسن، لا إله إلا الله مخلصين له الدين، ولو كره الكافرون، اللهم لا مانع لما أعطيت ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد، ثبت هذا عن رسول الله ﷺ أنه كان يقول إذا سلم في الظهر، والعصر، والمغرب، والعشاء، والفجر، ويزيد بعد ذلك في الفجر، والمغرب: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، يحيي، ويميت، وهو على كل شيء قدير عشر مرات. وجاء عنه ﷺ الحض، والتحريض، والتعليم أن يقول بعد ذلك: سبحان الله، والحمد لله، والله أكبر، ثلاثًا وثلاثين مرة، علمه فقراء المهاجرين، ثم تعلمه الجميع، سبحان الله، والحمد لله، والله أكبر ثلاثًا وثلاثين مرة، وفي حديث أبي هريرة عند مسلم، ويقول تمام المائة: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير فيصير الجميع مائة، إذا قالها؛ غفرت خطاياه، وإن كانت مثل زبد البحر. وقال في حديث أبي هريرة في الصحيحين لما جاءه الفقراء من المهاجرين، قالوا: يا رسول الله، ذهب أهل الدثور -يعني أهل الأموال- بالأجور يصلون كما نصلي، ويصومون كما نصوم، ويتصدقون، ولا نتصدق، ويعتقون، ولا نعتق، ما عندنا أموال؟ قال: أفلا أدلكم على شيء تدركون به من سبقكم، وتسبقون من بعدكم، ولن يكون أحد أفضل منكم إلا من صنع مثلما صنعتم قالوا: بلى يا رسول الله، قال: تسبحون، وتحمدون، وتكبرون دبر كل صلاة ثلاثًا وثلاثين مرة هكذا في الصحيحين .. -عليه الصلاة والسلام- وفي مسلم، ويقول تمام المائة: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير فرجع الفقراء يقولونها بعد كل صلاة، ثم رجعوا إليه، فقالوا: يا رسول الله، سمع إخواننا أهل الأموال ما فعلنا، ففعلوا مثله -يعني صاروا يسبحون، ويحمدون، ويكبرون مثله- قال النبي ﷺ: ذلك فضل الله يؤتيه من يشاء إذا رزقه الله المال، وأنواع الذكر، والعبادة هذا فضله  يؤتيه لمن يشاء، والله ذو الفضل .  وعلمهم آية الكرسي بعد كل صلاة اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] فقد ثبت فيها الحديث، وهكذا قُلْ هُوَ اللَّهُ أَحَدٌ[الإخلاص:1] وقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1] وقُلْ أَعُوذُ بِرَبِّ النَّاسِ [الناس:1] بعد كل صلاة، وفي صلاة المغرب، والفجر زيادة، يقرأ قل هو الله أحد، والمعوذتين ثلاث مرات، هذا هو المشروع بعد الصلوات، وإذا دعا .. دعوات بينه وبين نفسه؛ فلا بأس من دون رفع اليدين، فقد جاء الدعاء بعد الصلاة عنه عليه الصلاة والسلام. أما أنه يقرأ الإمام، والجماعة بصوت واحد، يقرؤون هذا لا أصل له، بل هو بدعة، وهكذا رفع أيديهم بالدعاء بعد الصلوات الخمس بدعة أيضًا، وإنما السنة ما سمعتم من فعل النبي ﷺ وتعليمه عليه الصلاة والسلام.\n... هذا دعاء طيب، لكن الأفضل قبل السلام، علمه النبي معاذ بن جبل، يكون قبل السلام أفضل، وإن دعا به بعد السلام فلا بأس: اللهم أعني على ذكرك، وشكرك، وحسن عبادتك. كذلك: اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني إنك أنت الغفور الرحيم، اللهم اغفر لي ما قدمت، وما أخرت، وما أسررت، وما أعلنت، وما أسرفت، وما أنت أعلم به مني، أنت المقدم، وأنت المؤخر لا إله إلا أنت، اللهم إني أعوذ بك من البخل، وأعوذ بك من الجبن، وأعوذ بك أن أرد إلى أرذل العمر، وأعوذ بك من فتنة الدنيا، وأعوذ بك من عذاب القبر، كل هذا الأفضل فيه قبل السلام، في آخر التحيات، وإن دعا ببعض هذا بعد السلام؛ فلا بأس، لكن بينه، وبين نفسه، من دون صوت جماعي، من دون رفع الأيدي مع الإمام، كل هذا لا يفعل، بس دعاء بينه، وبين نفسه، وبينه وبين ربه.","link":"https://binbaz.org.sa/fatwas/2456/حكم-قراءة-يس-والملك-واية-الكرسي-بعد-الصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_983.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6612,"question":"هل الأذان، والإقامة عند قبر الميت مشروع؟ وهل قراءة القرآن على القبر، أو في بيت الميت الثلاثة أيام له أصل من قرأ، أم لا؟","title":"حكم الأذان والإقامة في القبر وقراءة القرآن في بيت الميت","answer":"الجواب: هذه بدعة ما لها أصل، بعض الناس يأذن في القبر، أو يقيم في القبر، هذه بدعة ما لها أصل، أو يقرأ فيه، بعض القراءة هذه بدعة ما لها أصل، كذلك التجمع في بيت الميت، ويقرؤون فيه أيامًا وليالي، هذه بدعة ما لها أصل. السؤال: هذا منتشر في المقبرة، ولا هناك من يرشدهم؟ الجواب: لا، ينبهون الدعاة، والهيئة -إن شاء الله- تلاحظ، وأنت واحد من الناس إذا شفته؛ أنكر عليه -جزاك الله خيرًا- أنت واحد من الإخوان، تقول لهم: هذا بدعة، وهذا لا يجوز، لأن الدعوة إلى الله ما هي خاصة بأحد دون أحد، من علم شيئًا يبين للناس، والهيئة كذلك، فالواجب التساعد، والتعاون على البر، والتقوى.","link":"https://binbaz.org.sa/fatwas/2440/حكم-الاذان-والاقامة-في-القبر-وقراءة-القران-في-بيت-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_967.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6636,"question":"ما رأي سماحة الشيخ في تقسيم البدع، كالبدع المستحبة، والبدع المحرمة، ووجه دليل من قال بهذا التقسيم، مع بيان قول الرسول ﷺ: كل بدعة ضلالة؟","title":"حكم تقسيم البدع","answer":"الجواب: ذهب بعض الناس -بعض الفقهاء من المتأخرين- إلى تقسيم البدعة إلى حسنة، وسيئة، وواجبة، ومحرمة، ومباحة، وهذا لا أصل له، هذا التقسيم لا أصل له، فليس في البدع شيء حسن، كلها ضلالة، النبي ﷺ قال: كل بدعة ضلالة فلا يجوز الاعتراض على الرسول ﷺ فالذي يقسمها يقول: بعضها ضلالة، وبعضها ما هو ضلال، معترض على الرسول ﷺ أتى النبي ﷺ بعبارة جامعة، قال: كل بدعة ضلالة فهذا كلام عام جامع، لا يجوز أن يعترض عليه.  وأما ما يظن بعض الناس أنه بدعة، وهو مما شرعه الله، ليس ببدعة، مثل بناء المساجد ليس بدعة ... -عليه الصلاة والسلام- وكذلك نقط المصاحف، وتشكيلها من باب الإيضاح لكلام الله، ليس من البدع، فمن باب الإيضاح لكلام الله، وبيان ما هو مرفوع، وما هو منصوب؛ لأن بعض العامة لا يحسن ذلك، وقد تشتبه عليه بعض الكلمات إذا لم تنقط، وكذلك جمع المصاحف، وكذلك بناء المدارس، كل هذا ما هو من البدع، بل مما شرع الله، ومما دعا إليه رسول الله ﷺ لأن الله أمرنا أن نحفظ كتابه، وأن نعلم أولادنا، وهذا من باب التعليم، والإيضاح، وليس هذا من البدع، هكذا إيجاد الربط، والأوقاف ليس من البدع، بل من باب الصدقات الجارية، والنبي ﷺ قال: لو مات ابن آدم؛ انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له فإذا أوقف الناس بيوتًا على الأئمة، أو المؤذنين، أو الأربطة، أو غير ذلك للتدريس، والتعليم، والغرباء، والفقراء، والمساكين، هذا من العمل الصالح، والصدقات الجارية الداخلة فيما حث عليه النبي ﷺ من نفع الناس، وإرشادهم، والصدقة عليهم، ومواساتهم، ورحمتهم، هذا كله تشبيه لا وجه. السؤال: وقول: (نعمت هذه البدعة)؟ الجواب: هذا يروى عن عمر، جاء عن عمر في مسألة التراويح من حيث اللغة، مثل ما قال: بَدِيعُ السَّمَاوَاتِ [البقرة:117] يعني من حيث اللغة، أنه جمعهم على إمام، ولم يكونوا مجموعين على إمام سابق في التراويح، وصلى بهم ﷺ ثلاث ليالي، أو أربع، ثم تركهم خوفًا أن تفرض عليهم، فجمعهم عمر على إمام واحد، وخرج ذات ليلة، وهم يصلون، فقال: (نعمت هذه البدعة).  فالمعنى يعني من حيث اللغة، أما هو يعرف أنها سنة، ولهذا فعلها ودعا إليها، وفعلها الرسول ﷺ فهي سنة بلا شك، هي سنة، وقربة، ليست بدعة في الدين، ولكن من في قلبه مرض يتعلق بهذه الكلمة، ولو كانت في غير صفه لما تعلق بها.","link":"https://binbaz.org.sa/fatwas/2475/حكم-تقسيم-البدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1002.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6670,"question":"أنا شاب أعزب، ومتدين -ولله الحمد- ولكني إذا جئت أتوضأ للصلاة أترجل في إخراج اسم الله عند الوضوء، وأتكلم بالنية في نفسي، فمثلًا، أقول: أتوضأ لصلاة كذا داخل نفسي، ولكن في الآونة الأخيرة صار بيني، ما أدري ماذا يقصد؟","title":"حكم التلفظ بالنية قبل الوضوء","answer":"الجواب: ما يحتاج يا ولدي التكلم بالنية، قلبك يكفي، ما دمت قمت للوضوء، فالنية كافية، أما قول: نويت أن أتوضأ لصلاة الظهر هذه بدعة ما لها أصل، النية في القلب يكفي، الأعمال بالنيات، النية في القلب، والتلفظ بها بدعة، فلا حاجة إلى أن تقولها في نفسك، والتسمية باللسان تقول: بسم الله عند الوضوء، بسم الله، ثم تتوضأ، يعني تبدأ بالمضمضة، والاستنشاق، ونحو ذلك، أو عند غسل يديك ثلاثًا، سمي الله، أما .. للوضوء ما حاجة، فالقلب يكفي، لكن القلب يكفي بنية الوضوء ونية الصلاة، ونية الصيام، ونية الحج يكفي، لكن يقال في الحج: لبيك كذا، وكذا.","link":"https://binbaz.org.sa/fatwas/2536/حكم-التلفظ-بالنية-قبل-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1031.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6679,"question":"حكم صنع الطعام لأهل الميت؟","title":"حكم صنع الطعام لأهل الميت","answer":"الجواب: .. لا يصنعون ولائم بعد الموت لا، أما كون جيرانه، أو أقاربه يدفعون لأهل الميت طعامًا فهذا مشروع، وقد ثبت عن النبي ﷺ أنه لما جاء نعي جعفر بن أبي طالب  لما قتل في الشام، أمر النبي ﷺ أهل بيته أن يصنعوا طعامًا لأهل بيت جعفر، فإذا صنع جيرانهم لهم طعامًا، أو بعض أقاربهم لهم طعامًا أيام المصيبة؛ فلا بأس، أما أهل الميت لا يصنعون طعامًا للناس، ولا يقيمون الولائم، قال جرير بن عبدالله البجلي  : \"كنا نعد الاجتماع إلى أهل الميت، وصنعة الطعام بعد الدفن كنا نعده من النياحة\".","link":"https://binbaz.org.sa/fatwas/2548/حكم-صنع-الطعام-لاهل-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1043.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6692,"question":"عندما يموت إنسان مسلم في بلادنا يدفع أهله مبلغًا من المال لشخص، أو أكثر؛ من أجل ختم القرآن للميت، ما رأي فضيلتكم في هذا؟","title":"حكم استئجار من يقرأ القرآن عن الميت","answer":"الجواب: هذا لا أصل له، كونهم يستأجرون من يقرأ القرآن للميت هذا لا أصل له، والقارئ لا أجر له؛ لأنه قرأ بالأجر، فلا أجر له، فلا يستحب هذا، ولا يشرع، وقد مضى النبي ﷺ والصحابة، ولم يفعلوه، وهم أسبق الناس إلى كل خير، وأسبقهم إلى كل طاعة، فلا يجوز كونه يستأجر من يقرأ للميت بعد الموت، أو جماعة يقرؤون أيام العزاء، هذا بدعة لا أصل له.","link":"https://binbaz.org.sa/fatwas/2546/حكم-استىجار-من-يقرا-القران-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1041.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6696,"question":"عندما يموت إنسان مسلم في بلادنا يدفع أهله مبلغًا من المال لشخص، أو أكثر؛ من أجل ختم القرآن للميت، ما رأي فضيلتكم في هذا؟","title":"حكم استئجار من يقرأ القرآن عن الميت","answer":"الجواب: هذا لا أصل له، كونهم يستأجرون من يقرأ القرآن للميت هذا لا أصل له، والقارئ لا أجر له؛ لأنه قرأ بالأجر، فلا أجر له، فلا يستحب هذا، ولا يشرع، وقد مضى النبي ﷺ والصحابة، ولم يفعلوه، وهم أسبق الناس إلى كل خير، وأسبقهم إلى كل طاعة، فلا يجوز كونه يستأجر من يقرأ للميت بعد الموت، أو جماعة يقرؤون أيام العزاء، هذا بدعة لا أصل له.","link":"https://binbaz.org.sa/fatwas/2546/حكم-استىجار-من-يقرا-القران-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1041.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6701,"question":"بعد وفاة الميت -عندنا في مناطق الجنوب- بعد وفاة الميت .. يبنون الخيام بجوار بيت المتوفى، ويقيمون فيها الحفلات، والذبائح؟","title":"حكم بناء الخيام لإقامة المآتم","answer":"الجواب:  هذا بدعة، هذا مأتم، بينَّا كم مرة في الصحف، ورسائل قرئت عليهم في الجنوب، وبُين في الصحف، والمجلات كل هذا بُين، ومنكر، لا يجوز هذا. السؤال: يكون بدعة هذا؟ الجواب:  نعم، بدعة، ما يجوز هذا، نعم. السؤال: يجوز نروح لهم نعزيهم، وهم بهذا الشكل؟ الجواب: لا. السؤال: لكن اجتماعهم من دون خيام، ومن دون محمل، لكن اجتماع الكل يعني ..؟ الجواب: إذا زاروهم للتعزية سنة، أما إقامة حفل لهذا، ومأتم ما يجوز هذا. السؤال: لا هم يجتمعون يأتون .. يردون العزاء، فيستقبلونهم جماعة الميت؟ الجواب: يستقبلونهم في بيوتهم، ما يحتاج إقامة مخيمات، يستقبلوهم في بيوتهم، والحمد لله.. السؤال: ولكن حكم إقامتهم كيف حكم .. الجواب: هذا منكر ما له أصل، هذا مأتم من المآتم. السؤال: أحيانا تضيق البيوت عن استيعاب المعزين؛ لأنهم يأتون بالآلاف، فهم يصنعون مكاناً يقيهم من الحر، أو من البرد، أو من المطر، ويستقبلون فيه المعزين، ويروح؟ الجواب: إذا وجد .. من دون ولائم، من دون شيء .. عند الحاجة إلى ذلك.","link":"https://binbaz.org.sa/fatwas/2580/حكم-بناء-الخيام-لاقامة-الماتم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1076.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6705,"question":"هل يجوز أن يقرأ أحد الأشخاص القرآن، ويرد الذين يستمعون له بنهاية كل آية بأن يقولوا: الله أكبر، أو اللهم صل على محمد، إذا كان هذا لا يجوز، لماذا نخرج مثل هذه القراءات في إذاعة القرآن الكريم، وقد يكون هذا إقرار لهذا الفعل من جانب الإذاعة؟","title":"حكم التكبير أو الصلاة على النبي من المستمعين للقرآن","answer":"الجواب:\n\n.. لا أعلم لها أصلًا، وإنما المشروع أن ينصتوا، وأن يجدوا، ويتأملوا وقت القراءة؛ لأن الله قال: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا [الأعراف:204].","link":"https://binbaz.org.sa/fatwas/2577/حكم-التكبير-او-الصلاة-على-النبي-من-المستمعين-للقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1072.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6712,"question":"لقد تكلمتم عن أحكام الأعياد المبتدعة، فما رأيكم فيما يحدث في وقتنا الحاضر من اليوم الوطني، والاحتفال به، والتهنئة له، أفتونا جزاكم الله خيرًا؟","title":"حكم الاحتفال بالأعياد الوطنية","answer":"الجواب: هذا اليوم الوطني هو من التشبه بأعداء الله، الأيام الوطنية هو من التشبه، وقد وقع عن حسن نية، واجتهاد، ولكنه فيما يظهر لنا لا يشرع، وليس مما ينبغي، بل هو فيه تشبه لأعداء الله، وإن لم تقصد العبادة، أما لو قصد العبادة؛ يكون بدعة، لكن إذا لم تقصد العبادة، وإنما قصد بذلك التهانئ، وإظهار ما أنشأته الدولة، وما بذلته الدولة، فهذا يكون معتبرًا من جنس الأيام الأخرى التي يحدثها اليهود، والنصارى، وأشباههم للذكرى، أو لأسباب أخرى، فلا ينبغي التشبه بهم، لا في هذا، ولا في غيره.","link":"https://binbaz.org.sa/fatwas/2592/حكم-الاحتفال-بالاعياد-الوطنية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1088.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6715,"question":"قلتم سماحتكم في حديثكم أن الاحتفال بمولد النبي -عليه الصلاة والسلام- بدعة، فما تقول في الأدلة التي استشهد بها من يقيمون الموالد من الكتاب، والسنة، والآثار، والاستنتاجات العقلية؟","title":"الرد على من قال بجواز الاحتفال بالموالد","answer":"الجواب: كل ما ذكروه لا حجة لهم فيه، بل هو حجة عليهم، وقد كتب في هذا محمد علوي المالكي المعروف، كتابًا صغيرًا جمع فيه فوق العشرين، زعم أنها أدلة، وهي كلها تدل على عكس ما قال، كلها تلبيس، وعدم إيضاح للحق، ولكن الهوى يعمي، ويصمي، فهي حجة عليه لا له، وعلى مقتضى أدلته أن كل اجتماع يكون فيه تعظيم للنبي، أو للأنبياء يكون جائزًا، فعلى هذا على قوله، وما سرد من أدلته أن جميع الأيام، والليالي لو جعلت أعيادًا للأنبياء، ولمحمد ﷺ يقرأ فيها، ويذكر فيها موالدهم، لكان ذلك من ذكرهم، ومن تعظيمهم، ومن الصلاة عليهم، كما أنها تكون الأيام، والليالي كلها أعيادًا، وهذا كله باطل، ولا حجة فيه، لا في أول أمره، ولا في آخره، وجميع كُتيبه الذي ذكر، كلها حجة عليه، وقد أوضح الذين ردوا عليه ذلك، وبينوا بطلان ما قال، ونسأل الله له الهداية، فقد لبس عليه، ولبس على أمثاله من الناس، ونسأل الله أن يمن عليهم بالهداية، ويردهم إلى الصواب. ولو كان خيرًا هذا؛ لسبقنا إليه خير القرون  يعني نحن أعلم من أبي بكر، وعمر، وعثمان، وعلي؟ ونحن أعلم من أصحاب النبي ﷺ؟ ونحن نهدى لشيء أفضل مما اهتدوا إليه، فيكون زمانهم محرومًا من هذا الخير، ونحن اهتدينا إليه؟ هذا محال! وقد قال النبي ﷺ: لا تزال طائفة من أمتي على الحق منصورة فهم كانوا على الحق في القرن الأول، والثاني، والثالث، كانوا على الحق بلا ريب، وليس عندهم مولد، فكانوا حرموا من هذا الخير، وحرموا من هذا الفضل، وحصل عليه من بعدهم ممن هو أجهل، وأقل فضلًا منهم، وحرم فضله الأولون السابقون، والأخيار، وفاز به المتأخرون، أو الأولون جهلوه، وصار المتأخرون أعلم منهم؟! هذا أيضًا محال، فمن زعم: أن الآخرين أعلم من الأولين؛ فقد ضل ضلالًا بعيدًا، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/2593/الرد-على-من-قال-بجواز-الاحتفال-بالموالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1089.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6753,"question":"عرفنا من كلام الشيخين مدى حرمة هذه البدعة، ومدى إثمها، فهل من قام بالمولد النبوي بقصد أن يجمع المسلمين لتبيين الدين الصحيح، لا لإشاعة هذه البدعة، بأن يكون مضيقًا عليه، لا يستطيع أن يجمع المسلمين، ويعلمهم دينهم إلا في مثل هذه التجمعات، وهو يعلم بدعيتها، وعدم شرعيتها كذلك، من جاء من عامة المسلمين يعلم ذلك؟","title":"حكم حضور الموالد لبيان الحق والتحذير منها","answer":"الجواب: إذا حضرها لهذا القصد؛ ليبين أمرها، وأنها بدعة، ويبين للناس ما في نفسه من أشياء منكرة، يحذرهم منها ... إلى فعلها، ويبين لهم أن هذه بدعة، وأنه لا يجوز الاحتفال؛ فهذا طيب، أما أنه يقيم الاحتفال لأجل الميتين لا، ما يقيمه لأجل الميتين، يخطب الناس في المساجد، وفي الجمع، ويبين للناس مما شرع الله سبحانه، ومما حرم، لكن إذا حضرها، وإذا أقامها غيره، وجاء إليهم، ونصحهم، وعلمهم أن هذا بدعة؛ فهذا مأجور.","link":"https://binbaz.org.sa/fatwas/2640/حكم-حضور-الموالد-لبيان-الحق-والتحذير-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1136.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6764,"question":"عرفنا من كلام الشيخين مدى حرمة هذه البدعة، ومدى إثمها، فهل من قام بالمولد النبوي بقصد أن يجمع المسلمين لتبيين الدين الصحيح، لا لإشاعة هذه البدعة، بأن يكون مضيقًا عليه، لا يستطيع أن يجمع المسلمين، ويعلمهم دينهم إلا في مثل هذه التجمعات، وهو يعلم بدعيتها، وعدم شرعيتها كذلك، من جاء من عامة المسلمين يعلم ذلك؟","title":"حكم حضور الموالد لبيان الحق والتحذير منها","answer":"الجواب: إذا حضرها لهذا القصد؛ ليبين أمرها، وأنها بدعة، ويبين للناس ما في نفسه من أشياء منكرة، يحذرهم منها ... إلى فعلها، ويبين لهم أن هذه بدعة، وأنه لا يجوز الاحتفال؛ فهذا طيب، أما أنه يقيم الاحتفال لأجل الميتين لا، ما يقيمه لأجل الميتين، يخطب الناس في المساجد، وفي الجمع، ويبين للناس مما شرع الله سبحانه، ومما حرم، لكن إذا حضرها، وإذا أقامها غيره، وجاء إليهم، ونصحهم، وعلمهم أن هذا بدعة؛ فهذا مأجور.","link":"https://binbaz.org.sa/fatwas/2640/حكم-حضور-الموالد-لبيان-الحق-والتحذير-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1136.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6776,"question":"نهتم كثيرًا بقضية الاحتفال بعيد المولد النبوي، والردود عليه، بينما الاحتفال باليوم الوطني، وغيره من الأيام في البلاد الإسلامية تجري على ما هي عليه دون اعتراض، هل لأنها احتفالات سياسية، والمولد ديني، كل هذه الاحتفالات لا شك باطلة، فما تعليق سماحتكم؟","title":"الفرق بين الاحتفال بالمولد النبوي واليوم الوطني","answer":"الجواب: التعليق على هذا: أن الأيام الوطنية هذا تقليد للكفرة، وأشباه الكفرة، وليس من باب الدين، فهو أسهل من جهة العواقب، وهو لا شك، ينبغي تركه، ولا ينبغي فعله؛ لأنه تقليد للكفرة، ولا ينبغي تقليدهم، ولا التشبه بهم، ولكن الموالد التي تقام للأنبياء، أو الأولياء خطرها أعظم، وشرها أكبر؛ لأنها تشبه العبادة، تشبه الدين تشبه الغلو، وتفضي إلى الشرك الأكبر، والمعاصي الكثيرة، ولهذا اهتم بها أهل العلم أكثر من اهتماهم بالأيام الوطنية السياسية، التي يفعلها الملوك، والرؤساء، مع أن هذا قد بذل.. تكلمنا فيه بما يلزم، والحمد لله.","link":"https://binbaz.org.sa/fatwas/2647/الفرق-بين-الاحتفال-بالمولد-النبوي-واليوم-الوطني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1143.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6853,"question":"من هم الأولياء؟ نريد شرحًا مفصلًا؛ لأن في بعض البلاد المجاورة يجب عليك أن تأخذ طريقة من الشيخ حتى يكون واسطة بينك وبين الله، هذا على حد قولهم؟","title":"حقيقة الأولياء","answer":"الجواب: الأولياء هم أهل الإيمان، وأنت منهم إذا كنت مؤمنًا، فأنت منهم، أولياء الله هم أهل الإيمان، والتقوى، قال تعالى: أَلَا إِنَّ أَوْلِيَاءَ اللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ  ۝ الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ [يونس:62، 63]، وقال سبحانه: وَمَا كَانُوا أَوْلِيَاءَهُ إِنْ أَوْلِيَاؤُهُ إِلَّا الْمُتَّقُونَ [الأنفال:34]. فأولياء الله هم أهل الإيمان والتقوى الذين وحدوا الله، واستقاموا على دينه، فأدوا فرائضه، وتركوا مناهيه، هؤلاء هم أولياء الله، وهم أهل الإيمان، وهم أهل التقوى، وقد تقع منهم معصية، ثم يتوبون، فيتم إيمانهم، قد يقع من الولي المعصية، أو المؤمن، ثم ينتبه، فيتوب؛ فيتوب الله عليه، والذي لم يتب كان مؤمنًا ناقصًا، ووليًا ناقصًا، وإذا تاب تاب الله عليه.  وأما ما تقوله الصوفية: إن الولي هو الذي يكون عنده خوارق، وعنده شعوذة، وعنده دعاوى طويلة، عريضة حتى يقال: إنه شيخ الطريقة، وحتى يقلد، وحتى يتبع فيما يريد، وفيما يهوى، وحتى ينسى كتاب الله، وسنة رسوله -عليه الصلاة والسلام- هذا من عمل الشيطان، هذا من الضلالات، والبدع، والأهواء المنكرة -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/2744/حقيقة-الاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1244.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6946,"question":"هل تعتبر أعياد الميلاد نوعًا من البدع؟ وكذلك الحفلات في أثناء المناسبات؟","title":"حكم الاحتفال بعيد الميلاد","answer":"الجواب: الأعياد كل ما يتكرر في السنة، أو في الشهر، أو في الأسبوع بنية العبادة، والتقرب إلى الله، هذه البدع، فالموالد من هذا الباب.","link":"https://binbaz.org.sa/fatwas/2876/حكم-الاحتفال-بعيد-الميلاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1324.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":6947,"question":"ما الفرق بين البدعة الحسنة، والسيئة؟ وكيف نعرف كل منهما؟","title":"حكم تقسيم البدع إلى حسنة وسيئة","answer":"الجواب: الصواب: أن البدعة كلها سيئة، كلها ضلال، ما فيها بدعة حسنة، يقول النبي ﷺ: كل بدعة ضلالة أما قول بعض العلماء: أنها قسمان: حسنة، وسيئة، هذا قول من كيسهم، ما عليه دليل. الصواب: أنه ليس هناك بدعة حسنة، كلها ضلالة، وما سموه حسنة فليس من البدع، بل هو أمر جاء به الشرع، مثل: تنقيط القرآن، وتشكيله؛ لأجل لا يغلط الناس فيه، هذا مما أمرنا الله به، أمرنا بحفظ القرآن، وضبطه. ومثل إقامة المدارس للدراسة، وإن كان ما هي في عهد النبي ﷺ لكن أقيمت للحاجة إليها، وبنيت المساجد على طريقة غير طريقة النبي ﷺ النبي بناه بالجذوع، وبناه الناس بعده بالحجر، أو بغير ذلك مثل ما بناه عثمان، لا بأس بهذا، ليس هذا من البدع، هذا من باب العناية بأمر الدين، وإقامة الشعائر على الوجه الأكمل مهما أمكن.","link":"https://binbaz.org.sa/fatwas/2877/حكم-تقسيم-البدع-الى-حسنة-وسيىة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1325.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":7091,"question":"هل ثبت حديث صحيح في فضل صيام يوم الخامس عشر من شعبان؟ وهل ورد حديث صحيح في فضل قيام تلك الليلة؟","title":"حكم تخصيص ليلة النصف من شعبان ويومها بالصيام والقيام","answer":"الجواب:\n\nلا، تخصيص يوم النصف من شعبان بالعبادة، أو الصيام، أو ليلة النصف لا أصل له، بل هو بدعة، الصحيح من أقوال العلماء أنه بدعة، والأحاديث التي فيه ضعيفة، ليلة النصف من شعبان كلها ضعيفة، وبعضها موضوع، لا صحة لها.","link":"https://binbaz.org.sa/fatwas/3103/حكم-تخصيص-ليلة-النصف-من-شعبان-ويومها-بالصيام-والقيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1480.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":7238,"question":"هل في الدين بدعة مباحة؟ وما معنى قول عمر: نعمت البدعة هذه؟","title":"حكم القول بوجود بدعة مباحة في الدين","answer":"الجواب:\n\nما في الدين بدعة مباحة، ولا بدعة مكروهه، بل كلها ضلالة، يقول النبي ﷺ: وكل بدعة ضلالة، هذا كلام رسول الله ﷺ، فليس في الدين بدعة، لا مباحة، ولا مستحبة، بل كل البدع في الدين ضلالة.\n\nوأما ما يسميه بعض الناس بدعًا في المدارس، وفي بناء المنارات، هذه ليست بدعًا، هذه أمور دعت إليها الحاجة؛ فهي قربة، فالمنارة لأجل يعرف الصوت بالأذان حتى يسمعه الناس، والمدارس لأجل تعليم القرآن والسنة، والأربطة لأجل الناس الفقراء، فليس هذه من البدع، بل هذه من الحسنات، والخيرات، والقربات. \n\nوأما قول عمر : (نعمت البدعة) فالمراد به من حيث اللغة، فإنه لما جمعهم على إمام واحد في التراويح، وكان النبي ﷺ فعل ذلك مرات لعدة ليالي، ثم ترك، وخاف أن تفرض عليهم -عليه الصلاة والسلام- فلما توفي النبي ﷺ وتوفي أبو بكر، واستخلف عمر؛ رأى أن يجمعهم على إمام واحد؛ لأنهم يصلون أوزاعًا في المسجد، هذا يصلي لأربعة، وهذا يصلي لثلاثة، وهذا يصلي لنفسه، فرأى أن يجمعهم فجمعهم، كما جمعهم النبي ﷺ وصلى بهم؛ لأنه قد أمن الآن الفرض، وانقطع الوحي، فلهذا جمعهم  وقال: (نعمت البدعة) يعني من حيث اللغة، لأن البدعة في اللغة ما كان على غير مثال سابق، فهذه الصلاة التي جمعهم عليها، واستمروا عليها بدعة من حيث اللغة، لا من حيث الدين، فإن الرسول قد فعلها، ودعا إليها ﷺ وصلى بهم عدة ليال، فلم تكن بدعة، بل هي قربة، وطاعة.","link":"https://binbaz.org.sa/fatwas/3303/حكم-القول-بوجود-بدعة-مباحة-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1628.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":7437,"question":"ما هو فضل صيام سبعة وعشرين من رجب وليلة النصف من شعبان؟ وهل هناك حديث عن الرسول يحث المؤمنين على صيام تلك الأيام؟ وهل صيام الأيام الثلاثة الأولى من شهر رجب أو شهر شعبان أو شوال وفضلها أكبر من مثيلاتها في الأشهر الأخرى؟","title":"حكم صيام السابع والعشرين من رجب والنصف من شعبان","answer":"الجواب: هذا لا أصل له، فإن بعض أهل العلم يزعم أن سبعة وعشرين رجب أنها ليلة الإسراء والمعراج، وهذا لا أصل له، والحديث المروي في ذلك غير صحيح، فليس لها خصوصية، وليس لصيام ثلاثة أيام من أول رجب أو من أول شعبان أو من أول شوال خصوصية.  إنما شرع صيام ثلاثة من كل شهر عام لكل الشهور، يشرع للمؤمن أن يصوم ثلاثة أيام من كل شهر، لا فرق بين رجب وغيره، كذلك ستة أيام من شوال جاء الشرع بها أيضًا، ما هي بثلاث ستة أيام من شوال، أما الثلاث فهي عامة للشهور كلها، وأما تخصيص صيام سبعة وعشرين من رجب، أو ثلاثة من أوله، أو ليلة النصف من شعبان تقام وحدها هذا لا أصل له، جاء فيه أحاديث غير صحيحة، ليلة النصف من شعبان ليست بصحيحة ولا يعتمد عليها.","link":"https://binbaz.org.sa/fatwas/3542/حكم-صيام-السابع-والعشرين-من-رجب-والنصف-من-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1847.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":7647,"question":"هذه رسالة وردت للبرنامج من جيزان ومن إبراهيم مطر من قرية الجهو، يقول في رسالته: عندنا عادات منها أن ليلة ثلاث من وفاة الميت نقرأ قرآن، ويحضر الناس بكثرة في هذه الليلة، وقد قيل لنا: إن هذا العمل بدعة، فأخذنا أسلوب غيره، فإذا جاءت هذه الليلة ندعو للميت بالمغفرة والرحمة لكي ينفض هذا الموقف، فهل هذا الفعل يجوز من الدعاء للميت؟ وإذا كان العكس فبم تنصحونا وفقكم الله في إقناع الحضور إنهاء التعزية، أرشدونا أرشدكم الله؟","title":"حكم الاجتماع في الليلة الثالثة من دفن الميت للدعاء له","answer":"الجواب: الاجتماع لأهل الميت في الليلة الثالثة من الموت لقراءة القرآن أو للدعاء أو لصنع وليمة كل هذا بدعة لا أصل له، وإنما يعزون، يزورهم الناس في أي وقت، كان في يوم الموت أو في الثاني أو في الثالث أو الرابع، ما في حد محدود، يزورهم الناس في أوقات مناسبة يعزونهم هذا لا بأس به، التعزية مستحبة، أما أنهم يصنعون لهذا شيء من طعام أو قراءة قرآن يعتاد أو ما أشبه ذلك، هذا كله بدعة حتى جلوسهم مع الناس للدعاء للميت والاستغفار له كذلك بدعة، ولكن هذا الوقت يتركونه، يعني: يحلون هذه العادة ويزيلونها بترك الجلوس في هذا الوقت حتى من أرادهم يجدهم في أوقات أخرى، وبهذا تنتهي هذه العادة السيئة في اليوم الثالث، لا يجلسون في اليوم الثالث لا لقراءة ولا للدعاء للميت والاستغفار ولا لغير هذا، بل يدعون هذه العادة بالكلية، ويمكن أن يجدهم المعزون في أوقات أخرى، في اليوم الأول واليوم الثاني واليوم الرابع، حتى لا تبقى هذه العادة السيئة. نعم.\nوهكذا ما يفعل بعض الناس من صنع ولائم في اليوم السابع أو في الأربعين بعد الموت، كل هذه بدع، فأي ترتيب يقع من مأتم للميت في اليوم الثالث أو رابع أو عاشر أو أربعين أو غير ذلك أو شيء غير هذا بحيث يجتمعون لطعام أو قراءة قرآن أو ذبائح أو ولائم كله بدعة، كل هذا بدع، كل هذه المآتم بدع، يجب الحذر منها ولا يجب فعلها.\nوهكذا ما تفعله الشيعة في يوم العاشر من محرم بدعة، من النعي على الحسين ، وما يفعلونه هناك كله من البدع التي نسأل الله أن يهديهم حتى يتركوها، نسأل الله لنا ولهم الهداية؛ لأن هذا شيء لا أصل له، فلا ينبغي لأهل الإسلام أن يفعلوا ذلك أبداً، لا مع كبير ولا مع صغير ولا مع شريف ولا مع وضيع؛ لأن الرسول ﷺ سيد ولد آدم ، ولما توفي ﷺ ما اجتمع الناس بعد وفاته في اليوم الثالث ولا في العاشر وجعلوا وليمة أو قراءة قرآن، وهكذا الصديق لما مات ما اجتمع الناس لصنع طعام أو قراءة قرآن، وهكذا عمر لما قتل، وهكذا عثمان ، وهكذا علي  رابع الخلفاء الراشدين، وهكذا بقية العشرة، وهكذا بقية الصحابة، وهم السادة وهم القدوة، فلو كان هذا شيئاً مستحباً طيباً لفعلوه.. ولاقتدى بهم الناس.\nفالحاصل أن هذا الشيء لا يجوز بل هو من البدع التي يجب تركها على أهل السنة وعلى الشيعة جميعاً، يجب على الجميع ترك هذا البدع، وأن يراقبوا الله  في ذلك، وأن يتأسوا بنبيهم ﷺ وبخلفائه الراشدين الأربعة: الصديق وعمر وعثمان وعلي ، فإنهم هم خيرة الناس، وهم أفضل الناس بعد نبي الله وبعد الأنبياء، وهم القدوة، رزق الله الجميع الهداية.\nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/4795/حكم-الاجتماع-في-الليلة-الثالثة-من-دفن-الميت-للدعاء-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_036/03606.mp3","categories":["أحكام التعزية","البدع والمحدثات"]},{"id":7890,"question":"سؤاله الأخير يا سماحة الشيخ يقول: ما حكم تقديم الدخان مع ما يقدم بعد حضور الناس للتعزية في الميت، وفقكم الله وشكر لكم، وقدر مسعاكم؟","title":"حكم توزيع الدخان أثناء التعزية","answer":"الجواب: لا يجوز لأهل الميت ولا غيرهم أن يقدموا الدخان للناس ولا الخمر، بل هذا حرام منكر؛ لأن الدخان حرام والخمر حرام، فليس لأهل الميت أن يقدموا ما حرم الله لزوارهم والمعزين هذا لا يجوز، هذا من التعاون على الإثم والعدوان، ولكن لا بأس أن يقدموا قهوة أو شاهي أو شراب طيب لا بأس، أما أن يقدموا الدخان أو الخمر أو الحشيش أو الحبوب المسكرة والمخدرة هذا كله لا يجوز، بل هذا من التعاون على الإثم و العدوان، والله سبحانه نهى عن ذلك، نسأل الله للجميع الهداية. نعم","link":"https://binbaz.org.sa/fatwas/5376/حكم-توزيع-الدخان-اثناء-التعزية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_060/06007.mp3","categories":["أحكام التعزية"]},{"id":7892,"question":"هذه الرسالة من نزال حسن روضان، من سوريا محافظة الحسكة، يقول في رسالته: السلام عليكم ورحمة الله وبركاته وبعد:فإني أشكر الشكر الجزيل أصحاب الفضيلة الذين يجيبون على رسائلنا ويدلوننا إلى طريق الرشاد، يقول من العادات السائدة لدينا أنه إذا توفي عندنا إنسان يجتمع الناس للتعزية في بيت أهل المتوفى، وحاملين معهم بما يسمى بالتعازي كالنقود والذبائح وما أشبه ذلك، وعلى إثر ذلك يقوم أهل الميت بالذبح من هذه التعازي ويشترون ببعض النقود من الشاي والقهوة، علماً الذين يقومون بالذبح هم أقارب وجيران الميت بقصد المساعدة كون أهل الميت مشغولين، ولا يخفى أيضاً مساعدة أهل الميت، نرجو منكم التوضيح إذا كان ذلك جائزاً أم لا، وفقكم الله وبارك فيكم؟","title":"حكم صنع أهل الميت الطعام للمعزين","answer":"الجواب:\nالسنة للمسلمين أن يساعدوا أهل الميت ببعث العشاء لهم، يعزون في ميتهم ويبعث لهم أقاربهم وجيرانهم أيام العزاء العشاء، طعام العشاء؛ لأنهم مشغولون عن صنع العشاء بسبب المصيبة، وقد ثبت عنه ﷺ أنه قال لأهله لما جاء نعي جعفر بن أبي طالب يوم مؤتة، قال: ابعثوا لأهل جعفرٍ طعامًا فقد أتاهم ما يشغلهم، هذا من السنة.\n\nأما كون أهل الميت يقومون ويصنعون الطعام للناس هذا لا ينبغي، هذا منكر وهو من جملة النياحة، قال جرير بن عبد الله البجلي: \"كنا نعد الاجتماع إلى أهل الميت وصنعة الطعام لهم من النياحة\"، فلا ينبغي هذا، ولا يجوز لهم أن يصنعوا الطعام للناس، ويجمعوا الناس للأكل عندهم لأنهم مشغولون بالمصيبة، لكن زوارهم ينبغي أن يخففوا، يزورونهم للتعزية، ثم ينصرفون ولا يثقلون عليهم، ولا يحرجونهم إلى صنع الطعام، بل ينبغي للمعزين أن يعزوا ثم ينصرفوا من دون إبطاء وتأخر عندهم حتى لا يشقوا عليهم.\n\nوإذا كان المعزون جاؤوا من بلادٍ بعيدة ضيوفًا على المعزين فلا بأس حينئذٍ من أجل الضيافة، أن يصنع لهم أهل الميت طعامًا أو يصنعه الجيران ويقدمونه لهم، لا بأس بهذا، أما يتخذ عادة، أن أهل الميت يصنعون الطعام للمعزين، هذا لا ينبغي، بل هذا من المنكر، ومن أعمال الجاهلية، ومن النياحة، لكن إذا اضطروا إلى هذا بسبب الضيوف الذين جاءوا من بعيد ويستحون من تركهم فلا بأس أن يصنعوا لهم طعامًا من باب الضيافة، لا من باب المأتم، ولا من باب صنع الطعام لأجل الميت، لا، بل هذه حاجة عارضة.\n\nوأما جيرانهم وأقاربهم فالأفضل أن يصنعوا لهم طعامًا يهدونه إليهم من أجل أنهم مشغولون فيكفيهم المؤونة جيرانهم وأقاربهم ويهدونه إليهم، وإذا أكل معهم بعض المعزين أو بعض الجيران فلا بأس لأنه طعام حاصل إن لم يأكلوه طرح في العراء فلا بأس حينئذٍ أن يأكل معهم جيرانهم وضيوفهم، كل هذا لا بأس به.","link":"https://binbaz.org.sa/fatwas/5370/حكم-صنع-اهل-الميت-الطعام-للمعزين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_060/06003.mp3","categories":["أحكام التعزية"]},{"id":7893,"question":"أيضاً يقول: ما حكم المتبقي من هذا الطعام وغيره كالذبائح والمال: هل يجوز أن يكون من مال الورثة المتوفى عنهم أم يرجع إلى أصحابهم؟","title":"حكم ما يتبقى مما يهدى لأهل الميت","answer":"الجواب: ما يتبقى يكون لأهل الميت للورثة، ما يتبقى من هذه الأموال التي أهدوها يكون لأهل الميت ينتفعون به جميعاً.","link":"https://binbaz.org.sa/fatwas/5371/حكم-ما-يتبقى-مما-يهدى-لاهل-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_060/06004.mp3","categories":["أحكام التعزية"]},{"id":7896,"question":"سؤاله الأخير يا سماحة الشيخ يقول: ما حكم تقديم الدخان مع ما يقدم بعد حضور الناس للتعزية في الميت، وفقكم الله وشكر لكم، وقدر مسعاكم؟","title":"حكم توزيع الدخان أثناء التعزية","answer":"الجواب: لا يجوز لأهل الميت ولا غيرهم أن يقدموا الدخان للناس ولا الخمر، بل هذا حرام منكر؛ لأن الدخان حرام والخمر حرام، فليس لأهل الميت أن يقدموا ما حرم الله لزوارهم والمعزين هذا لا يجوز، هذا من التعاون على الإثم والعدوان، ولكن لا بأس أن يقدموا قهوة أو شاهي أو شراب طيب لا بأس، أما أن يقدموا الدخان أو الخمر أو الحشيش أو الحبوب المسكرة والمخدرة هذا كله لا يجوز، بل هذا من التعاون على الإثم و العدوان، والله سبحانه نهى عن ذلك، نسأل الله للجميع الهداية. نعم","link":"https://binbaz.org.sa/fatwas/5376/حكم-توزيع-الدخان-اثناء-التعزية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_060/06007.mp3","categories":["أحكام التعزية"]},{"id":8099,"question":"الرسالة التالية باعثها أحد الإخوة يقول: يحيى محمد عطية يمني مقيم في المملكة، أخونا يسأل عن القات ويسرد مجموعة من أوصافه وتأثيره على من يتعاطاه، لو تكرمتم سماحة الشيخ؟الشيخ: لو قرأتها.المقدم: يقول يحيى محمد عطية: لقد سبق أن بعثت برسالة قبل هذه الرسالة أسأل فيها عن القات والآن أقول: إنه باليمن كل الجميع تأكل شجراً اسمه القات وهو حرام عند العلماء وذلك عند شهر رمضان بالليل وهم يقرءون القرآن بالنهار ويكون نائم بالقات في فمه، فهل هذا حرام أم حلال ويستمر على هذا المنوال، سماحة الشيخ؟","title":"تنبيهات وتوضيحات حول حكم أكل القات","answer":"الجواب: القات معروف عند أهل العلم وهو شجرة معروفة في اليمن وأهلها يتعاطون ذلك إلا من حفظ الله منهم، والذي ثبت عندنا من كلام العارفين به أنه مضر وأنه يسبب تعطيلاً كثيراً عن الأعمال والمكاسب الطيبة ويسبب أشياء تضر متعاطيه، وقد كتب جماعة من علماء اليمن وغيرهم في تحريمه وأنه قد يخدر وقد يفتر، قد يسبب سكراً في بعض الأحيان بتغير الشعور مع ما فيه من تعطيل صاحبه المدة الطويلة لا يعمل بسبب تخزينه له، فهو شجرة خبيثة مضرة.\nوقد انعقد مؤتمر في المدينة للنظر في المخدرات ودراستها وأجمع المؤتمرون على تحريم القات، وأنه مضر بأهله، وأنه لا يجوز تعاطيه، وألف في ذلك جماعة من أهل العلم وكتب شيخنا العلامة الشيخ محمد بن إبراهيم آل الشيخ رحمه الله في ذلك كتابة ذكر فيها تحريمه ونقل فيها بعض كلام أهل العلم الذين عرفوه.\nفينبغي للمؤمن أن يحذره وأن لا يتساهل في تعاطيه واستعماله وأن لا يغتر بمن يتعاطى ذلك.\nونصيحتي لكل إخواني في اليمن أن يدعوه وأن يحاربوا هذه الشجرة وأن يبتعدوا عنها وأن يقضوا على شجرتها.\nونصيحتي للدولة -وفقها الله- في اليمن أن تحارب هذه الشجرة وأن تؤكد على الشعب اليمني بمحاربتها وتركها حفظاً للمسلمين في اليمن من أذاها وضررها، وحفظاً لهم أيضاً من تعطيل أوقاتهم بلا فائدة، وحفظاً لهم أيضاً من تعاطي أشياء لا تناسب لولا أنهم يتعاطون هذا القات ويخزنون.\nفالمقصود: أن ضرره كثير وشره عظيم من إفادة العارفين به من علماء اليمن وغيرهم، ونسأل الله للجميع التوفيق والهداية.\nالمقدم: اللهم أمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/5895/تنبيهات-وتوضيحات-حول-حكم-اكل-القات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_101/10104.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":8346,"question":"من القصيم رسالة وصلت إلى البرنامج من أحد الإخوة (م. م. ف) المذنب، أخونا يسأل ويقول: أنتم تعلمون أن كل المطابخ فيها مغاسل، وأواني مطبخنا والمغسلة تتسرب إلى المجاري، وأحياناً يكون معها قطع من الفضلات، ما رأيكم في هذا؟ وبم توجهون الناس؟","title":"حكم اختلاط فضلات الطعام بالمجاري عند غسل الأواني","answer":"الجواب: الواجب على من يعتني بالمطابخ أن يتحرى إبعاد ما يكون من اللحوم أو قطع الخبز أو غير هذا من الطعام حتى يكون في جهة أخرى، إما في كراتين تبعد إلى الصحراء يأكل منها الطير والدواب، أو في محلات أخرى نظيفة توضع فيها هذه الفضلات، أو في سطوحهم وأحواشهم ونحو ذلك.\nأما ما يتعلق بغسل الأواني من آثار الدسم ونحو ذلك فلا يضر تسربه إلى المجاري؛ لأن هذا ليس بطعام وليس بمأكول، إنما هي بقايا الدسم، وإذا فرط شيء من غير قصد من بعض الأشياء التي لم يقصدها ولم يتعمدها فلا حرج عليه إن شاء الله، إنما عليه الاحتياط والحرص أن يكون بقية الطعام في جهة، تحفظ في جهة من بيته أو في جهات أخرى من الصحراء.. بقية الخبز أو اللحوم أو الأرز أو غير ذلك تنقل إلى محلات بعيدة عن القذر، كالأحواش التي يأتيها الدواب وتأتيها الطيور أو الصحراء ونحو ذلك، وما يتعلق بغسل الأواني وأشباه ذلك لا يضر تسربه إلى المجاري. نعم.","link":"https://binbaz.org.sa/fatwas/6164/حكم-اختلاط-فضلات-الطعام-بالمجاري-عند-غسل-الاواني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11303.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":8430,"question":"الرسالة التالية وصلت إلى البرنامج من حضرموت، وصلت من الإخوة: سالم بن علي باعبود باوزير وإخوانه: مبارك صالح بن نبيل والعبد صالح ، إخواننا رسالتهم في صفحة كاملة، وكلها تصور العادات التي عليها الناس بعد وفاة متوفى لديهم، فهم يضطرون حتى إلى أن يستدينوا من أجل الاحتفالات التي تقام، والأكل، والشرب، وما أشبه ذلك، حتى وإن توفي المتوفى وهو فقير ولم يخلف شيء، ماذا يقول سماحة الشيخ لهذه العادات لو تكرمتم؟","title":"حكم إقامة أهل الميت للمآتم والولائم بعد الدفن","answer":"الجواب: قد كتبنا في هذا أجوبة كثيرة، وقد نبهنا في هذا البرنامج مرات كثيرة، على أنه لا يجوز الاحتفال عند الموت بأحد من الناس، ليس لأهل الميت أن يقيموا احتفالاً ...... بذلك، ولا أن يذبحوا ذبائح، ولا أن يصنعوا طعاماً للناس، كل هذا من البدع والجهالات التي كان يفعلها بعض الناس، وهي من أمر الجاهلية.\nثبت عن جرير بن عبد الله البجلي  قال: كنا نعد الاجتماع إلى أهل الميت وصنعة الطعام بعد الدفن من النياحة  فكان من عمل الجاهلية ومن النياحة التي كانوا يفعلونها في الجاهلية.\nفالواجب على المسلمين إذا مات الميت أن يسألوا الله له المغفرة والرحمة، وأن يتركوا هذه الاحتفالات، وهذه الأطعمة التي تقام من أهل الميت، وقد يكون الميت فقيراً، وقد يكون عنده أيتام فيضرونهم، المقصود أنها لا أصل لها حتى ولو كان غنياً، لا أصل لها، ولا ينبغي فعلها، ولا يجوز فعلها، لكن يشرع لجيرانهم وأقاربهم أن يصنعوا لهم طعاماً؛ لأنهم مشغولون بالمصيبة، ولهذا ثبت من حديث عبد الله بن جعفر بن أبي طالب رضي الله تعالى عنهما أن النبي صلى الله عليه وسلم لما جاء نعي جعفر لما قتل في مؤتة، وجاء نعيه إلى المدينة، أمر النبي صلى الله عليه وسلم أهله أن يصنعوا لآل جعفر طعاماً، قال: لأنه أتاهم ما يشغلهم، فإذا صنع لهم طعام من جيرانهم أو أقاربهم وأرسل إليهم؛ لأنهم مشغولون بالمصيبة فهذا مستحب، وهذا سنة، أما أهل الميت فليس لهم صنع الطعام، ولا ينبغي لهم أن يصنعوا للناس الطعام، أما إذا صنعوه لأنفسهم ولأكلهم أو لضيوف نزلوا بهم فلا بأس، أما أن يصنعوا من أجل الميت مأتماً للميت لينوحوا عليه، أو يقيموا عليه الأشعار والمراثي، أو ليدعوا الناس إلى ذلك، كل هذا من البدع، كل هذا من الجهالات ومن أمر الجاهلية لا يجوز، أما كونهم يصنعوا لأنفسهم طعاماً هم ليأكلوا عادتهم فلا بأس، أو نزل بهم ضيف، فصنعوا من أجل الضيف لا من أجل الموت، ولا من أجل النياحة، ولا من أجل جمع الناس، ولكن من أجل الضيف الذي نزل، إذا صنعوا طعاماً ليطعموا الضيف فلا بأس بذلك؛ لأنه جاء من بعيد.\nفالمقصود من هذا كله أن المنكر هو أن يصنعوه للناس، أهل الميت يصنعوا طعاماً ليجمعوا الجيران أو الأقارب ولينوحوا أو ليقرءوا أو غير ذلك هذا هو المنكر، هذا هو الجاهلية.\nأما صنعهم طعاماً لحاجتهم أنفسهم؛ لأكلهم المعتاد؛ أو نزل بهم ضيف فاضطروا إلى أن يصنعوا طعاماً لأجله حتى يكرموه لما جاء من بعيد، فهذا لا حرج في ذلك، ولا ينبغي لأهل الإيمان وأهل الإسلام أن يعتادوا أمر الجاهلية وأن يفعلوا أمر الجاهلية، لا، بل يتواصوا، بل ينبغي التواصي بترك أمر الجاهلية، هكذا ينبغي للمسلمين.\nوأما جيرانهم وأقاربهم فيستحب لهم أن يصنعوا لهم طعاماً ويرسلونه إليهم؛ لأنهم مشغولون بالمصيبة، هذا إذا تيسر فهذا أفضل، وهذا سنة. نعم.","link":"https://binbaz.org.sa/fatwas/6314/حكم-اقامة-اهل-الميت-للماتم-والولاىم-بعد-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_119/11907.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":8469,"question":"أخونا يسأل مع مستمع آخر هو: محمد التونسي إخواننا يسألون سماحة الشيخ عن العادات في العزاء، وأيضاً يسأل معهم أحد الإخوة يقول محمد أحمد شوي مقيم في جدة وهو من تشاد، يسألون عن العادات المتبعة لدى البعض في العزاء، من الولائم وقراءة القرآن والأربعينيات والسنويات أيضاً وما شاكل ذلك، ويرجون التوجيه من سماحة الشيخ؟","title":"بدع التعزية","answer":"الجواب: هذه عادات لا أصل لها ولا أساس لها، بل هي من البدع ومن أمر الجاهلية، كونه يقيم وليمة إذا مات الميت يدعو إليها الجيران والأقارب ونحو ذلك، ويقيمونها بالبكاء أو بالقراءة أو نحو ذلك، هذه بدعة لا تجوز، وهكذا إقامتها على رأس الأربعين، أو على رأس الأسبوع أو على رأس الشهر أو على رأس السنة كلها من بدع الجاهلية، كلها مما لم يشرعه الله سبحانه وتعالى.\nوإنما المشروع لأهل الميت الصبر والاحتساب والعزاء يعني: العزاء مما أصابهم أن يتعزوا بالله ويرضوا عما قدر عليهم سبحانه وتعالى، ويحتسبوا الأجر عنده ، ولا مانع من أن يصنعوا لأنفسهم الطعام العادي لأكلهم وحاجاتهم، وهكذا لو نزل بهم ضيف صنعوا له الطعام العادي لا بأس، أما أن يصنعوه من أجل الموت ومن أجل المأتم من أجل إقامة مأتم، يجمعون الناس ليقرءوا القرآن أو ليقرءوا الأحاديث أو الأشعار أو ليبكوا معهم وينوحوا معهم، كل هذا من البدع المحدثة وليس له أصل في الشرع المطهر.\nويشرع لأقاربهم وجيرانهم ونحو ذلك أن يصنعوا لهم طعاماً يرسلونه إليهم؛ لأنهم مشغولون بالمصيبة فإذا صنع لهم جيرانهم أو بعض أقاربهم طعاماً يوم الموت أو اليوم الثاني أو نحوه، وأرسلوه إليهم جبراً لمصابهم وإعانة لهم على المصيبة لأنهم مشغولون، قد لا يتفرغون للطبخ، قد يكسلون عن ذلك لشدة المصيبة هذا أمر مشروع، وقد ثبت عن رسول الله عليه الصلاة والسلام أنه لما أتى نعي جعفر بن أبي طالب رضي الله عنه حين قتل في مؤتة في الشام وجاء خبره إلى المدينة  أمر النبي ﷺ أهله أن يصنعوا طعاماً لأهل جعفر، قال: اصنعوا لهم طعاماً فقد أتاهم ما يشغلهم يعني: بعثوا لهم طعاماً من أهله صلى الله عليه وسلم إلى أهل جعفر لأنه قد أتاهم ما يشغلهم، يعني: يشغلهم عن صنع الطعام، فهذا أمر مشروع وليس فيه بأس. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6485/بدع-التعزية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_124/12403.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":8487,"question":"أولى رسائل هذه الحلقة سماحة الشيخ رسالة وصلت إلى البرنامج من المدينة المنورة، باعثها أخونا صالح عبد الرحمن الصويان أخونا يسأل عن مؤتمر يقول: إنه عقد في أمريكا وهذا المؤتمر من ضمن توصياته التنبيه على بعض المنتجات، ذلكم أنها تحوي شحم الخنزير، ومن تلكم المنتجات صابون ومعجون وجبن وما أشبه ذلك، ويرجو التوجيه من سماحة الشيخ، هل لديكم علم عن هذا المؤتمر وهل لديكم علم عن تلكم المنتوجات ويرجو التوجيه للناس لو سمحتم؟","title":"التنبيه على بعض المنتجات المخلوطة بشحم الخنزير","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد وجه إلينا أسئلة عن هذا الذي ذكره السائل من المنتجات وما حصل في هذا المؤتمر وأحيل إلى الجهات المختصة هنا في المملكة، وذكرت أنه لم يرد إلى هذه المملكة شيء من ذلك، وأنه لم يثبت عليها شيء من ذلك. فالذي لدينا هو أنه لم يثبت لدينا شيء من هذا الذي يدعى أنه من لحم الخنزير أو من شحم الخنزير، وليس كل من أذاع ذلك أو ذكره يعتمد؛ لأن كثيراً من الشركات يعادي بعضها بعضاً ويكيد بعضها لبعض. فالواجب أن لا يقبل ذلك إلا من أهل العلم والأمانة والثقة الذين وقفوا على الحقيقة وعرفوا صحة ما يدعيه بعض الناس من وجود شحم الخنزير أو لحم الخنزير في أي شيء، سواء كان جبناً أو صابوناً أو غير ذلك. أما دعاوى بعض الشركات فلا يعتمد عليها؛ لأنها إما شركات كافرة وإما شركات متهمة، والأصل حل ما ذكر من الصابون والجبن ونحوه هذا هو الأصل، والله يقول جل وعلا: يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الأَرْضِ حَلالًا طَيِّبًا [البقرة:168] فالأصل حل هذه الأشياء إلا بدليل يدل على تحريمها؛ لأن الله أباح لنا طعام أهل الكتاب فما وردنا من أهل الكتاب فالأصل فيه الحل، وهم اليهود والنصارى حتى نعلم دليلاً على تحريمه أو شيئاً مادياً معلوماً يدل على تحريمه. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6546/التنبيه-على-بعض-المنتجات-المخلوطة-بشحم-الخنزير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12601.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":8551,"question":"آخر سؤال للأخ (علي . ع. م) من الزلفي في رسالته هذه، يقول: هناك بعض الأطعمة والمشروبات المعلبة مكتوب عليها خالي من الخنزير، أو خالي من الكحول، فهل يكتفى بمثل هذه الكتابة وتتناول، أم أن هناك حرج؟","title":"هل يكفي في المأكولات كتابة خالي من الخنزير أو الكحول؟","answer":"الجواب: لا بأس يكتفى بهذه الكتابة إذا كانت من بلاد أهل الكتاب بلاد النصارى يكتفى بهذا، الأصل حل أطعمتهم لنا ولو لم يكتبوا عليها شيء، فإذا كتب عليها كان من باب أولى يعني، إلا إذا علم أن هذا كذب، وأن هذا الشيء فيه خنزير أو فيه شيء من النجاسات الأخرى، فتكون الكتابة لا قيمة لها، إذا علم بالبينة بالثقات أن هذا كذب، أما إذا لم يعلم شيء فالأصل الإباحة والسلامة.\nالمقدم: جزاكم الله خير وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6635/هل-يكفي-في-الماكولات-كتابة-خالي-من-الخنزير-او-الكحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_206/20608.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":8554,"question":"آخر سؤال للأخ (علي . ع. م) من الزلفي في رسالته هذه، يقول: هناك بعض الأطعمة والمشروبات المعلبة مكتوب عليها خالي من الخنزير، أو خالي من الكحول، فهل يكتفى بمثل هذه الكتابة وتتناول، أم أن هناك حرج؟","title":"هل يكفي في المأكولات كتابة خالي من الخنزير أو الكحول؟","answer":"الجواب: لا بأس يكتفى بهذه الكتابة إذا كانت من بلاد أهل الكتاب بلاد النصارى يكتفى بهذا، الأصل حل أطعمتهم لنا ولو لم يكتبوا عليها شيء، فإذا كتب عليها كان من باب أولى يعني، إلا إذا علم أن هذا كذب، وأن هذا الشيء فيه خنزير أو فيه شيء من النجاسات الأخرى، فتكون الكتابة لا قيمة لها، إذا علم بالبينة بالثقات أن هذا كذب، أما إذا لم يعلم شيء فالأصل الإباحة والسلامة.\nالمقدم: جزاكم الله خير وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6635/هل-يكفي-في-الماكولات-كتابة-خالي-من-الخنزير-او-الكحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_206/20608.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":8625,"question":"له سؤال أخير في هذه الرسالة يقول فيه: ما حكم أكل لحوم المعلبات المستوردة من البلاد غير الإسلامية؟","title":"حكم أكل الأطعمة المستوردة من البلاد غير الإسلامية","answer":"الجواب: اللحوم المعلبة فيها تفصيل، إذا كانت مستوردة من بلاد أهل الكتاب من اليهود والنصارى فالأصل فيها الحل؛ لأن الله سبحانه أباح لنا طعام أهل الكتاب، وعلينا أن نتحرى ونحذر ما حرم الله علينا، وهذا لو كان بيننا وبين اليهود اتصال وإلا الآن ليس بيننا وبينهم إلا الحرب؛ لكن من جهة أهل الكتاب من النصارى كفرسنا وإنجلترا وأمريكا وأشباههم اللحوم التي تأتي منهم حل لنا إذا لم نعلم أنها ذبحت على غير الشرع، كالخنق وضرب الرأس حتى تموت ونحو ذلك، وهكذا لو قدر أن إنساناً وصل إليه طعام أهل الكتاب من اليهود ، فإن طعام أهل الكتاب من حيث هم يهود أو نصارى حل للمسلمين إلا أن يعلم المسلم أنهم ذبحوه ذبحاً غير شرعي.\nأما الذبائح المعلبة من المجوس عباد الأوثان أو من الشيوعيون من السوفيت، من الصين الشعبية، من بلغاريا.. من رومانيا، البلاد الشيوعية فهذه البلاد ذبائحهم لا تحل حتى يتولاها مسلم أو كتابي، أما إذا تولاها الشيوعي أو الوثني أو المجوسي فهؤلاء ذبائحهم محرمة؛ لكفرهم وضلالهم وكونهم أكفر من اليهود والنصارى ، نسأل الله العافية. نعم.\nالمقدم: نعم، جزاكم الله خير وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6765/حكم-اكل-الاطعمة-المستوردة-من-البلاد-غير-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_211/21106.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":8634,"question":"له سؤال أخير في هذه الرسالة يقول فيه: ما حكم أكل لحوم المعلبات المستوردة من البلاد غير الإسلامية؟","title":"حكم أكل الأطعمة المستوردة من البلاد غير الإسلامية","answer":"الجواب: اللحوم المعلبة فيها تفصيل، إذا كانت مستوردة من بلاد أهل الكتاب من اليهود والنصارى فالأصل فيها الحل؛ لأن الله سبحانه أباح لنا طعام أهل الكتاب، وعلينا أن نتحرى ونحذر ما حرم الله علينا، وهذا لو كان بيننا وبين اليهود اتصال وإلا الآن ليس بيننا وبينهم إلا الحرب؛ لكن من جهة أهل الكتاب من النصارى كفرسنا وإنجلترا وأمريكا وأشباههم اللحوم التي تأتي منهم حل لنا إذا لم نعلم أنها ذبحت على غير الشرع، كالخنق وضرب الرأس حتى تموت ونحو ذلك، وهكذا لو قدر أن إنساناً وصل إليه طعام أهل الكتاب من اليهود ، فإن طعام أهل الكتاب من حيث هم يهود أو نصارى حل للمسلمين إلا أن يعلم المسلم أنهم ذبحوه ذبحاً غير شرعي.\nأما الذبائح المعلبة من المجوس عباد الأوثان أو من الشيوعيون من السوفيت، من الصين الشعبية، من بلغاريا.. من رومانيا، البلاد الشيوعية فهذه البلاد ذبائحهم لا تحل حتى يتولاها مسلم أو كتابي، أما إذا تولاها الشيوعي أو الوثني أو المجوسي فهؤلاء ذبائحهم محرمة؛ لكفرهم وضلالهم وكونهم أكفر من اليهود والنصارى ، نسأل الله العافية. نعم.\nالمقدم: نعم، جزاكم الله خير وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6765/حكم-اكل-الاطعمة-المستوردة-من-البلاد-غير-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_211/21106.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":8665,"question":"تقول أيضاً: أنها تشرب الدخان وتقرأ القرآن، فهل يجوز لها قراءة القرآن وهي تدخن؟","title":"حكم قراءة المدخن للقرآن","answer":"الجواب: الواجب عليك -أيها الأخت- الحذر من شرب الدخان، الدخان محرم وفيه أضرار كثيرة، فالواجب على الرجال والنساء تركه والحذر منه فهو منكر لا يجوز بيعه ولا شراؤه ولا استعماله، فعليك أن تتقي الله وأن تحذريه، ولا مانع من قراءة القرآن للمدخن، قراءة القرآن أمر مطلوب، لكن ينبغي لمن أراد قراءة القرآن أن يغسل فمه بعد التدخين ويستعمل ما أمكن من الطيب، من السواك، من فرشة يغسل بها الفم حتى تزول الرائحة الكريهة، حتى يستعمل كتاب الله وكلامه بعد إزالة هذه الرائحة الخبيثة، وهكذا من أكل ثوماً أو بصلاً ينبغي له أن يستعمل ما يخفف هذه الرائحة قبل أن يقرأ إذا تيسر له ذلك.\nعلى كل حال قراءة القرآن شيء مطلوب وعبادة عظيمة لا ينبغي تركها ينبغي العناية بها، لكن شرب الدخان هو المنكر الذي يجب الحذر منه، وتركه والتواصي بتركه، كما يجب ترك شرب المسكرات كلها. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6813/حكم-قراءة-المدخن-للقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21418.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":8775,"question":"يسأل الأخ مساعد أيضاً ويقول: هل الدجاج المستورد واللحوم المستوردة من الخارج بها شبهة من الحرمة أم لا؟ علماً بأنني عندي شك فيها وأكره أكلها. أفتوني جزاكم الله خير بالرغم من كتابة: ذبح على الطريقة الإسلامية؟","title":"طعام أهل الكتاب حلال إلا بعلم بما يحرمه بيقين","answer":"الجواب: اللحوم المستوردة قسمان:\nما كان مستورداً منها من بلاد أهل الكتاب النصارى أو اليهود لو جاء من بلادهم فيها هذا حل لنا؛ لأن الله أباح لنا طعام أهل الكتاب، فما استورد من طعامهم فهو حل لنا إلا أن نعلم يقيناً ما يحرمه من كونه ذبح على غير وجه الشرع كالخنق، أما إذا لم نعلم فالأصل هو حله لنا، وهذه البلاد -بحمد الله- السعودية يعتني القائمون على أمورها بألا يرد إليها إلا شيء سليم، فما ورد إلى بلاد السعودية من بلاد النصارى فهو أمر قد اعتني به، والأصل فيه الحل والإباحة إلا إذا علمت أن هذا الشيء ورد من فلان ابن فلان أو من الشركة الفلانية التي تذبح كذا وكذا ذبحاً مخالفاً للشرع، إذا علمت هذا يقيناً فلا تأكل منه، وإذا تيسر لك أن تذبح لنفسك مما أعطاك الله من الدجاج وغيره فهذا خير وأطيب والحمد لله. نعم..\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6931/طعام-اهل-الكتاب-حلال-الا-بعلم-بما-يحرمه-بيقين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21904.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":8916,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أبو مصعب، أبو مصعب يسأل عن عدة أمور -سماحة الشيخ- من بينها يقول: إن هناك أناسًا يقولون: إن الببسي حرام شربه؛ وذلك لوجود الكافين فيه؛ وكذلك عصير التفاح رغم أنه مكتوب على العلبة عصير تفاح فقط، وكذلك البيرة رغم أنه مكتوب عليها خالية من الكحول، وكذلك الكافي، وكذلك الجبن، أفتوني مأجورين إننا نعيش بين أناس كل هذا لديهم حرام ولا يجوز شربه ولا أكله، ما رأي الشرع أولًا؟ وكذلك رأيك بصراحة، والخطاب موجه لكم سماحة الشيخ خاصة، ما رأيكم بصراحة في هذه الأشياء، وحبذا لو يصدر من سماحتكم كتيب يبين فيه عن هذه الأشياء التي أصبح كل يفتي من عنده بخصوصها، وكذلك القياس على كيفه وهواه جزاكم الله خيرا؟","title":"حكم المشروبات والعصائر والبيرة الخالية من الكحول","answer":"الجواب: أما الببسي والعصير والبيرة فهذه لا حرج فيها وليس فيها شيء من الكحول، يعني: من شيء من المسكر، ولا حرج في شربها، وقد كان فيما مضى من الزمان من نحو عشر سنوات بل أكثر من عشرين سنة تقريبًا، كانت منافسات بين بعض الشركات في ذلك، وكتبت بعض الشركات أن في الببسي وفي مشتقاته شيئًا من الكحول من المسكر، ثم بعد التحقيق لم يثبت شيء من ذلك، فهو سليم ولم يزل الناس يتعاطونه ويشربون منه الكثير فلم يتأثر أحد منهم بذلك لا سكرًا ولا خدورًا، فالقول بأنه ممنوع، قول لا أصل له ولا وجه له.\nوهكذا ما يتعلق بالبيرة قد سألنا عنها الخبراء بها، فذكروا أنها سليمة، لكن يوجد في بعض أنواع البيرة في الخارج ما يقال: إن فيه ما يسكر، فعلى المؤمن أن يحذر ما قيل: إنه مسكر، إذا كان في البلاد الخارجية، ويحذر شربه، وما كان هنا فهو معلوم أنه لا يسكر، وقد زعم بعض الناس أن فيها قليلًا كواحد ونص أو واحد في المائة من المسكر، ولكن لم يثبت هذا عندنا.\nوالقاعدة: أن ما أسكر كثيره فقليله حرام، فلم يثبت عندنا أن فيها شيئًا مما يسكر كثيره، فالأصل فيها الحل والإباحة، وهكذا العصير من التفاح أو البرتقال أو العسل أو العنب أو من أي شيء، العصير من العنب أو التفاح أو البرتقال أو غير ذلك لا حرج فيه إذا لم يشتد، فهذه الأشياء الموجودة التي ليس فيها شدة بل هي سليمة من الشدة وسليمة من الإسكار لا حرج فيها.\nوقد كان النبي ﷺ ينبذ له الزبيب وغيره اليوم واليومين والثلاث فيشرب ذلك، فإذا أكمل الثالثة سقاه بعض الناس أو أراقه خشية أن يشتد ويتخمر، فكل عصير أو نبيذ لم يشتد فإنه حل لنا، وإذا طرح فيه ما يمنع اشتداده قد طرح بالعصير أو في النبيذ ما يمنع اشتداده بقي على حله؛ لأنه إنما يحرم بالاشتداد والتخمر، فإذا لم توجد هذه العلة بقي على أصله وهو الإباحة.\nوأما الجبن ونحوه، فهذا قد قيل فيه ما قيل، قد قيل: إنه فيه شيء من الخنزير، وقد كتبنا لوزارة التجارة في هذا، وأجابت الوزارة بأن هذا قد اختبر في عدة مخابر، وأن جميع ما يوجد في المملكة سليم مما يقال عنه أن فيه شيئًا من الخنزير، وأن المخابر التي لدى الوزارة قد اعتنت بهذا الشيء فلم تجد فيه شيئًا مما يقوله الناس، والأصل الإباحة في الأطعمة حتى يعلم تحريمها، وكذلك الجبن الأصل فيه الإباحة حتى يعلم تحريمه، كما أن الأصل في أطعمة اليهود والنصارى الحل حتى يعلم تحريمها.\nقد ذكرتْ الوزارة أن جميع ما يجيء إلى المملكة من اللحوم المستوردة يعتنى بها، ويحرص على سلامتها، وهناك من يعتني بذلك من جهة الوزارة في البلدان التي تستورد منها اللحوم، فنسأل الله أن يزيدها من التوفيق، ولا يزال لنا معها اتصال وعناية حتى ينتهي المشكِل إن شاء الله.\nالمقدم: جزاكم الله خيرًا، مطالبة أخينا سماحة الشيخ بإصدار كتيب عن هذا الموضوع لعله يوفي..\nالشيخ: هذا إن شاء الله ننظر فيه، ولعله يتيسر إن شاء الله عن قريب.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7073/حكم-المشروبات-والعصاىر-والبيرة-الخالية-من-الكحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_170/17004.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":9029,"question":"نعود إلى السودان عبر رسالة وصلت إلينا من أحد الإخوة المستمعين يقول: أخوكم من أهل السنة والجماعة، أخونا له ثمانية أسئلة سؤاله الأول يقول: هل العزاء بعد الدفن لأهل الميت في مكان خاص لمدة ثلاثة أيام مشروع مع إحضار الطعام؟","title":"حكم تعزية أهل الميت ثلاثة أيام مع إحضار الطعام","answer":"الجواب: ليس لهذا أصل، أما العزاء فليس له محل معين، يعزيهم في الطريق، يعزيهم في المسجد، يعزيهم في المقبرة قبل الدفن أو بعد الدفن، كل هذا لا بأس به، أما أنه يصنع طعامًا للناس للمعزين وغيرهم فهذا لا يجوز من أعمال الجاهلية، ولكن لو جلسوا في بيتهم وجاءهم المعزون من غير أن يصنعوا طعامًا للناس فلا بأس، إذا جاءهم معزي في البيت فعزاهم وخرج في ليل أو نهار لا بأس بهذا، أما أنهم يصنعون طعامًا للناس ليكرموهم إذا جاءوا يعزون هذا ليس له أصل، وهو من عمل الجاهلية، يقول جرير بن عبدالله البجلي : كنا نعد الاجتماع إلى أهل الميت وصنعة الطعام بعد الدفن من النياحة أما كون جيرانهم أو أقاربهم يصنعون لهم طعامًا ويرسلونه إليهم هذا لا بأس به هذا مشروع؛ لأن الرسول ﷺ لما أتى نعي جعفر بن أبي طالب  يوم مؤتة قال النبي ﷺ لأهله: اصنعوا لآل جعفر طعامًا فقد أتاهم ما يشغلهم، فإذا صنع الأقارب أو الجيران لأهل الميت طعامًا وبعثوه إليهم أيام المصيبة لأنهم مشغولون فهذا مستحب ولا حرج فيه، إنما الحرج في كون أهل الميت هم الذين يصنعون، لكن إن صنعوا طعامًا لهم لأنفسهم أو لضيوفهم جاءهم ضيوف فصنعوا لهم لا يضر، لكن لا يتعمدون شيئًا من أجل الميت أو عادة من أجل الميت، لكن لو أنهم صنعوا طعامهم ما جاءهم من أحد شيء ما أعطاهم أحد شيء، صنعوا طعامهم لا بأس، أو نزل بهم ضيوف فزادوا في طعامهم لأجل الضيوف لابأس. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7187/حكم-تعزية-اهل-الميت-ثلاثة-ايام-مع-احضار-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_176/17612.mp3","categories":["أحكام التعزية"]},{"id":9066,"question":"نعود مع مطلع هذه الحلقة إلى رسالة أحد الإخوة من السودان الذي يقول: أخوكم من أهل السنة والجماعة أخونا عرضنا في حلقة مضت سؤالًا واحد من أسئلة له ثمانية ضمنها رسالته، وفي هذه الحلقة نرجو أن نتمكن من عرض بعض الأسئلة، يقول في هذه الحلقة: هل من السنة أن تذهب زوجتي للعزاء داخل القرية وخارجها في القرى المجاورة لنا بالسيارة مع النساء؟","title":"حكم خروج المرأة للعزاء مع النساء بالسيارة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا مانع من ذهاب زوجتك أيها السائل لتعزية إخوانها وأقاربها في القرية لا بأس بذلك مع النساء إلا إذا كان المحل بعيدًا يسمى سفرًا فلابد من محرم، أما إذا كانت القرية وما يعد تابعًا للقرية هذا لا بأس به ولو كانت ليس معها محرم، يكفي النساء معها، والتعزية مستحبة من الرجال والنساء لأقاربهم ولجيرانهم ولأحبابهم؛ لأن المصيبة لها أثر في النفوس فالتعزية مشروعة. نعم.","link":"https://binbaz.org.sa/fatwas/7226/حكم-خروج-المراة-للعزاء-مع-النساء-بالسيارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_179/17901.mp3","categories":["أحكام التعزية"]},{"id":9108,"question":"هل يشرع مواساة أهل العزاء بالمال؟","title":"مواساة أهل الميت بالمال","answer":"الجواب: نعم يشرع إذا كانوا فقراء محاويج يشرع أن يواسوا، إذا كان عميدهم الذي ينفق عليهم توفي وليس وراءه من يقوم بحالهم وهم محتاجون فيما يعلمه المحسن إليهم فلا بأس يشرع لهم، يشرع لجيرانهم ولأقاربهم أن يواسوهم سواء وقت الموت أو بعد الموت بمدة على حسب الحال، أما أن يساعدوهم على إقامة مأتم فلا، لكن يساعدوهم لفقرهم بمال بطعام بملابس لا بأس، لكن على وجه لا يكون فيه إعانة على منكر. نعم.","link":"https://binbaz.org.sa/fatwas/7259/مواساة-اهل-الميت-بالمال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_179/17902.mp3","categories":["أحكام التعزية"]},{"id":9149,"question":"السؤال الثالث والأخير في رسالة الأخت (ف. ع. س) من اليمن تعز تقول فيه: ما حكم الشرع في شرب الدخان والشمة؟ وما هو دليل التحريم، أفيدونا أفادكم الله؟","title":"حكم شرب الدخان والشمة","answer":"الجواب: الدخان وفروعه ومشتقاته كلها محرمة، ودليل ذلك قول الله : يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4] أمر الله نبيه ﷺ أن يقول للناس:  أحل لكم الطيبات لما سألوه  ماذا أحل لهم ؟ أمره الله أن يقول لهم:  أحل لكم الطيبات ، وأخبر سبحانه عن وصف نبيه محمد ﷺ في سورة الأعراف قال: وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ [الأعراف:157]، وقد أجمع العارفون بالدخان من الأطباء وغير الأطباء على أنه خبيث ضار ضرراً كبيراً بمتعاطيه، فهو معروف بأنه سبب لأمراض كثيرة من داء السرطان وداء السكتة وأدواء أخرى معروفة ذكرها العلماء وألفوا فيها المؤلفات، فهو محرم لخبثه وضرره الكثير، وربما أفقد صاحبه شعوره إذا تأخر عنه أو أكثر منه، فهو ذو مضرة عظيمة، فيجب على كل مسلم تركه، على الرجال والنساء جميعاً، فيحرم بيعه وشراؤه والتجارة فيه واستعماله هو ومشتقاته من شمة وغيرها. رزقني الله وإياكم العافية. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7309/حكم-شرب-الدخان-والشمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_230/23012.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":9183,"question":"ما حكم أكل لحم الخيل وأكل لحم الضبع؟","title":"حكم أكل لحم الخيل والضبع","answer":"الجواب: لحم الخيل حل قد أذن فيه النبي عليه الصلاة والسلام، وهكذا الضبع حل بالنص عن النبي عليه الصلاة والسلام، فالخيل والضباع حل لنا بخلاف الذئاب والأسود والنمور والكلاب هذه محرمة، وهكذا كل ذي ناب السباع كله محرم ما عدا الضبع فهو مستثنى بالنص، والخيل حل لنا بالنص عن النبي عليه الصلاة والسلام، كما ذكر جابر بن عبدالله الأنصاري ، قال: نهى رسول الله ﷺ عن لحوم الحمر الأهلية وأذن في لحوم الخيل، وقالت أسماء بنت أبي بكر رضي الله تعالى عنها: نحرنا على عهد النبي ﷺ فرسًا فأكلناه ونحن في المدينة متفق على صحته.\nفالحاصل أن الخيل حل لنا، وهكذا الضبع حل على الصحيح، أما الحمر الأهلية المعروفة والبغال هذه محرمة البغال والحمر محرمة، وهكذا السباع كالذئب والنمر والأسد والكلب والهر كل هذه محرمة. نعم.","link":"https://binbaz.org.sa/fatwas/7343/حكم-اكل-لحم-الخيل-والضبع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_180/18007.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":9217,"question":"هل من شم رائحة الدخان يأخذ حكم المدخن وينطبق عليه؟","title":"حكم شم رائحة الدخان","answer":"الجواب: إذا تعمد ذلك وصار يتلذذ بذلك يعمه المنع والتحريم، أما إذا شمه من غير قصد بلي به في المكان أو في الطريق فلا يضره ذلك.","link":"https://binbaz.org.sa/fatwas/7377/حكم-شم-راىحة-الدخان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_182/18207.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":9258,"question":"أختنا أيضاً تسأل وتقول: سمعت أن هناك بعض المشروبات تحتوي أيضاً على شيء من الكحول، وقرأت في كتاب الخمر بين الطب والفقه للدكتور محمد علي البار أن فيها نسباً ضئيلة من الكحول، ولكن معالجته بمواد أخرى حالت دون الإسكار لكن المادة موجودة؛ لأن هناك قاعدة علمية تقول: إن المادة لا تفنى ولا تستحدث، فهل يحرم تناول تلك الأشياء؟","title":"حكم المشروبات التي تحتوي على نسبة من الكحول","answer":"الجواب: القاعدة في هذا مثلما قال النبي ﷺ: ما أسكر كثيره فقليله حرام إذا كان ذلك الشيء كثيره يسكر يغير العقل فقليله محرم، أما إذا كانت المادة فيه ضعيفة لا يسكر معها كثيره فلا حرج في ذلك ولا يضر، هذه القاعدة الشرعية سواء كان ذلك يشرب أو يؤكل، إن كان كثيره يسكر حرم الكثير والقليل، فإن كان كثيره لا يسكر لم يحرم لا كثيره ولا قليله، سواء كان مطعوماً أو مشروباً. نعم.\nالمقدم: سمعت أن هناك قائمة أصدرتموها تحتوي على شحم الخنزير وحذرتم من استعمالها كبعض أنواع الصابون والحليب والجبنة ولكني لم أحصل على شيء من هذا، فهل ما قيل صحيح؟\nالشيخ: ليس بصحيح لم يصدر منا شيء في هذا، ليس بصحيح. نعم.","link":"https://binbaz.org.sa/fatwas/7421/حكم-المشروبات-التي-تحتوي-على-نسبة-من-الكحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_153/15308.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":9385,"question":"أحياناً تحدث وفاة شخص إما متعمداً للانتحار، أو شخص سكير شرب مسكراً يحتوي على كمية كبيرة من السكر أو المسكرات المؤدية للوفاة، أو شخص اعتدي عليه بالقتل للخلاص من شره فهل يجوز مواساة والدة المتوفى بسبب من هذه الأسباب، أو من يمت إليه بصلة، حيث أنني أتردد كثيراً هل أذهب أم لا، فتوجهت إليكم لترشدوني إلى ما يرضي الله سبحانه وتعالى، جزاكم الله خيراً ورضي عنكم؟","title":"حكم تعزية أهل الميت العاصي","answer":"الجواب: نعم، لا بأس بالتعزية، بل تستحب التعزية وإن كان بهذه المثابة، وإن كان عاصياً، إذا انتحر أو قتله من اعتدى عليه، أو قتل قصاصاً، أو قتل حداً كالزاني المحصن لنفسه، وهكذا من شرب الخمر حتى مات بسبب ذلك إذا كان لم يستحل ذلك ولم يوجد به ما يوجب ردته من الأعمال أو الأقوال فهذا عاصي ولا مانع من تعزية أهله في ذلك، ولا مانع من الدعاء له بالمغفرة والرحمة، ويغسل ويصلى عليه، لكن لا يصلي عليه أعيان المسلمين كالسلطان والقاضي ونحو ذلك، يصلي عليه بعض الناس من باب الزجر عن عمله السيئ، إذا كان قتل نفسه أو مات بسبب تعاطيه المسكرات، أما إذا مات بعدوان غيره عليه بظلم اعتدى عليه ظلماً فهذا مظلوم يصلى عليه ويدعى له، أو كذلك إذا مات بالقصاص بأن قتل قصاصاً لأنه قتل فقتل قصاصاً هذا يصلى عليه أيضاً ويدعى له ويعزى أهله في ذلك إذا كان مسلماً، إذا كان ليس عنده ما يوجب ردته، نعم. نسأل الله العافية.\nالمقدم: بارك الله فيكم. إذاً المنتحر يصلى عليه لكن تصلي عليه فئة من الناس غير فئة الأعيان؟\nالشيخ: نعم ؛ لأنه أتى منكراً عظيماً، والنبي ﷺ لما أخبر عن رجل قتل نفسه قال: أما أنا فلا أصلي عليه عليه الصلاة والسلام.\nالمقدم: وترك البقية يصلون عليه؟\nالشيخ: نعم، لم يمنع الناس. نعم.","link":"https://binbaz.org.sa/fatwas/7549/حكم-تعزية-اهل-الميت-العاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_157/15703.mp3","categories":["أحكام التعزية"]},{"id":9423,"question":"وهذه رسالة وردتنا من جمهورية اليمن الجنوبية من محمد عثمان نعمان يقول في رسالته: في أيام الخميس أخزن القات من الساعة الثانية بعد الظهر وحتى الساعة الواحدة بعد منتصف الليل، ثم أقوم بعد ذلك بأداء صلاة العصر والمغرب والعشاء مرة واحدة، هل هذا يجوز أم لا، أفيدوني بارك الله فيكم؟","title":"أسباب القول بتحريم القات","answer":"الجواب: أولاً: القات من جملة المحرمات؛ لما فيه من الضرر العظيم حسب ما أخبرنا جماعة من أهل العلم العارفين به، فينبغي لك يا أخي تركه لما فيه من الأضرار الكثيرة.\nثانياً: كونه يحمل أصحابه على أن يخزنوا مدة طويلة يترتب عليها ترك الصلاة في وقتها، هذا مما يوجب تحريمه أيضًا؛ لأنه يجر إلى باطل وإلى منكر، فإذا ترك الصلاة في الوقت أمر منكر ومحرم، وقد ذهب جمع من أهل العلم إلى أن العبد إذا ترك الصلاة عمداً حتى خرج وقتها كفر؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر رواه الإمام أحمد وأبو داود والترمذي والنسائي وابن ماجة بإسناد صحيح، من حديث بريدة .\nوروى مسلم في الصحيح عن جابر ، عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة فالتخزين من الساعة ثنتين إلى الساعة الواحدة ليلاً هذا زمن طويل، ضيع صلاة العصر وصلاة المغرب وصلاة العشاء، وهذا منكر عظيم يجب عليك يا عبد الله أن تدع ذلك، وأن تحذر هذه الورقة أو هذا النبات الذي أضر بك وأوجب لك هذا العمل السيئ. فالمقصود أن القات في نفسه منكر، حسب ما ذكر أهل العلم العارفون به.\nوقد انعقد مؤتمر في المدينة منذ سنتين أو ثلاث فيما يتعلق بالمخدرات، فأجمع أعضاء المؤتمر على أنه محرم أعني: القات، وإن توقف في ذلك بعض إخواننا من علماء اليمن، لكن ينبغي لك يا أخي على الأقل أن تبتعد عنه احتياطاً، وإن لم تقل بالتحريم، وإن لم تقنع بالتحريم، فينبغي لك أن تدعه وأن تبتعد عنه؛ لما فيه من المضرة العظيمة ولما فيه أيضاً من ترك الصلوات، فإن التخزين جرك إلى هذا العمل السيئ، والواجب أن تؤدى الصلاة في وقتها، وفي الجماعة أيضاً مع المسلمين في المساجد، فاحذره يا عبد الله! واتق الله! واترك هذا البلاء وهذا العمل المنكر وصل الصلاة في وقتها مع إخوانك المسلمين في بيوت الله، هداك الله ووفقك وكفاك شر نفسك وهواك، وكفى إخواننا في اليمن شر هذا القات، وأعانهم على تركه. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7588/اسباب-القول-بتحريم-القات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25502.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":9601,"question":"أولى الرسائل وردت من المرسل يحيى حسن أفندي من اليمن الشمالي بني قيس، يسأل يقول: إذا كان هناك ابن صغير لشاة وهو ما يعرف بالطلي الصغير أو غيره، وقد ماتت أمه بعدما ولد، وغذي على لبن حيوان محرم الأكل، فهل يؤكل أم لا أفيدونا أفادكم الله؟","title":"حكم أكل الحيوان المباح المرتضع من لبن حيوان محرم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإذا غذي الطلي أو غيره من الحيوانات المباحة على لبن محرم كلبن الحمار أو الكلب أو نحو ذلك؛ فإنه لا يحرم بذلك، بل يبقى حلالاً، ويكون حكمه حكم الجلالة، يطعم الطيب ويسقى الطيب مدة من الزمن يغلب على الظن نظافته فيها وطهارته فيها ويكفي، قال بعض أهل العلم: ثلاثة أيام، وبعضهم قال: سبعة أيام، فعلى كل حال ينبغي لأهله أن يسقوه اللبن الطيب، أو يعلفوه العلف الطيب سبعة أيام أو أكثر؛ فإنه بهذا يطيب وتذهب آثار اللبن الخبيث، ولا حرج في ذلك والحمد لله، كالجلالة تحبس يوم إن كانت دجاجة أو ثلاثة أيام إن كانت دجاجة أو نحوها أو سبعة أيام أو أكثر في مثل الحيوان الشاة ونحوها، وتطعم الطيب والحمد لله ويكفي. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7765/حكم-اكل-الحيوان-المباح-المرتضع-من-لبن-حيوان-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_249/24901.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":9611,"question":"السؤال الخامس: أحلال أم حرام لحم الحمير والضفادع والحصان أفيدونا أفادكم الله؟","title":"حكم أكل لحوم الحمر الأهلية والضفادع والخيول","answer":"الجواب: أما الحمير والضفادع محرم، والرسول ﷺ خطب الناس وأخبرهم أن الحمر الأهلية حرام، قال: إنها رجس وأجمع العلماء على تحريمها وهي الحمر الأهلية المعروفة أما حمر الوحش ..... ..... هذه لا بأس بها معروف أنها شكل آخر ... ، أما الحمر التي بيننا ..... أنفسنا عليها أو نحمل عليها فهذه يقال لها الحمر الأهلية، ويقال لها: الحمر الإنسية وقد حرمها النبي ﷺ، وخطب الناس في ذلك مرات يبين لهم .... .... وأنها رجس وأجمع المسلمون على تحريمها.\nوهكذا الضفادع نهى عن قتلها ولما نهى عن قتلها دل على تحريمها.\nأما الحصان فلا بأس به الخيل أحل لنا، الرسول ﷺ نهى عن لحوم الحمر الأهلية وأذن في لحوم الخيل.\nقالت أسماء بنت أبي بكر رضي الله عنها: نحرنا على عهد رسول الله ﷺ فرسًا ونحن بالمدينة فأكلناه هذا يدل على أن الخيل لا بأس بها، ولكن بعض أهل العلم يكرهها إذا كان لها حاجة وقت الجهاد، أما إذا كان ما هناك حاجة والمسلمون في غنية عنها فإنه لا بأس أن تذبح وتؤكل، أما إذا دعت الحاجة إليها في الجهاد فالأولى تركها للجهاد وعدم ذبحها ليستعين بها المسلمون في جهاد أعدائهم. نعم.","link":"https://binbaz.org.sa/fatwas/7767/حكم-اكل-لحوم-الحمر-الاهلية-والضفادع-والخيول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19309.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":9651,"question":"أولى رسائل هذه الحلقة سؤال ورد من المستمع (أ. ع. غ) من هيئة الأمر بالمعروف والنهي عن المنكر بمدينة الرياض، يقول السائل: ما حكم إطعام الدجاج بالدماء المجمدة، حيث أن كثيراً من أعلاف الدجاج التي يشتريها أصحاب مزارع الدواجن لتسمين الدواجن في الداخل أو الخارج تشتمل على الدماء المجمدة؛ لأن فيها نوعاً من البروتين الذي يساعد في نمو الدجاج أفيدونا أفادكم الله؟","title":"حكم إطعام الدجاج من النجاسات","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإطعام الدجاج أو غيرها من أنواع الحيوانات المأكولة شيئاً من النجاسات كالدماء ونحوها إذا كان الشيء قليلاً لا يضرها ولا يحرمها ولا يجعلها جلالة، وإنما تكون جلالة تحبس حتى تطهر وتنظف إذا كان الطعام النجس أكثر طعامها، أما إذا كان هو الأقل فإنه لا يؤثر، ولا يسبب حرمة في الحيوان ما دام عشرين في المائة، ثلاثين في المائة أو نحو ذلك هذا لا يضر، وإنما الذي يحرمها إذا كان أكثر كستين في المائة وسبعين في المائة ونحو ذلك، وبهذا تسمى جلالة فتحبس حتى تطعم الطيب وتسقى الطيب، فإذا حبست أياماً مناسبة طهرت وحلت، هذا إذا كان النجس هو الأكثر، أما إذا كان النجس قليلاً فإنه يغتفر كالعشرة في المائة والعشرين في المائة ونحو ذلك، حتى يكون أكثر.\nوالحبس يختلف فالدجاج يحبس ثلاثة أيام ويكفي حتى يطعم الطيب ويشرب الطيب، والحيوانات الأخرى كالغنم والبقر ونحو ذلك تحبس أكثر من ذلك تحبس سبعة أيام أو أكثر، تطعم الطيب وتسقى الطيب، فيطيب لحمها بعد ذلك ولا حرج في ذلك. نعم.\nالمقدم: بارك الله فيكم، لكن قد يكون هذا نظام متبع عند الذين يحرصون على تسمين الدواجن في أقصر وقت حتى يبيعوها؟\nالشيخ: نحن سألنا عنه كثيراً ممن يعرفون هذا يقولون: إنه شيء قليل بالنسبة إلى الطعام الآخر؛ لأنه شيء قليل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7816/حكم-اطعام-الدجاج-من-النجاسات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_251/25101.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":9803,"question":"هذه رسالة وردت إلى البرنامج من السائل محمد صالح سريحان، سوداني من الكويت، يقول في رسالته: ما حكم الفاتحة للميت، وذبح المواشي، ودفع الفلوس إلى أهل الميت؟","title":"حكم قراءة الفاتحة على الميت ومواساة أهله بالمال","answer":"الجواب: تقدم في السؤال الأول الذي قبل هذا أن التقرب للأموات بالذبائح أو بالفلوس أو بالنذور أو غير هذا أن هذا من الشرك الأكبر لا يجوز، هذا من العبادات التي لا تكون إلا لله وحده، فالذبح لله وحده، وهكذا النذور، وهكذا الصدقات كلها لله وحده، قال الله تعالى: قُلْ إِنَّ صَلاتِي [الأنعام:162] قل يا محمد: إِنَّ صَلاتِي وَنُسُكِي [الأنعام:162] يعني: ذبحي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ [الأنعام:162] لا شَرِيكَ لَهُ [الأنعام:163] وقال سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2] وقال النبي ﷺ: لعن الله من ذبح لغير الله رواه مسلم في صحيحه من حديث علي ، فالذبح لغير الله من الأولياء أو الكواكب أو الجن شرك بالله عز وجل، وهكذا للأصنام كله شرك بالله عز وجل، أما الذبح لله فهو عبادة، فإذا تقرب إلى الله بالذبائح.. بالضحايا.. بالهدايا.. بالنذور، كلها عبادة لله وحده سبحانه وتعالى، فهذه العبادة لا تصلح لغير لله، لا للأولياء ولا للأنبياء ولا للأصنام ولا للكواكب ولا لغير هذا من المخلوقات.\nوكذلك كونه يقدم نقودًا لصاحب القبر فالنقود قربة، مثلما يتقدم إلى الله بالصدقات التي يعطيها الفقراء، فإذا أعطى فقراء نقودًا فهي صدقة يرجى ثوابها من الله عز وجل، فإذا قدمها للميت فقد عبده بهذه الصدقة، عبده بهذه النقود التي يتقرب بها للميت، ويأخذها زيد وعمرو، فهذا منكر عظيم وشرك فظيع لا يجوز أبدًا، فيجب على المؤمن أن يحذر هذه الشرور وأن ينبه غيره على ذلك، والله المستعان. نعم.\nالمقدم: أنا فهمت من سؤاله -إذا أذنتم لي- سماحة الشيخ.\nالشيخ: نعم.\nالمقدم: أنه يقول: ما حكم الفاتحة للميت، يعني: لأبيه مثلًا، وذبح المواشي ودفع الفلوس إلى أهل الميت كنوع من المواساة؟\nالشيخ: إذا كان أراد هذا فله معنى آخر، أما قراءة الفاتحة فهي بدعة، كونه يقرأ الفاتحة للأموات أو على قبورهم هذا من البدع، لم يفعلها النبي ﷺ ولا أصحابه  وأرضاهم، فلا يجوز أن يقرأ للموتى الفاتحة ولا غيرها.\nأما كونه يعطى أهل الميت صدقة يساعدون فهذا لا بأس به، إذا مات ميتهم يدفع إليهم عشاء أو غداء لا بأس، فقد ثبت عن رسول الله ﷺ أنه قال لما جاء خبر جعفر بن أبي طالب  لما قتل يوم مؤتة في الشام: أمر النبي ﷺ أهله أن يصنعوا لأهل جعفر طعامًا، قال: اصنعوا لأهل جعفر طعامًا فقد أتاهم ما يشغلهم، فأمر أهله أن يصنعوا لأهل جعفر طعامًا وأن يبعث به إليهم؛ لأنهم قد أتاهم ما يشغلهم عن صنع الطعام، فإذا دفع إليهم جيرانهم طعامًا مصنوعًا أو ذبيحة ليستمتعوا بها وقت حزنهم ووقت مصيبتهم، أو نقود ليستعينوا بها على حاجاتهم فلا بأس فيما نرى لكن ليس لهم أن يصنعوا طعام -أهل الميت- ليس لهم أن يصنعوا طعام يدعون الناس إليه ويكون عندهم ولائم في بيوتهم هذه المآتم ممنوعة، لا تجوز، وقال جرير  ابن عبد الله البجلي : كنا نعد الاجتماع عند أهل الميت، وصنعة الطعام بعد الدفن من النياحة، فلا يجوز هذا، لكن الأفضل والسنة أن يصنعوا طعامًا، يصنع الجيران أو الأقارب طعامًا ويقدم لهم مصنوع، أما تكليفهم بالذبيحة أو بالنقود هذا خلاف المشروع إلا إذا فعلوه من باب الصدقة عليهم، من غير أن يقيموا وليمة عند أهل الميت ومن غير أن يكون هناك اجتماع عليها بل صدقة مجردة لينتفعوا بها لفقرهم وحاجتهم لا بأس، لكن السنة أن يبعث إليهم طعام مصنوع، خالص منتهي، يبعث إليهم ليكفوهم المئونة، حتى يأكلوا من دون كلفة ولا تعب؛ لأنهم مشغولون عن الطبخ بمصيبة الموت، هذا هو الأفضل، وهذا هو المشروع.\nأما الصدقة عليهم إذا كانوا فقراء بنقود أو ذبيحة أو طعام، فلا بأس به لكن بشرط أن لا يكون هذا الشيء لإقامة المأتم في البيت وصنع طعام للناس هذا لا يجوز، سواءً كان من أموالهم أو مما يدفع إليهم من جيرانهم، لا يفعل هذا. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7970/حكم-قراءة-الفاتحة-على-الميت-ومواساة-اهله-بالمال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_197/19702.mp3","categories":["أحكام التعزية"]},{"id":9856,"question":"تقول أيضاً: سمعت من برنامجكم الكريم في إحدى الحلقات، عندما سأل أحد المستمعين عن العزاء بأنه إذا مات الميت يأتي الناس يعزون أهله فيه ويقدمون لهم النقود والذبائح ويسجلونها كالدَّين، فأجبتم بأن هذا لا يجوز، وأنه إذا قضي دين الميت من هذه النقود فلا يجوز؟ أفيدونا أفادكم الله.","title":"حكم تقديم النقود والطعام لأهل العزاء","answer":"الجواب: هذا فيه تفصيل: ولعل بعض المتكلمين في هذا البرنامج من المشايخ تكلم فيه بشيء، وهذا فيه تفصيل: إذا كان الذي أتى بالهدية من طعام أو نقود قصده مواساة أهل الميت، وقصده الإحسان إليهم فهذا لا شيء فيه، فقد أمر النبي ﷺ أهله أن يصنعوا طعاماً لأهل الميت لما أتى نعي ابن عمه جعفر بن أبي طالب رضي الله تعالى عنه، فقال: اصنعوا لآل جعفر طعاماً، فقد أتاهم ما يشغلهم فإذا كان أهل الميت فقراء وصنع لهم إخوانهم أو قراباتهم أو جيرانهم طعاماً أو كانوا غير فقراء أيضاً ولكن صنعوا لهم من أجل أنهم مشغولون عن صنع الطعام بسبب المصيبة هذا لا بأس به، أو أعطوهم هدية لأنهم فقراء أو نقوداً لأجل يقيمون بها حاجاتهم فلا بأس بذلك، أما إذا كان متفقاً عليها أنها سلفة، وأنهم يردونها عليهم إذا أصابهم موت وصار عندهم عزاء، أن هؤلاء يردون عليهم مثلما أخذوا فهذا لا ينبغي هذا ليس بطيب، هذا ليس بطيب وإن أخذوه على أنه سلفة لحاجتهم، وقرضاً لحاجتهم ثم ردوه عليهم مقابل فلا بأس، لكن هذا قد يضيع عليهم، وقد لا يبالى به، ما دام أصحابه قد أرادوه قرضاً، أو أرادوه يعني معاوضة لهم في المستقبل، فترك هذا أولى وأحوط؛ لأن هذا قد يفوت على الناس، قد لا يموت عندهم وقد لا يحصل لهم عزاء في وقت قريب وينسى، فينبغي رده إذا كان بهذا الطريق، لا يقبل أما إذا كان من باب المواساة، من باب الإحسان، لا من باب القرض والمعاوضة فلا بأس.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8015/حكم-تقديم-النقود-والطعام-لاهل-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26206.mp3","categories":["أحكام التعزية"]},{"id":9893,"question":"يقول هذا السائل سماحة الشيخ: هل شرب الدخان سبب من أسباب عدم إجابة الدعاء؟","title":"التدخين بين قبول الدعاء ومنعه","answer":"الجواب: كل المعاصي من أسباب عدم الإجابة، جميع المعاصي من أسباب عدم الإجابة، فينبغي الحذر منها كلها، التدخين وغير التدخين، ينبغي للمؤمن أن يحذر جميع المعاصي لعله يستجاب له، ولعله يسلم من معرة الذنوب. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8061/التدخين-بين-قبول-الدعاء-ومنعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27305.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":10013,"question":"أيضًا في باب الجنائز يسأل سماحتكم يحفظكم الله ويقول: بعد دفن الجنازة يذهب أهل الميت لإحضار مقرئ يتلو القرآن الكريم لمدة ثلاثة أيام، وبعد خمسة عشر يومًا من الوفاة يذهب ذوو المتوفى إلى المقبرة وهم يحملون الخبز ويتصدقوا به، فهل هذا العمل صحيح ومشروع، جزاكم الله خيرًا؟","title":"حكم قراءة القرآن في مأتم بعد الوفاة لبضعة أيام","answer":"الجواب: وهكذا ليس مشروعًا فالقراءة على الميت أسبوع ولا يوم ولا أكثر كل هذا من البدع، ولكن يدعى له، يدعى للميت بالمغفرة والرحمة، ويتصدق عنه بما يتيسر في كل وقت ولو بعد موته بسنوات، الصدقة تنفع الميت، والدعاء ينفع الميت، الحج عنه والعمرة كذلك، قضاء دينه كل هذا ينفعه، أما إحضار مقرئ يقرأ أسبوع أو أقل أو أكثر أو عند قبره أو في بيته كل هذا لا أصل له.\nفالواجب تركه لأن الله جل وعلا لم يشرعه، ولو شرعه لبينه الرسول ﷺ وبينه أصحاب النبي عليه الصلاة والسلام، والواجب على أهل الإسلام الاتباع وعدم الابتداع. نعم.\nكذلك الذهاب إلى القبور والصدقة بالطعام أو بالخبز يوزع عند القبور لا أصل له، كل هذا من البدع، فالذهاب إلى القبور؛ تزار القبور للدعاء لهم والترحم عليهم، يقول ﷺ: زوروا القبور فإنها تذكركم الآخرة، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، وكان إذا زارها يقول ﷺ كذلك: يرحم الله المستقدمين منا والمستأخرين، هكذا السنة، أما زيارتها لتوزيع خبز أو لحوم هذا لا أصل له. نعم.\nالمقدم: جزاكم الله خيراً، سماحة الشيخ حتى ينتهي الناس عن هذه المخالفات في العزاء أو في غيره ما هي كلمتكم يحفظكم الله؟\nالشيخ: الواجب على المسلمين جميعاً أن يتقيدوا بالشرع في كل شيء في الجنائز وغير الجنائز، في صلاة الجنازة وغيرها، في جميع العبادات، لأن الله جل وعلا يقول ذاماً لقوم أحدثوا: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21]، ويقول جل وعلا: ثُمَّ جَعَلْنَاكَ عَلَى شَرِيعَةٍ مِنَ الأَمْرِ فَاتَّبِعْهَا [الجاثية:18]، ويقول ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد، ويقول عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد، فليس للناس أن يحدثوا عبادات في شرع الله ما أنزل الله بها من سلطان، لا في أمر الجنائز ولا في غير الجنائز، جميع البدع ينهى عنها، والإنسان يتقيد بالشرع، يسأل عما شرع الله يتفقه في الدين، ويسأل عما شرعه الله ويعمل بذلك، كما قال ﷺ: من يرد الله به خيرًا يفقهه في الدين، فالتفقه في الدين مطلوب ويعمل الإنسان بما علم من شرع الله .\nأما كون التعزية مشروعة كونه يزور أخاه يعزيه في البيت أو في الطريق أو في المسجد أو في الدكان أو في المزرعة لا بأس يزوره إخوانه يعزونه بأبيه في أخيه في أمه لا بأس، أما أن يتخذ لذلك طعام -يصنع طعام لهم- أو يتخذ قراء يقرءون للميت أو أشياء أخرى تفعل من أجل الميت عند الموت أو على رأس الأسبوع أو بعد أربعين يوم، أو على رأس السنة، كل هذا لا أصل له. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8182/حكم-قراءة-القران-في-ماتم-بعد-الوفاة-لبضعة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27602.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":10084,"question":"تقول عن نفسها: أخي اختلط ماله الحلال بالحرام، ونحن تورعًا لا نأكل من طعامه إلا إذا كنا في داره، والوالدة تريدنا أن نأكل وتغضب إن لم نأكل، فأيهما الأفضل هذا التورع أم طاعة الأم؟","title":"حكم الأكل من مال شخص اختلط فيه الحلال بالحرام","answer":"الجواب: لا مانع من الأكل، الحمد لله النبي ﷺ أكل من طعام اليهود وطعامهم فيه الربا وفيه ما لا يحل، مادمت لا تعلم هذا من هذا، اختلط ولا يعلم هذا من هذا فالأصل الإباحة والسلامة، فلكم أن تأكلوا من ماله وتنصحوه أن يحذر الحرام وأن يتصدق من ماله بمقدار الحرام حتى تبرأ ذمته.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8253/حكم-الاكل-من-مال-شخص-اختلط-فيه-الحلال-بالحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27612.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":10369,"question":"ما حكم قراءة القرآن على الأموات أثناء التعزية وعند زيارة القبور، أو المرور بجانبها؟","title":"حكم قراءة القرآن أثناء التعزية أو عند زيارة القبور","answer":"الجواب: لا يشرع قراءة القرآن عند زيارة القبور، وإنما يسلم عليها السلام الشرعي السلام عليكم دار قوم وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية هكذا يسلم عليهم، اللهم اغفر لهم وارحمهم، السلام عليكم أهل الديار من المؤمنين المسلمين وإنا إن شاء الله بكم لاحقون، هكذا علم النبي ﷺ أصحابه، كان يعلمهم يقول إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية وفي الرواية الأخرى: يرحم الله المستقدمين منا والمستأخرين أما عند التعزية يعظهم ويذكرهم مثل الآية الكريمة: وَبَشِّرِ الصَّابِرِينَ ۝ الَّذِينَ إِذَا أَصَابَتْهُمْْ مُصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ [البقرة:155-156] هذا لا بأس عند المصائب يذكر الآيات اللي فيها الصبر، يذكر الناس من باب النصيحة لا بأس هذا مشروع، يعزيهم ويدعو لهم ويذكرهم بالآيات والأحاديث التي فيها الحث على الصبر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8541/حكم-قراءة-القران-اثناء-التعزية-او-عند-زيارة-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27916.mp3","categories":["أحكام التعزية"]},{"id":10371,"question":"في إحدى القرى في منطقتنا قام أهل القرية بذبح فرس ووزعوا لحمه على أهل القرية بدعوى أنه مباح شرعاً، فهل ذلك صحيح؟","title":"حكم أكل لحم الخيل","answer":"الجواب: نعم، لحم الخيل مباح هذا الذي عليه جمهور أهل العلم وهو الصحيح، والرسول ﷺ أذن في لحوم الخيل، وروت أسماء بنت أبي بكر رضي الله عنهما: أنهم نحروا فرسًا على عهد النبي ﷺ في المدينة وأكلوها، فالمقصود: أن لحوم الخيل مباح، هذا هو الصواب الذي عليه جمهور أهل العلم. نعم.\nالمقدم: جزاكم الله خيرًا تنحر كالإبل أو تذبح كالبقر؟\nالجواب: تذبح كالبقر، بخلاف البغال والحمير لا، البغال والحمير هذه محرمة الحمر الأهلية المعروفة هذه محرمة، أما الخيل فإنها مباحة، الرسول ﷺ نهى عن الحمر والبغال وأذن في لحوم الخيل.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8544/حكم-اكل-لحم-الخيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27917.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":10455,"question":"من المستمع جمال محمد عامل يسأل ويقول: ما رأي سماحتكم في أكل لحم الخيل المعروفة لدى العرب؟","title":"أكل لحم الخيل حلال إلا إذا احتيج إليها في الجهاد","answer":"الجواب: الخيل مباحة قد أذن فيها النبي ﷺ، ورخص في لحم الخيل، وقالت أسماء بنت أبي بكر رضي الله تعالى عنهما: نحرنا على عهد النبي ﷺ فرساً، فأكلناه ونحن في المدينة رواه الشيخان في الصحيحين.\nفالخيل مباحة، لكن إذا احتيج إليها في الجهاد لا تذبح .. لا تنحر، وإذا لم يحتج إليها وذبحت فهي حلال كالضباء وكالوعل، وكالأرنب، وكغيرها من الصيود النافعة، أما الحمر والبغال لا، ليست بحلال، محرمة، الحمر والبغال.. الحمر الأهلية والبغال المعروفة هذه محرمة لا يجوز أكلها، أما الحمر الوحشية المعروفة هذه لا بأس بها، يسمونها الوضيحي فهذه مباحة، وهي حمر منقشة لها نقش عجيب، فليست مثل الحمر الأهلية بل لها شكل آخر، ولون آخر، وخلق آخر، فلا بأس بها، أما الحمر الأهلية فإنها تحرم، المعروفة اللي كان الناس يركبونها ويستعملونها في الحرث، والسني عليها، هذه معروفة، وقد ذبحها الناس يوم خيبر، فأنكر عليهم النبي ﷺ وأكفأ القدور، وبين تحريمها عليه الصلاة والسلام.\nوهكذا البغال المعروفة لا يحل أكلها، ولكن تستعمل، تركب وتستعمل في الحمل عليها كالحمير. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8626/اكل-لحم-الخيل-حلال-الا-اذا-احتيج-اليها-في-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_319/31904.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":10643,"question":"هذا السائل غريب من حائل يقول: لحم الضبع هل هو حلال أم حرام بارك الله فيكم؟","title":"حكم أكل لحم الضبع","answer":"الجواب: الضبع صيد يقول النبي ﷺ الضبع صيد ولحمها حلال والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/8820/حكم-اكل-لحم-الضبع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28505.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":10783,"question":"هذه الرسالة وردتنا من مشعل أو البرقية وردتنا من مشعل عبدالرحمن الثقفي، يقول المستمع مشعل: أفيدوني جزاكم الله خيراً عن لحم الغراب والهدهد ولحم المنيف -أو حول المنيف.. الحقيقة أن البرقية غير واضحة- يقول: هل هو حرام أم حلال هذه اللحوم؟ وإذا كان حرام فلماذا، أفيدوني شاكرين تعاونكم؟الشيخ: الغراب؟المقدم: نعم.. الغراب والهدهد.","title":"حكم أكل لحم الغراب والهدهد","answer":"الجواب: هذا لا يجوز لحمهما لا يجوز ولا يحل، والغراب يأكل الجيف، ولهذا أمر النبي ﷺ بقتله كالفأرة والعقرب والحية والكلب العقور، كل ذلك لا يجوز أكله ولحمه حرام؛ لأن الرسول ﷺ أمر بقتله لخبثه وضرره فدل على حرمته، وهكذا الهدهد نهي عن قتله، فلا يجوز قتله ولا أكله. نعم.\nالمقدم: لكن الهدهد هل هناك علة للنهي عن أكله؟\nالشيخ: لأن إباحة أكله وسيلة لقتله، والنبي ﷺ نهى عن قتله. نعم.\nفلما نهى النبي ﷺ عن قتله دل على تحريم أكله؛ لأن حل أكله وسيلة إلى قتله، والغراب أمر بقتله لخبثه وضرره؛ فلهذا حرم كالحية والعقرب وكالكلب العقور وأشباه ذلك، وأنواع الكلاب كلها محرمة، نعم، على الصحيح من أقوال العلماء. نعم.","link":"https://binbaz.org.sa/fatwas/8958/حكم-اكل-لحم-الغراب-والهدهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_350/35004.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":10800,"question":"يسأل أيضًا ويقول: هل لحم الثعلب حرام، أم حلال؟","title":"حكم أكل لحم الثعلب","answer":"الجواب:  الثعلب فيه خلاف بين أهل العلم، والصواب أنه حرام؛ لأنه سبع، والنبي  قال: كل ذي ناب من السباع فأكله حرام ونهى عن كل ذي ناب، وهو من السباع التي تفترس الطيور والدجاج ونحوها من الحيوانات الصغيرة، يفترسها الثعلب.  وهكذا القط السنور حرام؛ لأنه أيضًا يفترس، والقاعدة مثلما قال النبي ﷺ: كل ذي ناب من السباع فأكله حرام وهكذا كل ذي مخلب من الطير يصيد كالعقاب، والباشق والصقر والباز ونحو ذلك، هذه الطيور التي لها مخالب تصيد بها حرام أكلها، كالسباع التي تفترس كالذئب، والأسد والنمر والفهد والكلب ونحو ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8974/حكم-اكل-لحم-الثعلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_352/35204.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":10874,"question":"المستمع (أ. م. حجابي) و (أ. خ. مصطفى) من السودان بعثا برسالة ضمناها بعض الأسئلة، في أحد أسئلتهم يقولون: عندما يتوفى المرء في بلدنا يجلس الأقارب في بيت المتوفى مدة خمسة أيام، أو أكثر من ذلك لاستقبال المعزين، فيقرؤون الفاتحة ويرفعون أيديهم إلى الوجه، ثم يقولون بصوت جماعي: جبر الله كسرك، ولأهل الميت: عظم الله أجرك، فما حكم الشرع في هذه العادة، وهل هي صحيحة أم أنها بدعة؟ نرجو الإفادة، جزاكم الله خيرًا.","title":"حكم الاجتماع للتعزية ورفع الصوت بالدعاء وقراءة القرآن للميت","answer":"الجواب:  هذه العادة بدعة لا أصل لها في الشرع، ولم يكن الرسول ﷺولا أصحابه يفعلون ذلك، فالواجب على المؤمن الحذر من البدع، فهي شر وبلاء، ولهذا قال -عليه الصلاة والسلام- في الحديث الصحيح: إياكم ومحدثات الأمور، فإن كل محدثة بدعة، وكل بدعة ضلالة وقال -عليه الصلاة والسلام-: من عمل عملًا ليس عليه أمرنا فهو رد، يعني: فهو مردود، وكان يقول في خطبة الجمعة -عليه الصلاة والسلام-: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ يعني: السيرة وشر الأمور محدثاتها، وكل بدعة ضلالة خرجه مسلم في صحيحه. فالمصابون يعزون في ميتهم، ويدعى لهم أن الله يجبر مصيبتهم، ويحسن عزاءهم، ويغفر لميتهم إذا كان مسلمًا، أما كونهم يجلسون للعزاء، ويتجمعون على قراءة، وعلى الأكل والشرب، ونحو ذلك، هذا لا أصل له، لكن إذا جلس في بيته الوقت المعتاد الذي يجلسه الناس في بيوتهم، وجاءه الناس يعزونه من دون إحداث شيء، بل الجلوس العادي، وإن صب لهم قهوة، أو صب لهم شاهيًا لا بأس، هذه جلسات عادية، جلسات عادية لا بأس بها. وقد كان النبي ﷺ لما جاءه خبر جعفر بن أبي طالب لما قتل في مؤتة هذا الصحابي جلس واجمًا، أو يظهر عليه أثر الحزن، عليه الصلاة والسلام. فالمقصود أن الجلوس عند المصيبة، وعند روعة المصيبة ليس فيه حرج، لكن كونه يتعمد أن يكون لهذا نظام خاص بإيجاد طعام، أو مأتم حزن، أو جمع قراء، أو قراءة خاصة يفعلونها بينهم، أو دعوات يرفعون فيها أيديهم، ويجتمعون عليها، أو ما أشبه ذلك هذا لا أصل له. أما كونه جلس في بيته الجلوس المعتاد ضحوة أو ظهرًا أو عصرًا أو مغربًا، ومر عليه جيرانه وأقاربه أو عزوه في الطريق، أو في المسجد، أو في المقبرة كله جائز والحمد لله، من دون أن يتخذ لهذا نظامًا خاصًا، نعم. المقدم: قراءة الفاتحة أيضًا سماحة الشيخ؟ الشيخ: كذلك لا أصل لهذا لا الفاتحة ولا غيرها، أما إذا قرؤوا على العادة، إذا اجتمعوا وقرؤوا من القرآن لا لأجل الميت، بل لأنهم مجتمعون، وقرأ واحد يسمعهم كتاب الله لا بأس بهذا، أما يكون لسر المصيبة، لقصد المصيبة هذا لا أصل له. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9048/حكم-الاجتماع-للتعزية-ورفع-الصوت-بالدعاء-وقراءة-القران-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_358/35802.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":10938,"question":"الأخت (ش. ح. م) من ليبيا بعثت برسالة ضمنتها جمعًا من الأسئلة هي وأخواتها، يقلن في أحد الأسئلة: في بلادنا عندما يموت إنسان يبقى أقارب الميت في العزاء مدة سبعة أيام، لا يبرحون مكان العزاء، ويتردد المعارف على مكان العزاء من ثلاثة أيام، تذبح الذبائح طيلة تلك المدة، ماذا عن ذلك؟ جزاكم الله خيرًا، ونرجو النصح والتوجيه.","title":"حكم مكث أهل الميت في البيت للعزاء مع الذبح","answer":"الجواب:  ليس للعزاء مدة معلومة، بل السنة للمؤمن والمؤمنة التعزية على أي حال كانت في الطريق، أو في البيت بعد الموت، قبل الصلاة وبعدها، وقبل الدفن وبعده، وليس لذلك مدة معلومة، ولا مكان معلوم، بل المؤمن يعزي إخوانه في الله، والمؤمنة تعزي أخواتها في الله، وأقاربها وجيرانها تعزيهم، وأما كونهم يلزمون البيت سبعة أيام، أو ثلاثة أيام، هذا شيء لا أصل له، بل يخرجون في حاجاتهم وفي أعمالهم ومن صادفه في الطريق، أو في محل العمل، أو في البيت عزاهم، وإذا جلسوا في البيت وقت الجلوس المعتاد، وجاءهم إخوانهم، وعزوهم فلا بأس، أما أنه يصنعون للناس وليمة يذبحون ذبائح من أجل الميت فهذا بدعة من عمل الجاهلية، لا أصل له، يقول جرير بن عبد الله البجلي  الصحابي الجليل : كنا نعد الاجتماع إلى أهل الميت، وصنعة الطعام بعد الدفن، كنا نعده من النياحة. فليس لأهل الميت أن يصنعوا الطعام للناس بسبب الميت، لكن إذا أهدى إليهم جيرانهم أو أقاربهم طعامًا فهذا لا بأس به، بل هو مستحب أن يهدي الجيران، أو الأقارب لأهل الميت يصنع طعامًا؛ لأنهم مشغولون بالمصيبة، فقد فعله النبي ﷺ، أمر أهل بيته -عليه الصلاة والسلام- لما جاء خبر موت ابن عمه جعفر بن أبي طالب من الشام، قال ﷺ لأهله: اصنعوا لآل جعفر طعامًا فقد أتاهم ما يشغلهم، فإذا صنع الجيران، أو الأقارب لأهل الميت طعامًا فهذا مشروع، وإذا دعا إليه أهل الميت جيرانهم، ومن نزل بهم من الضيوف، وأكلوا فلا بأس؛ لأنه قد يكون طعامًا كثيرًا، فيحتاج إلى من يأكله، فإذا دعوا جيرانهم، أو بعض أقاربهم للأكل معهم فلا بأس بذلك. وهكذا لو نزل بهم ضيف، لو نزل بأهل الميت ضيف، وصنعوا له طعامًا فلا حرج في ذلك؛ لأن هذا ليس من أجل الميت، بل من أجل الضيف، وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9106/حكم-مكث-اهل-الميت-في-البيت-للعزاء-مع-الذبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_362/36203.mp3","categories":["أحكام التعزية"]},{"id":10997,"question":"من دولة الكويت رسالة بعث بها مستمع من هناك هو (ح. ع. مصري) يقول: أعمل طباخًا لدى شركة أجنبية، وأقوم بطهي لحم الخنزير، رغم يقيني بحرمته علمًا بأني لا أذوقه، ولا أقدمه للعمال المسلمين، هل علي إثم من طبخه وتقديمه للأجانب؟","title":"حكم طبخ المسلم لحم الخنزير لغير المسلمين","answer":"الجواب:  نعم، نعم ليس لك ذلك، الله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2]، وطبخ الخنزير وتقديمه للضيوف، أو لمن استعملك في هذا الشيء منكر، ومعاونة على منكر؛ لأن الله حرم عليهم الخنزير كما حرم على المسلمين، فليس لك أن تعينهم على ما حرم الله، كما أنك ليس لك أن تعينهم على الشرك، وعبادة عيسى -عليه الصلاة والسلام- وليس لك أن تعينهم على شرب الخمر، ولا غير هذا من المعاصي، فهكذا طبخ الخنزير وتقديمه لهم، أو للضيوف كله منكر.  فالواجب عليك الحذر من ذلك، والاستقالة، والبعد عنهم، إذا كنت صادقًا في إسلامك، نسأل الله لنا ولك الهداية، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/9181/حكم-طبخ-المسلم-لحم-الخنزير-لغير-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36515.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":11157,"question":"يقول: عندنا عادة عند وفاة أحد الأشخاص نجلس بعض الأيام أيام الوفاة في أكل وشرب، وبعض الأحيان يعطون فلوسُا وهدايا فما حكم هذا؟","title":"حكم الجلوس للعزاء وإقامة المآتم لذلك","answer":"الجواب:  ليس لأهل الميت أن يصنعوا الطعام للناس عند المصيبة الموت، ليس لأهل الميت أن يصنعوا الطعام المأتم لا، هذا .. من عمل الجاهلية، لكن إذا صنع لهم أقاربهم وجيرانهم هذا أفضل، يصنعون لهم طعامًا، يبعث به إليهم؛ لأنهم شغلوا بالموت والمصيبة، وقد ثبت عنه ﷺ أنه لما جاء خبر جعفر بن أبي طالب أنه توفي في يوم مؤتة أمر أهله أن يصنعوا لآل جعفر طعامًا قال: اصنعوا لهم طعامًا فقد أتاهم ما يشغلهم، فالسنة للجيران أو الأقارب أن يبعثوا لأهل الميت طعامًا، أما كون أهل الميت يقومون بذلك، يصنعون الطعام ويجمعون الناس لا، هذا غير مشروع، بل هو من عمل الجاهلية، قال جرير بن عبدالله البجلي  الصحابي الجليل: كنا نعد الاجتماع إلى أهل الميت وصنعة الطعام بعد الدفن من النياحة. لكن إذا جاءهم طعام ودعوا إليه جيرانهم أو ضيوفهم وأكلوا لا بأس، الطعام الذي يأتيهم من جيرانهم ومن أقاربهم، إذا أكل معهم جيرانهم أو ضيوفهم، لا بأس بذلك، نعم.","link":"https://binbaz.org.sa/fatwas/9353/حكم-الجلوس-للعزاء-واقامة-الماتم-لذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_371/37117.mp3","categories":["أحكام التعزية"]},{"id":11169,"question":"يقول: عندنا عادة عند وفاة أحد الأشخاص نجلس بعض الأيام أيام الوفاة في أكل وشرب، وبعض الأحيان يعطون فلوسُا وهدايا فما حكم هذا؟","title":"حكم الجلوس للعزاء وإقامة المآتم لذلك","answer":"الجواب:  ليس لأهل الميت أن يصنعوا الطعام للناس عند المصيبة الموت، ليس لأهل الميت أن يصنعوا الطعام المأتم لا، هذا .. من عمل الجاهلية، لكن إذا صنع لهم أقاربهم وجيرانهم هذا أفضل، يصنعون لهم طعامًا، يبعث به إليهم؛ لأنهم شغلوا بالموت والمصيبة، وقد ثبت عنه ﷺ أنه لما جاء خبر جعفر بن أبي طالب أنه توفي في يوم مؤتة أمر أهله أن يصنعوا لآل جعفر طعامًا قال: اصنعوا لهم طعامًا فقد أتاهم ما يشغلهم، فالسنة للجيران أو الأقارب أن يبعثوا لأهل الميت طعامًا، أما كون أهل الميت يقومون بذلك، يصنعون الطعام ويجمعون الناس لا، هذا غير مشروع، بل هو من عمل الجاهلية، قال جرير بن عبدالله البجلي  الصحابي الجليل: كنا نعد الاجتماع إلى أهل الميت وصنعة الطعام بعد الدفن من النياحة. لكن إذا جاءهم طعام ودعوا إليه جيرانهم أو ضيوفهم وأكلوا لا بأس، الطعام الذي يأتيهم من جيرانهم ومن أقاربهم، إذا أكل معهم جيرانهم أو ضيوفهم، لا بأس بذلك، نعم.","link":"https://binbaz.org.sa/fatwas/9353/حكم-الجلوس-للعزاء-واقامة-الماتم-لذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_371/37117.mp3","categories":["أحكام التعزية"]},{"id":11327,"question":"يقول هذا الأخ السوداني مقيم بحائل: ما هي الأطعمة التي حرمها الله على المسلمين؟ أرجو منكم الإفادة.","title":"الأطعمة المحرمة","answer":"الجواب:  بينها سبحانه في قوله -جل وعلا- في سورة المائدة: حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ وَالْمُنْخَنِقَةُ وَالْمَوْقُوذَةُ وَالْمُتَرَدِّيَةُ وَالنَّطِيحَةُ وَمَا أَكَلَ السَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى النُّصُبِ [المائدة:3] هذه بينها ، هذه محرمة الميتة والخنزير والدم المسفوح، وما أهل به لغير الله ما ذبح للأصنام أو للبدوي أو للحسين أو للشيخ عبد القادر الجيلاني أو لفلان أو فلان هذا يكون ميتة محرم، كلما ذبح لغير الله. المنخنقة التي تخنق حتى تموت بخيط أو غيره، والموقوذة التي تضرب بعصا أو حجر حتى تموت، أو تردى من الجبل يقال لها: متردية تسقط من الجبل أو من محل رفيع تموت هذه متردية، والنطيحة: الذي تنطحها أختها، تنطحها أختها حتى تموت، تنطحها البقرة أو الشاة أو العنز حتى تموت، وهكذا ما أكل السبع، ما قتلها السبع ميتة، وهكذا كل شيء يعني: يعرف أنه ضار للإنسان يضره، مثل: طعام فيه سم يضرك لا تأكله؛ لأنه يكون حينئذٍ خبيثًا، يعني: يضرك لو كان فيه سم. وهكذا لحوم السباع المحرمة كل ذي ناب من السباع كالكلب الأسد النمر الذئب والهر كلها محرمة، وهكذا كل ذي مخلب من الطير كالعقاب كالباز والصقر وأشباهه مما له مخلب يصيد به. الرسول حرم ذلك -عليه الصلاة والسلام-  كل ضار يضر مثل الحشيشة التي تسكر، الخمر الدخان القات الشيء الذي يضر أو يسكر يزيل العقل فيجب تركه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9509/الاطعمة-المحرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_292/29206.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":11361,"question":"المستمع جاد الله آدم عبدالله مقيم في المملكة يسأل سماحتكم ثلاثة أسئلة:في سؤاله الأول يقول: هل الدخان حرام أم مكروه؟ جزاكم الله خيرًا.","title":"حكم تعاطي الدخان","answer":"الجواب:  الدخان ذكر المحققون من أهل العلم أنه حرام؛ لمضاره العظيمة في المال والبدن والعقل، فهو محرم لمضاره الكثيرة هذا هو الصواب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9531/حكم-تعاطي-الدخان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37808.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":12248,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها مجموعة من الأسئلة، يقول: نحن الحمد لله مسلمون ولدينا أخ مسيحي، هل يجوز الأكل والشرب معه، أو لا؟ أفيدونا جزاكم الله خيرًا.","title":"حكم مؤاكلة الكتابي ومعاشرته","answer":"الجواب:  المسيحي ليس أخًا لك إذا كنت مسلمًا إلا إذا كان أخًا لك من النسب، الكافر ليس أخًا لك، يقول الله -جل وعلا-: إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ [الحجرات:10] ويقول النبي ﷺ: المسلم أخو المسلم فالمسلم هو أخو المسلم، وليس أخًا للكافر، وإن كان من نسبه، ليس أخًا له في الدين، سواء كان يهوديًا، أو نصرانيًا، أو مجوسيًا، أو شيوعيًا، أو قاديانيًا، أو وثنيًا، كل هؤلاء كفرة، ليسوا إخوة لنا، بل بيننا وبينهم البغضاء والعداوة، وإن أحسنا إليهم إذا كانوا فقراء ليسوا محاربين، لا مانع أن نحسن إليهم، إذا كانوا أهل ذمة، أو مستأمنين، نحسن إليهم لفقرهم، وندعوهم إلى الإسلام، لا بأس، لكن ليسوا إخوة لنا، وليسوا أحبابًا لنا، بل نبغضهم في الله حتى يهتدوا، ومع هذا نحسن إليهم، وندعوهم إلى الله، ونسأل الله لهم الهداية، كل هذا مطلوب. أما إذا كانوا حربًا لنا، بيننا وبينهم القتال، ليس بيننا وبينهم ذمة ولا أمان؛ فهؤلاء نبغضهم في الله، ونقاتلهم، ولا نعطيهم شيئًا، ولا نساعدهم على المسلمين، بل نبغضهم في الله، ونحاربهم، ونقطع الصلة بيننا وبينهم، ولا نساعدهم بشيء أصلًا، بل إعانتهم على المسلمين كفر وردة، نسأل الله العافية. وهذا المسيحي لا تتخذه صاحبًا، ولا تؤاكله، ولا.. لكن إذا بليت به، ساكن معك، أو ضيف؛ لا مانع أن تأكل معه، لكن لا تتخذه صاحبًا، ولا بطانة، بل تتخذه عدوًَا، وبغيضًا في الله  حتى يهتدي، وأما مواكلته العارضة بسبب الضيافة، أو بسبب أنه نزل معك في محل السكن لعارض؛ فإنك تأكل معه إذا دعت الحاجة، ولكن تسعى في الخلاص من صحبته، ومساكنته؛ لئلا يجرك إلى بلائه، ولئلا تساهل فيما أوجب الله عليك من شأنه، والله المستعان، نعم. المقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/10441/حكم-مواكلة-الكتابي-ومعاشرته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_448/44812.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":12459,"question":"هل يجوز لنا تعزية أهل الميت إذا كان الميت توفي عن طريق الانتحار؟","title":"حكم تعزية أهل المنتحر","answer":"الجواب:  نعم يعزوا، ويدعى له بالمغفرة إذا مات وهو مسلم، إذا كان مسلمًا، انتحاره لا يخرجه من دائرة الإسلام، كبيرة من الكبائر، ويدعى له بالعفو والمغفرة، ويصلى عليه، لكن لا يصلي عليه يعني: السلطان، أو الأمير، أو العالم من باب التعزير له ولأمثاله، يصلي بعض الناس؛ لأنه مسلم ليس بكافر، المنتحر مسلم أتى كبيرة عظيمة، فيصلى عليه، ويدعى له بالعفو والمغفرة، ويتصدق عنه -نسأل الله العافية والسلامة- نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10660/حكم-تعزية-اهل-المنتحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40401.mp3","categories":["أحكام التعزية"]},{"id":12666,"question":"يقول: أهل قريتنا يأكلون لحم الثعلب، فهل لحمه حلال، أم حرام؟","title":"حكم أكل لحم الثعلب","answer":"الجواب:  هذه من المسائل التي تقدمت مما اختلف فيها العلماء، والثعلب دل النص على تحريمه، فلا يجوز لأحد أن يبيحه للناس، أو يبيعه على الناس، وهكذا القط السنور الذي يطوف، البِسْ المعروف محرم؛ لأنها كلها من ذوات النيبان. والنبي -عليه الصلاة والسلام- يقول: كل ذي ناب من السباع فأكله حرام فهي سبع، القط سبع، والثعلب سبع، والذئب سبع، والكلب سبع، كله حرام، ليس لأحد أن يأكله، ولا أن يبيعه، فلا يباع السنور، ولا الكلب، ولا الذئب، زجر النبي ﷺ عن ثمن السنور، وعن ثمن الكلب، والذئب من باب أولى، والأسد كذلك، كل هذه السباع لا تباع، ولا تحل، بل هي حرام، فالثعلب من ذلك، الثعلب من جملة السباع المحرمة، وهو يصيد الطيور، ويفترسها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10876/حكم-اكل-لحم-الثعلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45818.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":12766,"question":"المستمع عبدالجليل عباس حمد سوداني، يقول: في المآتم عندنا يستمر المأتم ما يقارب الشهر، وخلاله ينفق الكثير من المال، فهل يعتبر هذا صدقة للمتوفى، أم أنه تبذير؟ جزاكم الله خيرًا.","title":"حكم إقامة المآتم","answer":"الجواب:  إقامة المآتم لا تجوز، والواجب على أهل الميت الصبر، والاحتساب، وألا يقيموا أي مأتم، هذا هو الواجب عليهم، لكن إذا بعث إليهم جيرانهم وأقاربهم طعامًا؛ فلا بأس، ثبت عنه ﷺ: أنه أمر أهل بيته أن يبعثوا لأهل جعفر طعامًا لما قتل  وجاء خبره قال: فإنه قد أتاهم ما يشغلهم. فلا بأس إذا جاءهم طعام أن يدعوا إليه جيرانهم، ومن حولهم، ويأكلوا معهم؛ لأنه كثير؛ فلا بأس أن يدعوا من يأكل معهم. أما أنهم يصنعون هم للناس فلا يجوز هذا، هذا من المأتم المنهي عنه، يقول جرير  ابن عبدالله الصحابي الجليل: كنا نعد الاجتماع إلى أهل الميت، وصنعة الطعام بعد الدفن من النياحة والنياحة منهي عنها. فالواجب على المسلمين التقيد بالأمر الشرعي، وعدم إيجاد المآكل التي يفعلها أهل الجاهلية، وتعتبر من النياحة، ولكن يستحب لجيرانهم وأقاربهم أن يبعثوا إليهم طعامًا؛ فإنه قد أتاهم ما يشغلهم، وإذا كان الطعام كثيرًا، ودعوا إليه من يأكل معهم؛ فلا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10980/حكم-اقامة-الماتم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41915.mp3","categories":["أحكام التعزية"]},{"id":12954,"question":"ننتقل إلى رسالة بعث بها السائل عبدالله، مصري مقيم بالمملكة يقول: ما هو الدم المسفوح؟","title":"المقصود بالدم المسفوح","answer":"الجواب:  هو الذي يخرج من الذبيحة عند الذبح يسمى مسفوحًا إذا جر عليها السكين، هذا الدم الذي يصب من حلق الذبيحة هذا يقال له: مسفوحًا، أما الذي يبقى في اللحوم في لحمها هذا ما هو مسفوح، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11171/المقصود-بالدم-المسفوح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50212.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":13216,"question":"السائل يقول: اعتاد البعض من النسوة أثناء التعزية في الأموات، وخاصة قبل دفن الجثمان أن يرددن قول: (لا إله إلا الله) بصوت عالي، أي: امرأة تقول والباقي يرددن وراءها، وصوت هذه المرأة مسموع عند الرجال، ويرين بأن هذا أفضل من اللطم، أو العويل، ويهدي من حالة أهل الميت، فما صحة ذلك؟","title":"حكم ترديد بعض النسوة :(لا إله إلا الله) عند العزاء","answer":"الجواب:  الظاهر أن هذا بدعة مطلقًا حتى لو ما سمعها الرجال، كونهن يرددن لا إله إلا الله.... النسوة عند التعزية هذا لا أصل له، التعزية: أحسن الله عزاءكم.. جبر مصيبتكم.. غفر لميتكم، ونحو هذا الكلام، أما أن يرددن لا إله إلا الله، أو سبحان الله بصوت جماعي؛ هذا بدعة، سواء سمعها الرجال، وإلا ما سمعها الرجال، لا ينبغي هذا، بل السنة أن يقال لهم: اتقوا الله، لا تجزعوا، الحمد لله هذه سنة الله في عباده، كل بيموت، ويتحدثن معهن بالوصية والنصيحة، هذه التهدئة، التعزية بالوعد بالخير، والتحذير من الشر. أما يأتين بلا إله إلا الله بصوت جماعي، أو بأشباه ذلك؛ فهذا من البدع؛ لأن البدعة هي ما أحدثه الناس خلاف الشرع، كما قال ﷺ: من عمل عملًا ليس عليه أمرنا؛ فهو رد من أحدث في أمرنا هذا ما ليس منه؛ فهو رد وهذا ليس أمر النبي ﷺ وليس من عمل الصحابة، بل هذا من البدع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11488/حكم-ترديد-بعض-النسوة-لا-اله-الا-الله-عند-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51215.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":13217,"question":"سماحة الشيخ ما حكم السفر للتعزية؟","title":"حكم السفر للتعزية","answer":"الجواب:  لا بأس به، يسافر، يعزي أخاه، أو أباه لا بأس، الحمد لله، نعم. المقدم: بالنسبة للتلفون -يا سماحة الشيخ عبد العزيز- هل يكفي في التعزية؟ الشيخ: يكفي، يكفي، لكن إذا سافر إليهم، أو زارهم في البيت؛ كان أكمل، أكمل -يعني- في الجبر والتعزية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11492/حكم-السفر-للتعزية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51216.mp3","categories":["أحكام التعزية"]},{"id":13280,"question":"يسأل ويقول: هل للمسلم أن يأكل من النخيل المهمل الساقط ثمره على الأرض؟","title":"حكم الأكل من الساقط من ثمر النخيل","answer":"الجواب: نعم، له أن يأكل مما سقط على الأرض إذا كان مهملًا، أما إذا كان محفوظًا في بستان، مصونًا؛ فليس له أن يأخذ شيئًا إلا بإذن ربه، أما إذا كان متروكًا، لم يصن، فإذا مر به، وأكل منه؛ فلا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11565/حكم-الاكل-من-الساقط-من-ثمر-النخيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_476/47609.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":13497,"question":"على بركة الله نبدأ هذا اللقاء بسؤال من الجزائر، السائل الحقيقة له مجموعة من الأسئلة، غالب محمد يقول في هذا  ما حكم أولئك الذين يجمعون المقرئين في بيت الميت بعد دفنه، ويقرؤون ما يتيسر من القرآن، ثم يأكلون ويشربون، وقد يأخذون مبلغًا ماليًا على تلك القراءة؟ وجهونا سماحة الشيخ.","title":"حكم الاجتماع لقراءة القرآن في بيت العزاء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فهذا الاجتماع لا أصل له في الشرع، بل هو بدعة، إنما السنة أن يزار أهل الميت للتعزية، والدعاء لميتهم؛ جبرًا لمصابهم، وأما أن يجمعونهم ليقرؤوا، ويطعمونهم هذا بدعة، يقول جرير  جرير بن عبدالله البجلي : \"كنا نعد الاجتماع إلى الميت، وصنعة الطعام بعد الدفن من النياحة\" خرجه الإمام أحمد بإسناد حسن.  فالمقصود: أن كونهم يجمعونهم؛ ليقرؤوا ويأكلوا؛ هذا لا أصل له، بل هو من البدع، أما لو زارهم إنسان يسلم عليهم، ويدعو لهم، ويعزيهم، وقرأ في المجلس قراءة عارضة، ليس بمقصودة، ولا هم مجتمعون، فقرأ آية، أو آيات لفائدة الجميع، ونصيحة الجميع؛ فلا بأس، أما أن أهل الميت يجمعون الناس، أو يجمعون جماعة معينة؛ ليقرؤوا، ويطعموهم، أو يعطوهم فلوسًا؛ هذا بدعة لا أصل له. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11803/حكم-الاجتماع-لقراءة-القران-في-بيت-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53101.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":13588,"question":"ما حكم شرب التدخين؟ وإذا تقدم هذا الشخص هذا الذي يشرب الدخان، وصلى بالناس إمامًا في مسجد، هل يجوز له أن يكون إمامًا لأحد المساجد؟","title":"حكم التدخين وإمامة المدخن","answer":"الجواب: شرب الدخان لا يجوز، بل هو محرم لما فيه من المضار العظيمة على البدن والصحة والمال والدين، فهو منكر، ومضاره كثيرة على الدين والدنيا والصحة والمال، فالواجب على كل مسلم أن يحذره، وأن يبتعد عن شربه، وعن مجالسة أهله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11914/حكم-التدخين-وامامة-المدخن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53304.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":13876,"question":"يقول: لدينا عادة حيث يدفع المعزي مبلغًا من المال حسب قدرته لأهل الميت، هل يجوز هذا؟","title":"حكم إعطاء أهل الميت مالًا عند التعزية","answer":"الجواب: إذا كانوا فقراء واعتاد الناس إعطاءهم فلا بأس، إذا كانوا فقراء يعطونهم لفقرهم، ولكن الأفضل من هذا تصنعون لهم طعامًا، يصنع لهم طعام غداء أو عشاء أيام المصيبة ثلاثة أيام أو أكثر؛ لأن الرسول ﷺ أمر أهله أن يصنعوا لآل جعفر طعامًا لما جاء نعي جعفر بن أبي طالب ، أمر أهله أن يصنعوا طعامًا لأهله، قال: لأنه أتاهم ما يشغلهم فإذا صنعتم طعامًا لأهل الميت فلا بأس سنة، أما أنهم يصنعون الطعام هم لا. لا يصنعونه للناس، لكن يصنع لهم ويرسل لهم، وإذا كانوا فقراء وساعدهم إخوانهم بمال فلا بأس.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/12283/حكم-اعطاء-اهل-الميت-مالا-عند-التعزية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50614.mp3","categories":["أحكام التعزية"]},{"id":13884,"question":"السائل طلعت سوداني ومقيم بالرياض له مجموعة من الأسئلة، يقول: هذا السؤال أولًا: المآتم، هل يجوز الذهاب للعزاء لأهل الميت وتعزيتهم إذا كانت لديهم بدع مثل: قراءة الفاتحة مع رفع الكفين قبل إلقاء السلام عليهم؟ نرجو منكم الإفادة.","title":"حكم تعزية أهل الميت إذا كان عندهم بدع","answer":"الجواب: نعم. تعزيهم وتنصحهم، تعزيهم وتنصحهم عما عندهم من البدع والحمد لله، تجمع بين الخيرين بين التعزية وإنكار المنكر، نعم.","link":"https://binbaz.org.sa/fatwas/12281/حكم-تعزية-اهل-الميت-اذا-كان-عندهم-بدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50613.mp3","categories":["أحكام التعزية"]},{"id":13890,"question":"يقول: لدينا عادة حيث يدفع المعزي مبلغًا من المال حسب قدرته لأهل الميت، هل يجوز هذا؟","title":"حكم إعطاء أهل الميت مالًا عند التعزية","answer":"الجواب: إذا كانوا فقراء واعتاد الناس إعطاءهم فلا بأس، إذا كانوا فقراء يعطونهم لفقرهم، ولكن الأفضل من هذا تصنعون لهم طعامًا، يصنع لهم طعام غداء أو عشاء أيام المصيبة ثلاثة أيام أو أكثر؛ لأن الرسول ﷺ أمر أهله أن يصنعوا لآل جعفر طعامًا لما جاء نعي جعفر بن أبي طالب ، أمر أهله أن يصنعوا طعامًا لأهله، قال: لأنه أتاهم ما يشغلهم فإذا صنعتم طعامًا لأهل الميت فلا بأس سنة، أما أنهم يصنعون الطعام هم لا. لا يصنعونه للناس، لكن يصنع لهم ويرسل لهم، وإذا كانوا فقراء وساعدهم إخوانهم بمال فلا بأس.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/12283/حكم-اعطاء-اهل-الميت-مالا-عند-التعزية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50614.mp3","categories":["أحكام التعزية"]},{"id":13950,"question":"المستمع ناصر حسن عوض بعث برسالة وضمنها سبعة أسئلة، في سؤاله الأول يقول: ما حكم أكل كلى الأغنام بدمها من غير طبخ أو شيء؟","title":"حكم أكل بعض أجزاء الذبيحة دون طبخ","answer":"الجواب: الدم المحرم هو المسفوح الذي يصب من حلق الذبيحة عند ذبحها، أما الدماء التي تكون في الكلى وفي داخل اللحم لا يضر أكلها نيئة ولا مشتوية، لكن كونها مطبوخة ومشوية أفضل، ولو أكل منها شيئًا نيئًا ولا يترتب عليه مضرة فلا بأس، أما إن قال أهل الخبرة والطب: إنه يضره إذا أكل شيئًا منها نيئًا فإنه يجتنبه للمضرة، أما إذا كان أكله نيئًا لا يضر سواء كبد أو كلية أو غير ذلك فلا حرج في ذلك لأنه مباح، وإنما طبخها وشيها يشهيها ويحسن أكلها، فإذا كان منها شيء لو أكله نيئًا لم يضره فلا حرج في ذلك.\nالمقدم: جزاكم الله خيرًا، بقية اللحم مثلًا؟\nالشيخ: كل اللحم كل اللحم.\nالمقدم: كل اللحم.\nالشيخ: إيه لا بأس أن يأكل من إبل أو بقر أو غنم أو صيد؛ لكن كونه يعني قد طبخ أو حصل له الشوي يكون أكمل وأفضل وأسلم من التبعة، لكن لو قدر أن بعض الناس أكل شيئًا نيئًا وليس فيه مضرة عند أهل الخبرة فلا حرج.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12349/حكم-اكل-بعض-اجزاء-الذبيحة-دون-طبخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48215.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":14038,"question":"سؤاله الأخير يقول: هل يجوز أن ينصب للميت بعد دفنه؛ لأن هناك بعض العادات القديمة ينصبون، ويجلسون ثلاثة أيام، والبعض سبعة أيام..الشيخ: أعد.المقدم: هل يجوز أن ينصب للميت بعد دفنه؛ لأن هناك بعض العادات القديمة ينصبون، ويجلسون ثلاثة أيام، والبعض سبعة أيام، وعند ذلك يدفع نقودًا عند العزاء، ويسجلون الأسماء ويحضرون الذبائح، وبعد ذلك يحضر المشايخ والدراويش، ويهللوا ويزغردوا، ويسمونها بالتهليلة على الميت، ويقولون: إن الذي لا يأكل من العزاء لا يحب المرحوم، ما هو المفروض بعد دفن الجثة؟ أفيدونا جزاكم الله خيرا.","title":"حكم إقامة الولائم بعد دفن الميت والتهليل والزغاريد","answer":"الجواب: أما النصب فلم يوضحه السائل ما هو النصب؟ لم يوضحه، والسنة في حق الميت إذا فرغ من دفنه أن يدعى له بالمغفرة والثبات، كان النبي ﷺ إذا فرغ من دفن الميت وقف عليه، وقال:  استغفروا لأخيكم، وسلوا له التثبيت؛ فإنه الآن يسأل، ولا يجوز البناء على قبره، ولا اتخاذ مسجد على قبره، بل يجب أن يترك هكذا في الصحراء ضاحيًا للشمس، ليس عليه بناء، والرسول ﷺ لعن اليهود و النصارى على اتخاذهم المساجد على القبور.\nفالواجب أن تبقى القبور هكذا، ليس عليها بناء، ونهى أن تجصص، وأن يقعد عليها، وأن يبنى عليها، وأما العزاء اتخاذ ذبائح من أهل الميت يدعون لها الناس، ويجتمعون عليها ثلاثة أيام أو أكثر؛ هذي بدعة من أمر الجاهلية لا تجوز.\nأما المستحب فهو أن يبعث لهم طعام، يبعث لأهل الميت طعام من جيرانهم، ومن أقاربهم أيام الموت؛ لأنهم مشغولون بالمصيبة، فلا بأس بذلك.\nوالنبي ﷺ لما جاء نعي جعفر بن أبي طالب ، لما قتل في دومة في الشام، وجاء نعيه إلى المدينة؛ أمر أهل بيته أن يصنعوا طعامًا لأهل جعفر ، قال: اصنعوا لهم طعامًا فإنه قد أتاهم ما يشغلهم، فإذا صنع جيرانهم أو أقاربهم لهم طعامًا وبعثوه إليهم في بيوتهم؛ هذا مشروع لا بأس به، وإذا دعوا إليه من يأكل معهم من جيرانهم؛ لأنه طعام كثير، ودعوا إليه من يأكله معهم فلا بأس.  أما أن يقوم أهل الميت بصناعة الطعام وذبح الذبائح ودعوة الناس، هذا بدعة ومنكر، ومن أمر الجاهلية، وهكذا الزغردة والصياح والكلام الفارغ الذي يفعلونه بمناسبة الميت، لا أصل له، وقد قال جرير بن عبد الله البجلي : \"كنا نعد الاجتماع إلى أهل الميت وصناعة الطعام بعد الدفن من النياحة\" ، رأى أنه يعد من النياحة عند أصحاب النبي عليه الصلاة والسلام.\nفالمشروع لأهل الميت الصبر والاحتساب، وأن يستعملوا ما شرع الله من الصبر والاحتساب، وقول: إنا لله وإنا إليه راجعون، والسنة لأقاربهم وجيرانهم أن يبعثوا لهم طعامًا وقت المصيبة، اليوم الأول أو الثاني أو الثالث.. ليس له حد، ولا مانع أن يدعو بعض جيرانهم أو أقاربهم؛ ليأكلوا معهم مما بعث إليهم من الطعام، أما أن يصنعوا طعامًا هم ويذبحوا ذبائح، أو يحبسوا أنفسهم في البيت من أجل المصيبة لا، هذا ليس من أمر الإسلام، بل هو من أمر الجاهلية، فالمصاب له أن يخرج، وله أن يذهب إلى حاجاته وإلى مزرعته وإلى حاجاته الأخرى، وإذا جلس بعض الوقت المعتاد؛ ليسلم عليه من يزوره للعزاء، فلا بأس بذلك، وإن سلموا عليه في الطريق أو في المقبرة قبل الدفن أو بعد الدفن، كل ذلك لا بأس به يكفي، في الطريق، في المسجد، في المقبرة، قبل الدفن، بعد الدفن، في بيته؛ كل ذلك واسع، ولا يلزمه أن يبقى في البيت أو يشرع له أن يبقى في البيت يحبس نفسه لأجل ذلك، وفق الله الجميع. نعم.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12473/حكم-اقامة-الولاىم-بعد-دفن-الميت-والتهليل-والزغاريد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_607/60710.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":14163,"question":"يقول السائل: هل يجوز أكل لحم الوبر؟","title":"حكم أكل لحم الوبر","answer":"الجواب: نعم، الوبر حلال، الوبر من الحيوانات المباحة، الوبر والأرنب والغزال كلها من الطيبات. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12603/حكم-اكل-لحم-الوبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54624.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":14281,"question":"في سؤاله الثاني يقول: سماحة الشيخ! أسأل عن الاجتماع في بيت الميت لعدة أيام، علمًا بأنهم يأتون بطعام من بيوتهم ويأكلون في بيت الميت بحجة الحديث: اصنعوا لآل جعفر طعامًا وجهونا في ذلك.","title":"حكم الاجتماع في بيت الميت مع الإتيان بالطعام","answer":"الجواب: لا بأس إذا صنعوا لهم طعامًا وأكلوا معهم لا بأس؛ لأنهم فعلوا ما أمر به النبي ﷺ، قال لأهله: اصنعوا لآل جعفر طعامًا فقد أتاهم ما يشغلهم، لما قتل جعفر في الشام وجاء خبره في المدينة أمر أهله ﷺ أن يصنعوا لآل جعفر طعامًا، فيستحب لأقارب الميت الذين غير أهله أو جيرانه أن يصنعوا لهم طعامًا لأهله زوجته وأولاده، فإذا شاركهم بعض الجيران وأكل معهم فلا بأس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12742/حكم-الاجتماع-في-بيت-الميت-مع-الاتيان-بالطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54918.mp3","categories":["أحكام التعزية"]},{"id":14333,"question":"يقول: ما حكم الشرع في نظركم في شرب الدخان؟","title":"ما حكم الشرع في شرب الدخان؟","answer":"الجواب: الدخان منكر ومحرم؛ لأنه مضر فيه مضار كثيرة، فلهذا أوضح العلماء رحمة الله عليهم أنه محرم؛ لمضاره الكثيرة. نعم.","link":"https://binbaz.org.sa/fatwas/12811/ما-حكم-الشرع-في-شرب-الدخان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55016.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":14404,"question":"هذا السائل حسن إسماعيل من اليمن، استعرضنا سؤالاً له في حلقة سابقة، بقي له هذا السؤال يقول: سماحة الشيخ في اليوم الثالث من موت الميت تقام محاضرة في بيت الميت، ويحضرها جمع من الناس، هل هذا العمل جائز، أو هو من البدع؟","title":"حكم اعتياد إقامة محاضرة في بيت الميت في اليوم الثالث","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فاعتياد إقامة محاضرة في بيت الميت في اليوم الثالث، أو طعام، أو شبه ذلك، ليس من الشرع في شيء، بل هو بدعة، أما إذا كان عارض استمعوا يسلمون على أهل الميت ويعزونهم، فذكرهم بعض الناس لا بأس شيء عارض، أما اتخاذ هذا عادة وسنة جارية في اليوم الثالث أو الثاني أو الرابع أو الخامس إقامة حفل وموعظة وخطبة أو أكل هذا بدعة، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12886/حكم-اعتياد-اقامة-محاضرة-في-بيت-الميت-في-اليوم-الثالث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55301.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":14424,"question":"المستمع أحمد حامد، أبو هديب، بعث برسالة يقول: أفتونا فيما هو واقع عندنا في التعزية، والطريقة التي هي عندنا هي: أنّ أهل الميت يتوافد عليهم الناس في الحال، فمن هؤلاء الناس من يأتي معه بالذبائح الجاهزة للأكل، ويقوم أهل الميت بدورهم لتقديمها للمعزين الذين جاؤوا لتقديم العزاء كغداء أو عشاء، والبعض الآخر من الناس يأتي معه بالغنم حية، ويقوم أهل الميت بعمل اللازم لتقديمها أيضًا كغداء أو عشاء، والبعض وهم القلة يجعلون ما أتوا به من أموال غنم أو نقود لأهل الميت، ولا يأكلون، ولا يجلسون إلا الوقت القليل، ومن ثم يذهبون، هل هذا العمل صحيح، أم من الواجب أن يجلسوا في البيت ليتلقوا التعازي أهل الميت؟وجهونا، جزاكم الله خيرًا.","title":"حكم تقديم أهل الميت الطعام للمعزين","answer":"الجواب: لا حرج في هذا، إذا تصدقوا عليهم، وجاؤوا لهم بشيء من الغنم، أو شيء من اللحم، لا حرج في ذلك، وإذا صنعه أهل الميت لهم؛ لأنهم ضيوف وأكرموهم بما جاؤوا به من اللحم، أو من الذبائح لا حرج عليهم في ذلك، وإن أعطوهم مالاً أو غنمًا أو غير ذلك فذهبوا ولم يجلسوا مساعدة لأهل الميت فلا بأس بذلك، وقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه لما جاء نعي جعفر بن أبي طالب  وهو ابن عمه لما قتل في مؤتة في الشام، قال النبي ﷺ لأهله: ابعثوا لأهل جعفر طعامًا، فقد أتاهم ما يشغلهم فأمر أهله أن يبعثوا إليهم طعامًا مصنوعًا؛ لأنه أتاهم ما يشغلهم، فالأفضل لهؤلاء أن يبعثوا طعامًا مصنوعًا دون الذبائح، يكلفون بها أهل الميت، لكن ما داموا جاؤوا بها، وأعطوها أهل الميت فأهل الميت عليهم أن يضيفوا ضيوفهم، ويحسنوا إليهم، ويكونوا كرماء لا لؤماء، فإذا صنعوا منها طعامًا لهم، وأطعموهم غداءً أو عشاءً فلا حرج في ذلك. إنما المكروه الذي لا ينبغي، والمنكر الذي يكون من عمل الجاهلية كون أهل الميت يصنعون الطعام من مالهم للناس، يجعلون هذا مأتمًا للميت، يصنعون الطعام للناس هذا هو الذي لا ينبغي، وهو من عمل الجاهلية، قال جرير : كنا نعد الاجتماع إلى أهل الميت، وصنعة الطعام بعد الموت من النياحة يعني: إذا فعله أهل الميت من مالهم. أما إذا فعلوه للضيوف الذين نزلوا بهم، أو فعلوه من الذبائح التي جاء بها الضيوف، فهذا ليس فيه بأس؛ لأنهم ملزوم بهذا، إكرام الضيف أمر لازم، ولا حرج في إكرام الضيف، بل واجب، النبي ﷺ قال: من كان يؤمن بالله واليوم الآخر فليكرم ضيفه فإذا جاءهم الضيوف سواء معهم طعام، أو ما معهم طعام، إذا جاءهم الضيوف ونزلوا عندهم، وجلسوا إلى وقت الغداء أو العشاء وضيفوهم فلا بأس، وإذا كانوا معهم غنم، كان معهم غنم أو لحوم كان الأمر أشد وآكد، لكن لا يبدؤون هم، أهل الميت لا يصنعون الطعام، ويجعلوه مأتمًا للناس وعادة، هذا هو الذي ينكر عليهم، وينهون عنه. والأفضل للذين يزورونهم أن يصنعوا الطعام في بيوتهم، ويبعثوه إليهم مصنوعًا كاملًا حتى لا يكلفوهم صنعة الطعام؛ لأنهم مشغولون بالمصيبة، فالذي فعله الرسول ﷺ وسنه للأمة أن جيرانهم أو أقاربهم يبعثون بالطعام مصنوعًا إليهم حتى يكفوهم المئونة هذا هو الأفضل، وإذا جاءهم الطعام، وقدموه للضيوف ليأكلوا منه، أو دعوا إليه الجيران، أو أقاربهم ليأكلوا فلا حرج في ذلك؛ لأن الطعام لو ترك ضاع بغير فائدة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12926/حكم-تقديم-اهل-الميت-الطعام-للمعزين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62405.mp3","categories":["أحكام التعزية"]},{"id":14426,"question":"يسأل أخونا ويقول: أهل الميت في ليلة الرابع من أيام العزاء يقومون بذبح الأغنام، ويقولون: هي صدقة عن الميت، ولا ندري هل هي من ماله الذي تركه لورثته أم من مال بعض الأقرباء أم أنها مقدمة من بعض من جاء يقدم العزاء من المتأخرين في تقديمه؟ نرجو التفصيل في حكم هذا، جزاكم الله خيرًا.","title":"حكم تخصيص ليلة الرابع بعد الوفاة بالذبح والصدقة","answer":"الجواب: اعتياد هذا لا يجوز، كونه يعتادون اليوم الرابع أو السابع أو الأربعين يذبحون ذبائح، ويتصدقون عن الميت هذا من البدع، لا يجوز هذا، لكن لو جاءهم ضيوف في اليوم الثالث، أو جاءهم ضيوف في اليوم الرابع، أو في الخامس، وذبحوا لهم، أو معهم ذبائح فذبحوا منها لهم لا بأس بذلك لإكرام الضيوف.  أما أن يتخذوه عادة في اليوم الرابع أو الثالث أو الخامس أو العاشر أو السابع، أو غير هذا عادة لا يجوز، بل يجب ترك البدع، والحذر منها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12927/حكم-تخصيص-ليلة-الرابع-بعد-الوفاة-بالذبح-والصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62406.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":14438,"question":"المستمع أحمد حامد، أبو هديب، بعث برسالة يقول: أفتونا فيما هو واقع عندنا في التعزية، والطريقة التي هي عندنا هي: أنّ أهل الميت يتوافد عليهم الناس في الحال، فمن هؤلاء الناس من يأتي معه بالذبائح الجاهزة للأكل، ويقوم أهل الميت بدورهم لتقديمها للمعزين الذين جاؤوا لتقديم العزاء كغداء أو عشاء، والبعض الآخر من الناس يأتي معه بالغنم حية، ويقوم أهل الميت بعمل اللازم لتقديمها أيضًا كغداء أو عشاء، والبعض وهم القلة يجعلون ما أتوا به من أموال غنم أو نقود لأهل الميت، ولا يأكلون، ولا يجلسون إلا الوقت القليل، ومن ثم يذهبون، هل هذا العمل صحيح، أم من الواجب أن يجلسوا في البيت ليتلقوا التعازي أهل الميت؟وجهونا، جزاكم الله خيرًا.","title":"حكم تقديم أهل الميت الطعام للمعزين","answer":"الجواب: لا حرج في هذا، إذا تصدقوا عليهم، وجاؤوا لهم بشيء من الغنم، أو شيء من اللحم، لا حرج في ذلك، وإذا صنعه أهل الميت لهم؛ لأنهم ضيوف وأكرموهم بما جاؤوا به من اللحم، أو من الذبائح لا حرج عليهم في ذلك، وإن أعطوهم مالاً أو غنمًا أو غير ذلك فذهبوا ولم يجلسوا مساعدة لأهل الميت فلا بأس بذلك، وقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه لما جاء نعي جعفر بن أبي طالب  وهو ابن عمه لما قتل في مؤتة في الشام، قال النبي ﷺ لأهله: ابعثوا لأهل جعفر طعامًا، فقد أتاهم ما يشغلهم فأمر أهله أن يبعثوا إليهم طعامًا مصنوعًا؛ لأنه أتاهم ما يشغلهم، فالأفضل لهؤلاء أن يبعثوا طعامًا مصنوعًا دون الذبائح، يكلفون بها أهل الميت، لكن ما داموا جاؤوا بها، وأعطوها أهل الميت فأهل الميت عليهم أن يضيفوا ضيوفهم، ويحسنوا إليهم، ويكونوا كرماء لا لؤماء، فإذا صنعوا منها طعامًا لهم، وأطعموهم غداءً أو عشاءً فلا حرج في ذلك. إنما المكروه الذي لا ينبغي، والمنكر الذي يكون من عمل الجاهلية كون أهل الميت يصنعون الطعام من مالهم للناس، يجعلون هذا مأتمًا للميت، يصنعون الطعام للناس هذا هو الذي لا ينبغي، وهو من عمل الجاهلية، قال جرير : كنا نعد الاجتماع إلى أهل الميت، وصنعة الطعام بعد الموت من النياحة يعني: إذا فعله أهل الميت من مالهم. أما إذا فعلوه للضيوف الذين نزلوا بهم، أو فعلوه من الذبائح التي جاء بها الضيوف، فهذا ليس فيه بأس؛ لأنهم ملزوم بهذا، إكرام الضيف أمر لازم، ولا حرج في إكرام الضيف، بل واجب، النبي ﷺ قال: من كان يؤمن بالله واليوم الآخر فليكرم ضيفه فإذا جاءهم الضيوف سواء معهم طعام، أو ما معهم طعام، إذا جاءهم الضيوف ونزلوا عندهم، وجلسوا إلى وقت الغداء أو العشاء وضيفوهم فلا بأس، وإذا كانوا معهم غنم، كان معهم غنم أو لحوم كان الأمر أشد وآكد، لكن لا يبدؤون هم، أهل الميت لا يصنعون الطعام، ويجعلوه مأتمًا للناس وعادة، هذا هو الذي ينكر عليهم، وينهون عنه. والأفضل للذين يزورونهم أن يصنعوا الطعام في بيوتهم، ويبعثوه إليهم مصنوعًا كاملًا حتى لا يكلفوهم صنعة الطعام؛ لأنهم مشغولون بالمصيبة، فالذي فعله الرسول ﷺ وسنه للأمة أن جيرانهم أو أقاربهم يبعثون بالطعام مصنوعًا إليهم حتى يكفوهم المئونة هذا هو الأفضل، وإذا جاءهم الطعام، وقدموه للضيوف ليأكلوا منه، أو دعوا إليه الجيران، أو أقاربهم ليأكلوا فلا حرج في ذلك؛ لأن الطعام لو ترك ضاع بغير فائدة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12926/حكم-تقديم-اهل-الميت-الطعام-للمعزين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62405.mp3","categories":["أحكام التعزية"]},{"id":14440,"question":"يسأل أخونا ويقول: أهل الميت في ليلة الرابع من أيام العزاء يقومون بذبح الأغنام، ويقولون: هي صدقة عن الميت، ولا ندري هل هي من ماله الذي تركه لورثته أم من مال بعض الأقرباء أم أنها مقدمة من بعض من جاء يقدم العزاء من المتأخرين في تقديمه؟ نرجو التفصيل في حكم هذا، جزاكم الله خيرًا.","title":"حكم تخصيص ليلة الرابع بعد الوفاة بالذبح والصدقة","answer":"الجواب: اعتياد هذا لا يجوز، كونه يعتادون اليوم الرابع أو السابع أو الأربعين يذبحون ذبائح، ويتصدقون عن الميت هذا من البدع، لا يجوز هذا، لكن لو جاءهم ضيوف في اليوم الثالث، أو جاءهم ضيوف في اليوم الرابع، أو في الخامس، وذبحوا لهم، أو معهم ذبائح فذبحوا منها لهم لا بأس بذلك لإكرام الضيوف.  أما أن يتخذوه عادة في اليوم الرابع أو الثالث أو الخامس أو العاشر أو السابع، أو غير هذا عادة لا يجوز، بل يجب ترك البدع، والحذر منها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12927/حكم-تخصيص-ليلة-الرابع-بعد-الوفاة-بالذبح-والصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62406.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":14531,"question":"من الجمهورية العربية السورية، محافظة دير الزور، هذه رسالة بعث بها مستمع من هناك يقول:أخوكم المتوكل على الله محمد العلي الحاج، يسأل ويقول: هل يحق مساعدة أهل الميت في حالة التعزية في الطعام، ونحن نسميها تعاون مثل الجيران أو الأعمام أو الأقرباء؟","title":"حكم مساعدة أهل الميت بإعداد الطعام","answer":"الجواب: السنة أن يبعث لهم طعامًا مصنوعًا، كما فعل النبي ﷺ «لما جاءه خبر جعفر  ابن أبي طالب، حين قتل في مؤتة في الشام؛ لما جاء خبره أمر أهله -عليه الصلاة والسلام- أن يبعثوا لأهل جعفر طعامًا، وقال: إنه أتاهم ما يشغلهم فإذا دفع الجيران أو الأقارب إلى أهل الميت طعامًا مصنوعًا أيام العزاء؛ لأنهم مشغولون عن صنع الطعام بالمصيبة فهذا سنة. أما المساعدة بالنقود، أو بغير ذلك، فهذا لا بأس به إذا كانوا فقراء، إذا كان أهل الميت فقراء، وساعدهم إخوانهم بالنقود أو غيرها من أجل موت القائم عليهم، والكاسب لهم، فهذا حسن، ومساعدة لهم لأجل فقرهم، وأما أن يقوموا هم بصنع طعام للناس من أجل الميت، فهذا من عمل الجاهلية، لا يجوز، لا يقوم أهل الميت بصنع الطعام للناس إلا إذا نزل بهم ضيف ليكرموه فلا بأس؛ لأنهم صنعوه من أجل الضيف، لا من أجل الميت، فلا بأس بهذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13032/حكم-مساعدة-اهل-الميت-باعداد-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63414.mp3","categories":["أحكام التعزية"]},{"id":14613,"question":"أخونا يقول: هناك عادة في بلدنا، فحين يتوفى شخص، يكثر الإسراف، ثم هناك الأربعين يوماً، وأكول فهل على...الشيخ: أعد أعد.المقدم: يقول: هناك عادة في بلدنا، فحين يتوفى شخص يكثر الإسراف، ثم هناك الأربعين يومًا وأكول، فهل على المؤمن أن ينصحهم ببطلان ما يفعلون أم لا يأتي لتعزيتهم؟","title":"حكم الإسراف في الطعام عند الموت","answer":"الجواب: نعم، ينصحهم، يعزيهم وينصحهم؛ لأن قيام أهل الميت بالإسراف، وإطعام الناس من أجل الميت في يوم الموت، أو في العاشر، أو في الأربعين، أو على رأس السنة، أو غير ذلك، لا أصل له، بل هو من أعمال الجاهلية.  وإنما يصنعون طعامًا لحاجتهم، والسنة لأصحابهم وأقاربهم أن يبعثوا لهم طعامًا، كما قال النبي ﷺ لأهله لما مات جعفر؛ لما جاء نعي جعفر بن أبي طالب  يوم قتل في مؤتة في الشام، وجاء خبره أمر النبي ﷺ أهله أن يصنعوا لآل جعفر طعامًا، أمر أهله أن يصنعوا لأهل جعفر بن أبي طالب طعامًا، وقال: إنه قد أتاهم ما يشغلهم. فالسنة لأولياء لأقرباء الميت أو جيرانه أن يصنعوا لهم طعامًا لنسائهم لأهل الميت؛ لأنهم مشغولون بالمصيبة.  أما أن أهل الميت يقومون يصنعون الطعام للناس، ويدعونهم في اليوم الأول، أو في اليوم الثالث، أو في السابع، أو العاشر، أو الأربعين، أو على رأس السنة كل هذا لا أصل له، لكن إذا صنعوا لأنفسهم طعامًا، وجاءهم الغير وشاركهم، أو صنعوا للضيف طعامًا بغير قصد إقامته للميت، لكن لما نزل بهم الضيف فإن الضيف يجب إكرامه إذا صنعوا له طعامًا، لا بأس لا من أجل الميت، بل من أجل الضيافة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13125/حكم-الاسراف-في-الطعام-عند-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63609.mp3","categories":["أحكام التعزية"]},{"id":14615,"question":"أخونا يقول: هناك عادة في بلدنا، فحين يتوفى شخص، يكثر الإسراف، ثم هناك الأربعين يوماً، وأكول فهل على...الشيخ: أعد أعد.المقدم: يقول: هناك عادة في بلدنا، فحين يتوفى شخص يكثر الإسراف، ثم هناك الأربعين يومًا وأكول، فهل على المؤمن أن ينصحهم ببطلان ما يفعلون أم لا يأتي لتعزيتهم؟","title":"حكم الإسراف في الطعام عند الموت","answer":"الجواب: نعم، ينصحهم، يعزيهم وينصحهم؛ لأن قيام أهل الميت بالإسراف، وإطعام الناس من أجل الميت في يوم الموت، أو في العاشر، أو في الأربعين، أو على رأس السنة، أو غير ذلك، لا أصل له، بل هو من أعمال الجاهلية.  وإنما يصنعون طعامًا لحاجتهم، والسنة لأصحابهم وأقاربهم أن يبعثوا لهم طعامًا، كما قال النبي ﷺ لأهله لما مات جعفر؛ لما جاء نعي جعفر بن أبي طالب  يوم قتل في مؤتة في الشام، وجاء خبره أمر النبي ﷺ أهله أن يصنعوا لآل جعفر طعامًا، أمر أهله أن يصنعوا لأهل جعفر بن أبي طالب طعامًا، وقال: إنه قد أتاهم ما يشغلهم. فالسنة لأولياء لأقرباء الميت أو جيرانه أن يصنعوا لهم طعامًا لنسائهم لأهل الميت؛ لأنهم مشغولون بالمصيبة.  أما أن أهل الميت يقومون يصنعون الطعام للناس، ويدعونهم في اليوم الأول، أو في اليوم الثالث، أو في السابع، أو العاشر، أو الأربعين، أو على رأس السنة كل هذا لا أصل له، لكن إذا صنعوا لأنفسهم طعامًا، وجاءهم الغير وشاركهم، أو صنعوا للضيف طعامًا بغير قصد إقامته للميت، لكن لما نزل بهم الضيف فإن الضيف يجب إكرامه إذا صنعوا له طعامًا، لا بأس لا من أجل الميت، بل من أجل الضيافة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13125/حكم-الاسراف-في-الطعام-عند-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63609.mp3","categories":["أحكام التعزية"]},{"id":14844,"question":"المستمع عبدالرحمن بن عياد موسى، بعث يسأل ويقول: يختلف الناس عندنا في أكل الهدهد، فمنهم من يقول: لا يجوز أكله؛ لأن سيدنا سليمان  لم يذبحه، ومنهم من يقول: بجواز أكله؛ لأنه من الطيور غير ذات المخلب، أي: أنه ليس من الطيور الجارحة. نرجو بيان وجه الصواب. جزاكم الله خيرًا.","title":"ما حكم أكل الهدهد؟","answer":"الجواب: الهدهد لا يجوز أكله؛ لأن الرسول نهى عن قتله -عليه الصلاة والسلام-، فهو بصفة خاصة منهي عن قتله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13357/ما-حكم-اكل-الهدهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64413.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":15038,"question":"السائل (ع. م. أ) سوداني، ومقيم بالرياض، يقول في سؤال له: عندنا عادة، وهي: عند وفاة شخص يحضر الناس للمأتم، وعند حضور أي شخص يرفع يديه، ويقول: الفاتحة للمرحوم فلان، ويرفع بقية الجالسين أيديهم أيضًا ويقرؤون.الشيخ: أعد! أعد.المقدم: يقول هذا السائل: عندنا عادة، وهي: عند وفاة شخص يحضر الناس للمأتم، وعند حضور أي شخص يرفع يديه ويقول: الفاتحة للمرحوم فلان، ويرفع بقية الجالسين أيديهم أيضًا ويقرؤون عند رفعها سورة الفاتحة والإخلاص، فما حكم الشرع في نظركم سماحة الشيخ؟","title":"حكم قراءة الفاتحة للميت وحكم المآتم","answer":"الجواب: هذه القراءة، وهذا الرفع بدعة، لا أصل لها، ولا يجوز فعل ذلك؛ لعدم الدليل، الرسول  يقول: من عمل عملًا ليس عليه أمرنا فهو رد ويقول ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد ويقول: كل محدثة بدعة، وكل بدعة ضلالة ولم يكن يفعل هذا هو، ولا أصحابه -رضي الله عنهم-.\nأما المأتم ففيه تفصيل: إن كان مجيئهم للتعزية فقط فلا بأس، أما كونه للطعام يصنعون لهم طعام، ويجتمعون عنده لا؛ هذا لا يجوز، يقول جرير بن عبدالله البجلي: «كنا نعد الاجتماع إلى أهل الميت، وصنعة الطعام بعد الدفن من النياحة» أما إذا زاروهم للتعزية فقط، سلموا عليهم وعزوهم، ولو شربوا قهوة أو شاهي ما يخالف، أما يحط مأتم أهل الميت يصنعون طعام للناس، هذا لا يجوز، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13534/حكم-قراءة-الفاتحة-للميت-وحكم-الماتم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56308.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":15161,"question":"السؤال الأخير يقول: سمعت أن الجيلي الذي يشبه التقلي، أقول: سمعت أنه يحوي بعض المكونات من الخنزير، فهل هذا صحيح؟","title":"حكم استخدام الجيلي","answer":"الجواب: لا نعلم شيئًا في هذا، ولم يبلغنا فيه ما يوجب تحريمه، نعم.","link":"https://binbaz.org.sa/fatwas/13666/حكم-استخدام-الجيلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_665/nour_66510.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":15257,"question":"هذا سؤال من السائل (أ. ع) من الرياض يقول: هناك بعض المواطنين وللأسف الشديد اعتادوا على أن يرموا فضلات الطعام في نفس الأماكن المخصصة للقمائم، فهي تختلط بما سواها من القمائم التي غالبًا ما تحتوي على شيء من النجاسات أو القاذورات، فما هي نصيحتكم لهؤلاء؟ وما حكم هذا العمل؟","title":"حكم رمي فضلات الطعام في القمائم","answer":"الجواب: نصيحتنا أن تكون الفضلات من الطعام من لحوم وخبز وغير ذلك تكون في كراتين خاصة، وعلى البلديات في كل مكان أن تجعلها في مكان خاص، تأخذها وتجعلها في مكان خاص للدواب، ومن احتاج إليها، أو في البرية تجعلها في محل خاص في البرية، يأتيها دواب تأكلها، يأتيها من يأخذها لدوابه، ولا تجعل مع القمامات النجسة، فأهلها أنفسهم أولًا يجعلونها في كراتين خاصة على حدة، لا مع القمائم الأخرى من النجاسات، وعلى البلديات في كل مكان أن تلاحظ هذا الأمر، وأن تعتني به، وتجعله في أمكنة خاصة في البرية، أو في أي مكان تراه حتى يأخذه من أراده من الناس، أو حتى تأتي الدواب فتأكله، نعم.\nالمقدم: إنما ليس عليهم إثم في عملهم هذا؟\nالشيخ: لا يجوز لهم، ما يجوز خلطها مع النجاسات، نعم، ليس لهم ذلك، بل يأثمون بذلك. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13762/حكم-رمي-فضلات-الطعام-في-القماىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_674/nour_67405.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":15315,"question":"هذه رسالة من المستمع عبدالله حماد حسين العميري، يقول: ما حكم الذبح على الميت حين وفاته بقصد عمل وليمة للصدقة على هذا الميت، كما هي العادة عندنا في البادية في صحراء مصر العربية؟","title":"حكم الوليمة عند الموت بقصد الصدقة","answer":"الجواب: لا يشرع للمسلم صنع وليمة لميته لا بالذبح ولا بغيره، إذا مات الميت شرع لأقارب الميت أن يصنعوا لأهل الميت طعامًا وجيرانهم، ونحو ذلك.  أما أهل الميت فلا يصنعون طعامًا، ولا يذبحون ذبيحة من أجل الميت، ولا يجمعون الناس عليها، قال النبي ﷺ لما أتى نعي جعفر بن أبي طالب  حين قتل في الشام في الأردن أمر أهل بيته أن يصنعوا لهم طعامًا لأهل جعفر قال: اصنعوا لأهل جعفر طعامًا، فقد أتاهم ما يشغلهم. فالسنة أن يصنع لأهل الميت طعام من جيرانهم وأقاربهم الأباعد للأقارب الأدنين، وأما كون أهل الميت يصنعون الطعام ويجمعون الجيران هذا لا يصلح، بل هو من البدع، ومن المآتم المنكرة، قال جرير بن عبدالله البجلي : \"كنا نعد الاجتماع إلى أهل الميت، وصنعة الطعام بعد الموت من النياحة\" فأخبر جرير  أنهم كانوا يعدون اجتماع الناس لأهل الميت، وصنعة الطعام من أهل الميت للناس كانوا يعدون هذا من النياحة، يعني: يعده الصحابة  وأرضاهم، فدل ذلك على أن أهل الميت لا يصنعون طعامًا للناس ولا يجمعونهم، ولكن يستحب لجيرانهم وأقاربهم الأباعد أن يبعثوا لهم طعامًا لكونهم مشغولين بمصيبة. وأما من ذبح ذبيحة لأجل الصدقة بها عن الميت على الفقراء والمساكين فلا حرج في ذلك، لكن لا تكون في وقت مخصوص، ولا يجمع لها أحد، بل تذبح ويوزع لحمها على الفقراء والمساكين صدقة في أي وقت كان ليس لها وقت مخصوص، وليس لها خصوصية بيوم الموت، بل متى فعلها في أي وقت لقصد مواساة الفقراء أو أعطاهم نقودًا، أو ملابس، أو طعامًا غير اللحم كل هذا نافع للميت، ويؤجر عليه فاعله، وقد ثبت عن النبي ﷺ أنه سئل عن هذا قال له رجل: يا رسول الله، إن أمي افتلتت نفسها ولم توص، وأظنها لو تكلمت تصدقت، أفلها أجر إن تصدقت عنها؟ قال النبي: نعم اللهم صل عليه وسلم. فالصدقة عن الميت نافعة بإجماع المسلمين، لكن ينبغي أن تكون في غير وقت الموت حتى لا يتخذ ذلك سنة وعادة، بل يوزعها في أوقات أخرى بين الفقراء من غير تخصيص وقت معين، لا يوم الموت، ولا يوم سابع الموت، ولا يوم أربعين الموت، ما يكون لها خصوصية. أما ما يفعله بعض الناس من إيجاد مآتم في اليوم الأول، أو في السابع، أو في الأربعين مآتم يجمعوا فيها الناس ويذبحوا فيها الغنم، أو غيرها هذا شيء لا أصل له، بل هو من البدع، فلا يجوز. المقدم: نعم، أثابكم الله.","link":"https://binbaz.org.sa/fatwas/13817/حكم-الوليمة-عند-الموت-بقصد-الصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_676/nour_67604.mp3","categories":["أحكام التعزية"]},{"id":15666,"question":"يسألان سماحتكم عن أكل الكبد أو بعض أجزاء اللحم دون طبخ، هل هو جائز أو لا؟","title":"حكم أكل الكبد واللحم نيئًا","answer":"الجواب: لا أعلم فيها بأسًا، لكن الطبخ أحسن، الطبخ أحسن وأنفع وأسلم من المرض، وإلا فلا أعلم شيئًا، إذا أكل شيئًا مما أباح الله من الكبد أو غيرها نيئًا لا أعلم فيه حرجًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14210/حكم-اكل-الكبد-واللحم-نيىا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70515.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":15676,"question":"يقول: أيضًا من العادات الموجودة عندنا إذا مات إنسان بالغ، سواء كان رجلًا أو امرأة، يذبح عليه، ويحتفلون ثلاثة أيام، وكذلك يقرؤون القرآن الكريم، ويقولون: يلحق هذا صدقة، ويعتبر صدقة للميت، ويقولون: لا نعمل غير مذهبنا، سواء كان صدقًا، أو غير صدق، فما هو توجيهكم للناس؟جزاكم الله خيرًا.","title":"حكم الولائم التي تقام بعد الميت","answer":"الجواب: هذا لا يجوز، بل هو من البدع، ومن عمل الجاهلية، ما يصلح، كونه يذبح بعد الموت، ويدعو الناس يومين أو ثلاثة أو عشرة، كل هذا لا أصل له، إنما المشروع الدعاء له، والترحم عليه، والاستغفار له، وإذا صنع جيرانه أو أقاربه طعامًا، وأرسلوه إلى أهل الميت لا بأس؛ لأن النبي ﷺ لما جاء نعي جعفر بن أبي طالب  لما قتل في مؤتة في الشام، وجاء خبره أمر النبي ﷺ أهل بيته أن يصنعوا طعامًا لآل جعفر، وقال: إنه قد أتاهم ما يشغلهم فإذا صنع الجيران طعامًا لهم أو الأقارب لا بأس، أما هم يصنعون طعامًا، ويقيمون وليمة، يدعون الناس، ويحزنون ثلاثة أيام، أو سبعة، هذا لا أصل له، هذا من البدع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14220/حكم-الولاىم-التي-تقام-بعد-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70607.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":15855,"question":"هذا السائل من اليمن رمز لاسمه (ع. ع. أ) يقول -سماحة الشيخ-: في بلدنا إذا مات الشخص يقام له في بيته ثلاث أو سبع ليالي تسمى بالتهاليل؛ لأنه يهلل فيها ثلاث دفعات في كل دفعة مائة تهليلة؛ وذلك في كل ليلة من تلك الليالي، وقبل التهليل في الدفعة الأولى فقط تقرأ سورة يس جماعيًا من قبل الحاضرين، وفي نهاية وتمام المائة يقال دعاء طويل، يختم به الفاتحة إلى روح الميت والأولياء والنبي ﷺ، أفيدونا سماحة الشيخ عن هذا العمل؟","title":"حكم الاجتماع في بيت الميت للتهليل وقراءة القرآن","answer":"الجواب: هذا -يا أخي- بدعة، ما يجوز هذا، هذا منكر وبدعة، لا أصل له من الشرع، بل يجب تركه، إذا مات ميت يعزون يدعى لهم بالصبر والاحتساب، ولميتهم بالمغفرة إذا كان مسلمًا، أما هذه الأعمال فهي منكرة، كلها بدعة، لا أصل لها في الشرع، ولم يفعلها الرسول ﷺ ولا أصحابه ، فهي بدعة منكرة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14446/حكم-الاجتماع-في-بيت-الميت-للتهليل-وقراءة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57617.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":15888,"question":"رسالة بعث بها المستمع مصطفى صوام، من ليبيا، يسأل ويقول: ما حكم الدين في الشخص الذي يتناول السجائر؟وجهونا حول هذه القضية إذ عمت به البلوى. جزاكم الله خيرًا.","title":"حكم التدخين","answer":"الجواب: التدخين بأنواعه لا يجوز لما فيه من المضار العظيمة، وقد نص جمع من أهل العلم الذين ألفوا في ذلك على مضاره الكثيرة، ونص عليها الأطباء العارفون به، فهو محرم بلا شك، ولا يجوز تعاطيه، ولا بيعه، ولا شراؤه، ولا التجارة فيه، كالخمر كما يحرم بيع الخمر والتجارة فيها، فهكذا التدخين والقات وأشباهها من المضرات بالمسلمين وبالعباد، الواجب الحذر من ذلك، وألا يتجر فيها، وألا يتعاطاها المسلم، بل يحذرها غاية الحذر، كما يحذر الخمر، ويبتعد عنها، وكما أنه لا يجوز بيعها ولا شراؤها ولا شربها كذا التدخين، وهكذا القات يجب الحذر من هاتين المادتين لما فيهما من المضار العظيمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14481/حكم-التدخين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74508.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":16032,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المغرب باعثها أحد الإخوة من هناك يقول، شاب يسأل من المغرب، أخونا يقول: توفي رجل، ثم قام الناس بتشيعيه، وهم يقولون: لا إله إلا الله، محمد رسول الله، وبصوت مسموع، ومرتفع، ثم قام أهل الميت بالصدقة عليه، وعندما رجع الناس من دفنه بدؤوا في الأكل والشرب والضحك فيما بينهم، ما رأي سماحتكم في مثل هذه التصرفات؟ جزاكم الله خيرًا.","title":"حكم رفع الصوت عند تشييع الجنازة والضحك وصنع الطعام","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فاتباع الجنازة، ورفع الأصوات بالذكر، أو الصلاة على النبي ﷺ لا أعلم له أصلًا في الشرع، بل السنة خفض الصوت في هذه الحالة، وأن الإنسان يحاسب نفسه، ويتذكر مصير هذا الميت، ومصيره هو أيضًا؛ لأن الموت له شأن عظيم، وذكره يحرك القلب إلى الاستعداد للقاء الله، والقيام بحقه، والحذر من معاصيه . فالمسنون لأتباع الجنازة أن يتأملوا مصير هذا الميت ومصيرهم، وأن يعدوا العدة، وأن يخفضوا الأصوات؛ تقديرًا لهول الموقف، وشدة الحاجة إلى الإعداد للآخرة، والتأهب للموت قبل نزوله. وأما صنع الطعام من أهل الميت فهذا فيه تفصيل: أما صنع الطعام من أجل المصيبة، وجمع الناس هذا ليس من المشروع، بل من عمل الجاهلية، أما إذا صنعوه لأجل ضيف نزل بهم، أو لأنفسهم فلا بأس، أو جاءهم طعام من غيرهم، فإنه يسن لجيرانهم وأقاربهم أن يصنعوا لهم طعامًا؛ لأنه قد أتاهم ما يشغلهم، لما ثبت عن النبي ﷺ أنه أمر أهله أن يصنعوا طعامًا لأهل جعفر لما قتل في مؤتة، لما جاء خبره إلى المدينة  جعفر بن أبي طالب، أمر أهله أن يصنعوا لأهل جعفر طعامًا، وقال: إنه قد أتاهم ما يشغلهم. فإذا صنع أقارب الميت لأهل الميت طعامًا، أو جيرانه؛ فهذا مشروع، وإذا دعا أهل الميت من يأكل معهم من.. الطعام، أو قدموه.. لضيفانهم كل هذا لا بأس به. أما رجوعهم بعد الدفن للضحك، واللعب؛ هذا ليس بالمناسب، بل الأفضل لهم أن يتدبروا الأمر، ويظهر عليهم أمارات الحزن والاستعداد، ولهذا لما مات إبراهيم بن النبي ﷺ قال -عليه الصلاة والسلام-: العين تدمع، والقلب يحزن، ولا نقول إلا ما يرضي الرب، وإن بك يا إبراهيم ! لمحزونون. ولما حضر الموت ابن بنته -عليه الصلاة والسلام- دعته ﷺ .... حضر، فلما رأى نفس الصبي تقعقع عند الخروج؛ بكى، فسأله بعض الحاضرين عن ذلك، فقال: إنها رحمة، وإنما يرحم الله من عباده الرحماء. فالأفضل لأهل الميت أن لا يشتغلوا بالضحك واللعب، بل يقدروا الموقف، ويظهر عليهم آثار الحزن مع الرضا عن الله، والاسترجاع: إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ [البقرة:156] والصبر والاحتساب، أما مقابلة ذلك بالضحك، واللعب فليس من المشروع، وليس من المناسب، بل المناسب إظهار الحزن، وإظهار الدعاء للميت، والاستغفار له، وعدم إظهار اللعب، والضحك، ونحو ذلك مما يدل على عدم المبالاة، وفي التأسي بالنبي ﷺ الخير والبركة، فما كان ﷺ عند الموت يظهر الضحك، بل كان يظهر الحزن والبكاء ويقول: إنها رحمة وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14669/حكم-رفع-الصوت-عند-تشييع-الجنازة-والضحك-وصنع-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_711/nour_71101.mp3","categories":["حمل الميت ودفنه","أحكام التعزية","البدع والمحدثات"]},{"id":16093,"question":"إبراهيم محمد يقول: عندما يموت قريب لنا يأتي إلى منزله عدد من القراء، أو من طلبة تحفيظ القرآن الكريم، ويقرؤون القرآن بنية وصول الثواب للميت، ثم بعد ذلك يدعون للميت، فبعدما ينتهون؛ يطعمون الطعام على المقرئين، أو يدفع لهم مالًا، أو يجمع بينهما، أو يفعل مثل هذا للمريض بالشفاء لمرضه، أو للذي بني له منزلًا؛ ليبارك الله  له في منزله.. فما الحكم؟","title":"حكم الاجتماع لقراءة القرآن للميت","answer":"الجواب: هذا لا أصل له، أقول: لا أصل له في هذا، كونه يقرأ للميت، أو يجمعهم على الأكل، ويقرؤون للميت؛ كل هذا لا أصل له، غير مشروع. أما كونه يزورهم يعزيهم، يزور أهل البيت للتعزية؛ هذا مستحب، أما جمعهم للقراءة، فالقراءة لا تلحق، ليس عليها دليل، ولا جمعهم للقراءة، أو للأكل، أو للتحدث، إذا صنع الطعام للناس لا؛ النبي ﷺ ما كان يفعل هذا مع الموتى، يقول جرير بن عبدالله البجلي  -وهو من الصحابة المعروفين-: «كنا نعد الاجتماع إلى أهل الميت، وصنعة الطعام بعد الدفن من النياحة». أما إذا زاروهم يعزونهم، ويقهووهم فنجان قهوة، فنجان شاهي ... أما تجمع بقصد التجمع، ونصب الخيام.. وأشباه ذلك، أو دعوة القراء.. كل هذا من البدع، لا أصل له، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14734/حكم-الاجتماع-لقراءة-القران-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57913.mp3","categories":["أحكام التعزية"]},{"id":16222,"question":"تقول: هل يجوز تنظيف الزجاج بالدقيق، أم أن هذا حرام؟","title":"حكم تنظيف الزجاج بالدقيق","answer":"الجواب: ما نعلم فيه بأسًا، التنظيف بالدقيقـ والعلاج بالدقيق، والصبغ بالدقيق الله جعله نعمة لنا، وننتفع به في العلاج والدواء، وتنظيف الزجاج إذا كان ينفع في ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14904/حكم-تنظيف-الزجاج-بالدقيق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75115.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":16230,"question":"ما هو توجيهكم لمن يقوم بغسل الأرز، ويكب ماءه في المجاري، هل هذا جائز، أو لا؟","title":"حكم سقوط اليسير من الأرز في المجاري عند غسله","answer":"الجواب: لا بأس بكبه في المجاري إذا كان ما فيه أرز ينتفع به، حبات يسيرة، أو شيء لا ينتفع به، أما إذا كان فيه حب، الحب يأخذه، ويصب الماء الذي هو الوسخ فقط، أما الحبوب من الحنطة، أو من الرز لا يلقيها في المجاري، لكن لو فات عليه حبة، أو حبتان من غير قصد لا يضره. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14906/حكم-سقوط-اليسير-من-الارز-في-المجاري-عند-غسله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75116.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":16384,"question":"هل يلقى الميت في القبر على ظهره، أو على جنبه الأيمن متجهًا إلى القبلة؛ لأني أرى الناس عندنا يطرحون الميت على ظهره، وبعد الأربعين من موت الميت يقوم أقاربه بإلقاء عزيمة كبيرة، ويسمونها الفاتحة، ما هو رأيكم فيما يفعله الناس؟","title":"كيفية وضع الميت في القبر وحكم العزومة بعد الموت","answer":"الجواب: السنة أن يوضع على جنبه الأيمن موجهًا إلى القبلة، هذا هو السنة، فإن الكعبة هي قبلة المسلمين أحياء وأمواتا، وأما هذه العزيمة فلا أصل لها، بل هي بدعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15092/كيفية-وضع-الميت-في-القبر-وحكم-العزومة-بعد-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75414.mp3","categories":["حمل الميت ودفنه","أحكام التعزية"]},{"id":16500,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع: محمود أحمد دوسة من الزعفرانية، يسأل ويقول: \"نهى رسول الله ﷺ عن أكل لحوم الحمر الإنسية\" فما هي الحمر الإنسية؟","title":"المقصود بالحمر الإنسية وحكم أكل لحومها","answer":"الجواب: الحمر الإنسية هي الحمر الموجودة بين الناس، ويقال لها: الأهلية، التي يركبونها، ويستعملونها في بيوتهم، وفي نخيلهم، ومزارعهم، وكانت فيما مضى يسنى عليها يعني: يجذب بها الماء من الآبار لسقي النخيل، وسقي الزروع قبل مجيء المكاين في الجزيرة العربية، وفي البلدان الإسلامية، هذه الحمر الأهلية المعروفة التي بين الناس. أما الحمر الوحشية فهي صيد، لها لون آخر غير هذه الحمر، يقال لها: الحمر الوحشية، لها صفة خاصة، ونقش خاص في جلودها، فهي صيد يؤكل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15244/المقصود-بالحمر-الانسية-وحكم-اكل-لحومها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_814/nour_81404.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":16675,"question":"من أسئلة السائلة المستمعة من السودان تقول يا سماحة الشيخ: إذا ذهبنا لعزاء شخص ما، تقول: قبل أن نصافح أهل الميت، نرفع الأيدي، وندعو للميت، ثم نقوم بمصافحتهم، هل هذه العادة صحيحة؟","title":"حكم رفع اليدين والدعاء للميت عند تعزية أهله","answer":"الجواب: لا أعرف لها أصلًا، لكن الدعاء للميت لا بأس، قبل أو بعد، أما رفع الأيدي، واعتياده، هذا لا أصل له، لكن إذا إنسان سلم عليه، ودعا لميتهم قبل أو بعد؛ لا حرج، كله طيب، أما رفع اليد قبل ذلك، والدعاء قبل ذلك هذا ما أعرف له أصلًا. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15403/حكم-رفع-اليدين-والدعاء-للميت-عند-تعزية-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_584/58405.mp3","categories":["أحكام التعزية"]},{"id":16791,"question":"أمامي رسالة آثر صاحبها عدم ذكر اسمه، فيها سؤالان: السؤال الأول: ما رأي سماحة الشيخ في التدخين؟ وهل هو حرام، أم حلال؟ ويعقب أخونا فيقول: أعتقد أنكم أجبتم عن هذا؛ لكني لم أسمع، فاسمحوا لي، جزاكم الله خيرًا.","title":"ما حكم التدخين؟","answer":"الجواب: التدخين قد أجبنا عنه غير مرة، التدخين حرام، ومنكر، ومضاره كثيرة على الدين، والصحة، والمال، وقد يسكر بعض الأحيان بالنسبة إلى من تأخر عنه، ثم شربه، أو أكثر منه، ويحصل به أضرار كثيرة، وقد نص الكثير من أهل العلم على تحريمه، وأنه منكر، فالواجب الحذر منه، وتركه؛ لما فيه من الأضرار الكثيرة، والعواقب الوخيمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15553/ما-حكم-التدخين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76305.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":17448,"question":"سماحة الشيخ! هذه الرسالة وصلت من الجزائر بمرداس، من السائل عبد الرؤوف، يقول في سؤاله الأول: ما حكم الشرع فيما يسمى بعشاء الميت يا شيخ؟","title":"استحباب صنع الطعام لأهل الميت","answer":"الجواب: إذا عشوا ... الميت سنة، إذا مات إنسان شرع لجيرانه، وأقاربه أن يعشوهم، أن يبعثوا لهم عشاء؛ لأنهم مشغولون بالمصيبة، ثبت عنه ﷺ: أنه لما جاء خبر جعفر  جعفر بن أبي طالب لما قتل في غزوة مؤتة، قال لأهله ﷺ: اصنعوا لآل جعفر طعامًا؛ فقد أتاهم ما يشغلهم فإذا مات قريب الإنسان، أو جاره؛ استحب لأهله أن يصنعوا لهم طعامًا؛ لأنهم شغلوا بالموت. أما أهل الميت، فلا يصنعوا شيئًا، بدعة، كونهم يصنعون للناس، ويدعون للناس هذا يسمى مأتم، ما يصلح، يقول جرير بن عبد الله البجلي : \"كنا نعد الاجتماع إلى أهل الميت، وصنعة الطعام بعد الموت من النياحة\" يجتمعون لينوحوا عليه، أو ليصنعوا للناس طعامًا يدعونهم، هذا لا يصلح، أما يأتون للتعزية، يأتي الجيران، أو غيرهم يعزونهم، أو يبعثون لهم طعامًا؛ لأنهم مشغولون؛ فلا بأس. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16315/استحباب-صنع-الطعام-لاهل-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77203.mp3","categories":["أحكام التعزية"]},{"id":17463,"question":"هذا سائل للبرنامج أرسل بمجموعة من الأسئلة المستمعة (أ. س) من جمهورية مصر العربية، تقول: سماحة الشيخ! هل هذه الأحاديث صحيحة: «لا جلوس للعزاء» «لا عزاء بعد ثلاث» نرجو التوضيح، حيث إنه من عادتنا بأنه إذا حدثت وفاة فإن جميع الأهل يجتمعون في بيت المتوفى لتلقي العزاء؟ جزاكم الله خيرًا.","title":"الحكم على حديث: (لا جلوس للعزاء)","answer":"الجواب: ليس هذا الكلام بحديث، ولكنه من كلام بعض العلماء، وليس بحديث «لا جلوس للعزاء» و «لا عزاء بعد ثلاث» هذا ليس بحديث، ليس عن النبي ﷺ لكن جاء في الحديث الصحيح: لا تحد امرأة على ميت فوق ثلاث يعني: المرأة لا تحد على أخيها، أو أبيها فوق ثلاث، أما الثلاث فلا بأس أن تلبس لباسًا خلاف لباس العادة، ألا تطيب لا بأس في ثلاث، وبعد الثلاث تبقى على حالها الأولى، ولا تغير شيئًا، وأما الزوجة فتحد أربعة أشهر وعشرًا على زوجها فإنها تحد أربعة أشهر وعشرًا. وأما الجلوس للعزاء فلا أصل له في الشرع، لكن إذا جلس جلوس العادة في بيته، وزاره الإخوان يعزونه في الجلوس المعتاد بعد المغرب.. بعد الظهر.. بعد الضحى الجلوس المعتاد لا بأس، من غير أن يصنع وليمة، ولكن يجلس جلوس العادة، فيأتي إخوانه يسلمون عليه، ويعزونه، لا حرج في هذا، ولو بعد ثلاث، ولو عزوه بعد شهر، أو بعد عشر، إذا بلغهم الخبر متأخرًا وعزوه لا بأس، ولو بعد ثلاث لا حرج في ذلك، والحمد لله. المقدم: يكفي التلفون في العزاء يا فضيلة الشيخ؟ الشيخ: ويكفي التلفون في العزاء من طريق الهاتف، لا بأس، أو من طريق المكاتبة، والحمد لله. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16331/الحكم-على-حديث-لا-جلوس-للعزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77302.mp3","categories":["أحكام التعزية"]},{"id":17568,"question":"يقول: يقوم بعض الناس في مناطقنا، وخاصةً في شهر رمضان المبارك بتأجير قارئٍ يقرأ القرآن عن الأموات، مقابل عشرة ريالات عمانية للختمة الواحدة، هل تجوز المتاجرة بكلام الله ؟ وهل هذا المبلغ حلال؟ وما نصيحتكم لمن يقومون بذلك إن كان هذا الأمر مخالفًا للدين الحنيف؟ نرجو توضيح ذلك، فنحن قد وقعنا في الشبهات؟ ثم هل ذلك ينفع الميت؟ حيث أن البعض يستند إلى الحادثة التي صادفها الرسول ﷺ عندما مر بقبرين وهما يعذبان.ثالثًا: هل قراءة القرآن على الأموات من قبل ذويهم تنفعهم؟ حيث أن ذلك شائعٌ عندنا، خاصةً بعد ثلاثة أيامٍ من دفن الميت، إضافةً إلى ذبح الذبائح بعد موته، يتحول ذلك البيت إلى مناسبة عرس، تنعدم فيه الخشية، والعبرة، أنقذونا من البدع أثابكم الله، فإن مجتمعنا تنص عليه الآية: إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ [الزخرف:23]؟","title":"حكم تأجير قارئٍ يقرأ القرآن عن الأموات","answer":"الجواب: سبق الكلام في القراءة للميت، وأنه لا دليل على القراءة للأموات، وأما كونه يستأجر إنسان يتلو آيات، يستأجر حتى يتلو للميت، هذا لا أصل له، ولا يجوز، ولا تحل هذه الأجرة، قد حكى العلماء، حكى بعض أهل العلم الإجماع على تحريم ذلك، كشيخ الإسلام ابن تيمية رحمه الله ذكر الإجماع على أنه لا تجوز أخذ الأجرة على تلاوة القرآن، وأنه محرم بلا نزاع، كونه يقرأ ثمن، أو ثمنين، أو جزء، أو أكثر، أو أقل بمال، يقرأ للأموات، أو لأي سبب، لا يجوز هذا، وإنما تؤخذ الأجرة في التعليم، إن كان يعلم الأولاد، يعلم الناس، يعطى أجرة على التعليم، أما كونه يقرأ آيات، ويأخذ أجرة على هذه الآيات ليسمعها الناس منه، أو أنه يثوبها للميت، هذا لا أصل له، بل حكى مثلما تقدم شيخ الإسلام ابن تيمية الإجماع، وأنه لا نزاع في تحريم ذلك، أخذ الأجرة على مجرد التلاوة.\nأما كونه المعلم يعطى حتى يعلم الأولاد، حتى يعلم الناس القرآن؛ لا بأس بهذا، لقوله ﷺ: إن أحق ما أخذتم عليه أجرًا؛ كتاب الله، يعني: التعليم، والتوجيه، تعليم القرآن للناس؛ لا بأس أن يؤخذ عليه أجرة.\nأما كون أهل الميت يقيمون ذبائح، ولائم بعد الموت، يوم الموت، أو يوم ثالث، أو يوم عاشر، أو على رأس الشهر، أو رأس الأربعين، أو رأس السنة، هذا بدعة، لا يجوز هذا، ولكن يتصدقوا عن الميت، طعام يوزعوه على الفقراء، نيئًا أو مطبوخًا، يوزع على الفقراء، رز....... لا بأس، أم كونهم يصنعون طعام للناس، من شان المأكل، من شان الميت، أو يدعون الناس إليه ليقيمون ولائم، هذا بدعة. أما إذا أحبوا أن يتصدقوا بدراهم، أو بغيرها، في أي وقت، على الفقراء على الميت، هذا ينفع الميت، الصدقة تنفع الميت، هذا خيرٌ عظيم.\nفرقٌ بين الصدقة على الفقراء، والمساكين، وفرقٌ بين إقامة المآتم، كون جمع الناس يأكلون في بيت الميت، ويذبحون لهم الذبائح، هذا لا أصل له، والسنة أن يدفع لهم طعام -أهل الميت، جيرانهم.. أقاربهم، يصنعون لهم طعام، لما ثبت في الحديث أنه ﷺ لما أتى نعي جعفر بن أبي طالب ، يوم مؤتة، حين قتل هناك، لما جاء خبره  إلى المدينة، أمر النبي ﷺ أهله أن يصنعوا طعامًا لأهل جعفر، وقال: إنه أتاهم ما يشغلهم فإذا صنع الجيران، أو الأقارب، طعامًا لأهل الميت؛ لأنهم مشغولون بالمصيبة، هذا مستحب.\nأما كونه هم أهل الميت يصنعون للناس، يدعون الناس، هذا غير مشروع، وإذا جاءهم الطعام من جيرانهم، دعوا عليهم أن يأكلوا؛ لا بأس، جاءهم طعام كثير يزيد على حاجتهم، دعوا جيرانهم، دعوا من يأكل معهم؛ هذا لا بأس به. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16490/حكم-تاجير-قارى-يقرا-القران-عن-الاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_726/nour_72604.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":17777,"question":"يقول السائل: هل شرب الدخان مكروه أو محرم؟ وما الدليل على ذلك مأجورين؟","title":"هل شرب الدخان مكروه أم محرم؟","answer":"الجواب: شرب الدخان محرم منكر، والدليل على ذلك أن فيه مضارًا كثيرة، والشريعة قد حرمت ما يضر الناس، وهو فيه مضار كثيرة: الصحة والعقل والمال، وهو ضار محض بلا منفعة، كله ضار، ولهذا حكم أهل العلم المحققون بتحريمه، فالمقصود أنه محرم ومنكر يجب تركه. نعم.","link":"https://binbaz.org.sa/fatwas/16762/هل-شرب-الدخان-مكروه-ام-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59629.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":17820,"question":"المستمع محمد المغامس من الرياض يسأل ويقول: متى يبدأ العزاء لأهل الميت؟ هل هو بعد وفاة الميت مباشرة؟ أم بعد الدفن؟","title":"متى يبدأ العزاء؟","answer":"الجواب: يبدأ من حين الموت، تبدأ التعزية من حين الموت، قبل الصلاة، وقبل الدفن، يعزون من حين يموت الميت، ولو قبل أن يغسل، ولو بعد التغسيل بعد التغسيل بعد الصلاة، لا ليس لا حد له، أما بدؤها من حين الموت، وأما النهاية فلا حد لها.","link":"https://binbaz.org.sa/fatwas/16813/متى-يبدا-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59722.mp3","categories":["أحكام التعزية"]},{"id":17826,"question":"السفر للعزاء يا سماحة الشيخ! ما رأيكم فيه؟","title":"ما حكم السفر للعزاء؟","answer":"الجواب: لا حرج، يسافر إلى بلد يعزي أهل أقاربه لا بأس، أو يصلي على الميت لما بلغه أنه يصلى عليه في الوقت الفلاني، لا بأس.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16815/ما-حكم-السفر-للعزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59723.mp3","categories":["أحكام التعزية"]},{"id":18055,"question":"هذا سؤال من المستمع محمد مختار أحمد من السودان، يقول: عندنا بعض العادات في العزاء؛ ومنها: أن يرفع الناس أيديهم لأهل الميت، ويقولون: الفاتحة، ويقرؤون سورة الفاتحة، فهل هذا جائز أم لا؟","title":"حكم قراءة سورة الفاتحة في العزاء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالمشروع في العزاء هو الدعاء لأهل الميت بالتوفيق بالصبر والاحتساب وعظيم الأجر وغفران الذنوب للميت، أما رفع الأيدي إليهم وقراءة الفاتحة فليس له أصل. رفع الأيدي ما ندري ما مراده؛ فإن كان المراد به المصافحة عند اللقاء فهذا لا بأس به، هذا مشروع كونه يصافح المعزى إذا كان رجل أو كانت امرأة ذات محرم له كخالته وعمته وأمه ونحو ذلك، فلا بأس أن يصافح المعزى، ويقول: أعظم الله أجرك وأحسن عزاءك وغفر لميتك وجبر مصيبتك. هذا كله طيب، يقال هذا للرجل والمرأة جميعًا، فيصافح الرجل ويصافح المرأة إذا كانت محرمًا له كأخته وعمته وخالته. أما النساء غير المحارم فلا يصافحن، وما يفعله بعض الناس من مصافحة النساء غلط لا يجوز، يقول النبي ﷺ: إني لا أصافح النساءوتقول عائشة رضي الله عنها: «ما مست يد رسول الله يد امرأة قط - يعني: في البيعة- قالت: ما كان يبايعهن إلا بالكلام». فهذا يدلنا على أن المرأة الأجنبية ليس للرجل أن يصافحها، ولكن لا بأس بمصافحة المرأة ذات المحرم كأمه وجدته وخالته وعمته ونحو ذلك، عند العزاء وعند اللقاء لا بأس في ذلك عند المقابلة إذا قابل خالته أو عمته إذا زارها صافحها ودعا لها، أو عند العزاء صافحها ودعا لها، وهكذا إذا قابل الرجل عند اللقاء في الطريق أو زاره في البيت وصافحه كل هذا طيب، وهكذا عند العزاء يصافحه ويدعو له. أما إن كان رفع أيدي على غير هذه الطريق رفع أيدي إلى السماء من غير مصافحة هذا لا أصل له.\nوهكذا قراءة الفاتحة عند لقاء المعزى ليس له أصل بل هو من البدع. نعم. المقدم: كذلك يقول: إنهم يجتمعون ويقرؤون الكتاب على أساس أن ثوابه يمشي للميت، وأيضًا عندما يمرون بالمقابر يرفعون أيديهم ويقرؤون سورة الفاتحة ترحمًا على الأموات فهل هذا جائز ؟ الشيخ: وهكذا اجتماعهم على القراءة وقت العزاء هذا كله لا أصل له إنما يعزي وينصرف يعزي ويدعو لهم وينصرف، أما اجتماعهم عند أهل الميت على قراءة القرآن، أو على قراءة أشياء أخرى، أو للأكل والشرب هذا ليس له أصل، وإنما السنة أن جيران أهل الميت أو أقاربهم يبعثون لهم طعامًا كما فعله النبي ﷺ لما جاء نعي جعفر بن أبي طالب حين قتل في مؤتة في الشام قال النبي ﷺ لأهله: اصنعوا لآل جعفر طعامًا فقد أتاهم ما يشغلهم هذا هو الأفضل وهذا هو السنة. أما كون أهل الميت يصنعون طعامًا ويجمعون الناس على القراءة أو على دعاء أو على غير ذلك فهذا ليس من السنة، قال جرير بن عبد الله البجلي : «كنا نعد الاجتماع إلى أهل الميت وصنعة الطعام بعد الدفن كنا نعده من النياحة» فهذا يدل على أن هذا لا يجوز ولا ينبغي وليس من المشروع بل هو خلاف المشروع .نعم. المقدم: بالنسبة لرفع أيديهم وقراءة الفاتحة فوق المقابر؟ الشيخ: كذلك عند المقابر هذا لا يجوز أيضًا وليس له أصل، لا ترفع الأيدي عند المقابر ولا يقرأ القرآن بين القبور، ولا عند زيارة المقابر ليس له أصل هذا، ولكن السنة أن يدعو للموتى ويستغفر لهم، كان النبي ﷺ إذا زار القبور دعا للأموات بالمغفرة والرحمة، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية وفي رواية أخرى: يرحم الله المستقدمين منا والمستأخرين، اللهم اغفر لأهل بقيع الغرقد يدعو لهم هكذا عليه الصلاة والسلام. فهذا يدلنا على أن السنة في زيارة القبور الدعاء للأموات والترحم عليهم، أما أنه يقرأ لهم القرآن أو يرفعوا الأيدي إلى السماء أو إلى أي إشارة فهذا شيء لا أصل له. المقدم: جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/17089/حكم-قراءة-سورة-الفاتحة-في-العزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_901/nour_90101.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":18059,"question":"يسأل سماحتكم، فيقول: الحيوانات البرية ذوات الظفر والناب، هل لحمها حرامٌ؟ أم حلال؟ وما الدليل على ذلك؟","title":"حكم أكل الحيوانات البرية ذوات الظفر والناب","answer":"الجواب: السباع كلها حرام، والسباع: هي التي تمسك بظفرها -بمخلبها- من الطيور، كالعقاب، والصقر، والباشق، هذه محرمة، وهكذا السباع التي تفترس بنابها، كالكلاب، والقطط، والذئاب، والأسود، والنمور، كلها محرمة؛ إلا الضبع خاصة، مستثناة، الضبع صيد، استثناه النبي عليه الصلاة والسلام. يقول ابن عباس \"نهى رسول الله ﷺ عن كل ذي مخلب من الطير، وعن كل ذي ناب من السباع\"، ويقول ﷺ: كل ذي ناب من السباع فأكله حرام فجميع السباع التي تفترس، كلها محرمة، سواءٌ كانت كلابًا، أو ذئابًا، أو ثعلبًا، أو قطًا، أو غير ذلك، وهكذا الطيور التي تمسك بمخلبها، تصيد بمخلبها، كالعقاب، والصقر، والباز، وأشباه ذلك، كلها محرمة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17092/حكم-اكل-الحيوانات-البرية-ذوات-الظفر-والناب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_729/nour_72915.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":18093,"question":"يقول: أعمل في شركة مواد غذائية، وأرى بعض العمال يأكلون، ويشربون من البضاعة الموجودة في الشركة، فهل أنكر عليهم؟ أم لا؟ وهل يعتبر ما يفعلونه من المحرمات؟","title":"حكم أكل العمال من البضاعة الموجودة في الشركة","answer":"الجواب: نعم، لا يجوز لهم أن يأكلوا منها، ولا يشربوا منها إلا بإذن المسؤول، إذا كانت البضاعة من الشراب هذا للبيع، والفواكه للبيع، أو غيرها من الأطعمة، ليس لهم أن يأخذوا منها إلا بإذن، بإذن المسئول عن هذه الشركة، أو هذه البقالة، وليس لهم أن يقدموا على الأكل منها؛ لأن هذا يضرها، وقد يأكلوا كثيرًا، قد يكونون كثيرين. فالحاصل: لابد من إذن المسؤول، لابد من إذن المسئول عن هذه البقالة، أو هذه الشركة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17128/حكم-اكل-العمال-من-البضاعة-الموجودة-في-الشركة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73017.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":18114,"question":"سؤالها الثاني: الرجاء أن تعرفوني عن حكم الصعود (التنباك) بالتفصيل، وبماذا تنصحون من ابتلي به؟","title":"ما حكم التنباك؟","answer":"الجواب: التنباك من المحرمات الخبيثة التي أجمع الأطباء العارفون به على ضرره العظيم المتنوع الكثير، وكذلك أجمع العارفون به الذين جربوه على مضرته العظيمة، فالواجب تركه، وقد نصح الأطباء بذلك من الكفرة وغير الكفرة، حتى الكفرة عرفوا شره وضرره. فالواجب على كل مسلم أن يحذره، وعلى كل ناصح نفسه أن يتقي شره وأن يدعه وأن يستعمل الأسباب التي تعينه على تركه، ومنها ألا يجالس أهله، فإن مجالستهم تفضي به إلى أن يشاركهم. فينبغي للمؤمن أن يحذر هذا الدخان الخبيث وأن يبتعد عن مجالسة أهله، لعل الله يعينه على تركه، وهذا شيء واجب؛ لأن الله حرم علينا الخبائث وحرم علينا ما يضرنا، قال تعالى: يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4]، الآية من سورة المائدة، فبين سبحانه: أنه لم يحل لنا إلا الطيبات، ولا يقول مسلم يعرف هذا الدخان أنه من الطيبات، بل هو من الخبائث، وقال سبحانه في سورة الأعراف في وصف نبيه محمد عليه الصلاة والسلام: وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَالأَغْلالَ الَّتِي كَانَتْ عَلَيْهِمْ فَالَّذِينَ آمَنُوا بِهِ وَعَزَّرُوهُ وَنَصَرُوهُ وَاتَّبَعُوا النُّورَ الَّذِي أُنزِلَ مَعَهُ أُوْلَئِكَ هُمُ الْمُفْلِحُونَ [الأعراف:157]. فالمفلحون: من اتبعوه عليه الصلاة والسلام وساروا على نهجه وعظموا أمره ونهيه ومن ذلك ترك الخبائث والمسكرات والمخدرات والدخان كلها من الخبائث، كما أن الميتة والخنزير من الخبائث. فهكذا ما يضر العبد ويضر عقله وبدنه من أنواع المسكرات والمخدرات وأنواع التدخين والحشيشة التي تضر متعاطيها مضرة كبيرة، ينبغي للمؤمن أن يحذر هذه الأمور وأن يستعين بالله على تركها وأن يستعمل كلما يعينه على تركها، وأن يحذر صحبة أهلها أو مجالستهم، لعل الله يمن عليه بالسلامة، والله المستعان.","link":"https://binbaz.org.sa/fatwas/17159/ما-حكم-التنباك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_851/nour_85105.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":18152,"question":"الرسالة التالية وصلت إلى البرنامج من الأخوين: حسن بن صقر المحمد وأحمد بن موسى الزهراني إخواننا يصفون الغذاء الذي تغذى به الدواجن، فيقولون: بعد سؤالنا عن ماهية المواد التي تغذى بها الدواجن أخبرنا المشرف عن مستودعات الأغذية، وفني المختبر أن هذه الأطعمة التي تغذى بها الدواجن تستورد من مجازر أوروبا، وهي عبارة عن مخلفات المجازر من لحوم وجلود وعظام ودماء، وقد يدخل فيها لحم الخنزير بشكل مسحوق يتم خلطها جميعًا إضافة لحبوب وعظام أسماك، وتوزع على قسمين: قسم للدواجن التي تؤكل، وقسم للدواجن التي تبيض باسم أن هذا بروتين للتغذية، مع العلم أن مزارع كذا، ويسميها -سماحة الشيخ- تقوم بتوزيع وتموين هذه الأغذية للمزارع في عدد من المناطق، ويرجو من سماحة الشيخ التوجيه والإرشاد حول هذا؟ جزاكم الله خيرًا.","title":"حكم إطعام الدواجن والماشية أعلافًا مشبوهة","answer":"الجواب: قد جاءنا نماذج من هذا وأحلناها إلى الجهات المختصة، وذكروا أنها سليمة وليس فيها شيء مما يحذر، وإنما هي أشياء من أسماك ومن بذور سليمة ومن أشياء ليس فيها محلول لا من جهة الخنزير ولا من جهة الدماء. وبكل حال: فإذا وجد من هذه الأشياء شيء من النجس أو من الحرام كالخنزير، إذا كان قليلًا فإنه يعفى عنه، كما يعفى عما تأكله الجلالة من الأشياء الحقيرة القليلة، وإنما الذي يضر أن يغلب النجس والخبيث على طعام الدواجن وشرابها، فإذا كان ما تأكله مما يستقبح، إذا كان قليلًا يغلب عليه الطعام الطيب والشراب الطيب فإنه لا يضر. أما الذي جاءنا من النماذج التي بعثت إلينا من جهات متعددة من الإخوان هنا، وأحلناها إلى الجهات المختصة واختبروها فإنهم ذكروا أنه ليس فيها محذور وأنها ما بين بذور لا بأس بها، وأشياء أخرى ليس فيها محذور من أسماك وغيرها تغذى بها هذه الدواجن والأصل السلامة وبراءة الذمة حتى يعلم يقينًا أنها غذيت بما حرم الله ويغلب ذلك، ويكون ذلك كثيرًا، يعني: يغلب على طعامها وشرابها، حتى تكون كالجلالة، أما الشيء اليسير فيغتفر. نعم. المقدم: إذًا: يرى سماحتكم الوصول إلى تلك المصانع ليرى الإنسان بنفسه الحقيقة؟ الشيخ: هذه الأشياء التي ترد من هذه المصانع لابد أن تحال إلى الجهات المختصة على هذه الجهات التي تستوردها إذا كان عندها شك أن تحيلها إلى الجهات المختصة في المملكة مادامت المسألة في المملكة تحال إلى الجهات المختصة والمختبرات المختصة مثل وزارة التجارة وهيئة المقاييس وجامعة الإمام محمد بن سعود وجامعة الملك سعود التي فيها المختبرات، يختبرونها ويبينون ما فيها، فإنا أحلناها إلى بعض هذه الجهات ورأوا أنها سليمة. فالحاصل: أن الوارد قد يختلف وقد يتنوع المستورد قد يتنوع، فالذين يستوردون هذه الأشياء الواجب عليهم أن يجتهدوا حتى يعرفوا الحقيقة وحتى لا يغشوا الناس ولا يدخلوا على الناس ما حرم الله عليهم، وعلى الدولة أن تلزمهم بهذا، على الدولة بواسطة وزارة التجارة وغيرها من المسئولين الذين لهم صلة بهذا الشيء، عليهم أن يلزموا أي شركة وأي مزرعة تستورد أن تعرف ما تستورد وأن يكون ذلك سليمًا، وحتى يشهد لهم بذلك المسئولون هنا. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17191/حكم-اطعام-الدواجن-والماشية-اعلافا-مشبوهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_853/nour_85302.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":18197,"question":"رسالة وصلت إلى البرنامج من أوجلة في ليبيا، باعث الرسالة أحد الإخوة يقول حمد عتيبي، أرجو تقديم أسئلتي إلى سماحة الشيخ عبد العزيز بن عبد الله بن باز .السؤال الأول: بعد دفن أي ميت في بلدتنا ورجوع أهل الميت إلى المنزل، يصحبهم الكثير من أهالي البلدة، فيجتمع القراء في بيت المتوفى، ويقرءون القرآن بطريقة تقسيم القرآن إلى أجزاء، ويتلونه معًا في ساعة واحدة، كل يقرأ جزءًا أو اثنين، ثم يتناولون طعام الصدقة الذي تم إعداده وهو عبارة عن عدة رءوس من الأغنام تم ذبحها قبل دفن الميت، يتم هذا في اليوم الأول والثاني والثالث ثم في يوم الأسبوع، فهل يصل ثواب القراءة والصدقة على هذا النحو للميت، مع العلم أن الذين حضروا وأكلوا من طعام الصدقة ليسوا من المحتاجين؟ أفتونا جزاكم الله عنا وعن المسلمين خير الجزاء.","title":"حكم الاجتماع في بيت الميت لقراءة القرآن وتناول الطعام","answer":"الجواب: هذا العمل لا أعلم له أصلًا في الشرع، وهو من البدع التي أحدثها الناس، فليس من عادة النبي ﷺ ولا من عادة أصحابه الرجوع إلى بيت المتوفى أو غيره بعد الدفن ليجتمعوا على الطعام وعلى قراءة القرآن، ليس هذا من سنة المسلمين فيما نعلم. أما لو كان ذلك من غير قاعدة ومن غير اتباع معين بل صدفة بأن دعاهم، بعدما رجعوا من الدفن دعاهم بعض إخوانهم وقدم لهم طعامًا، أو قرأ أحدهم بعض القراءة من غير أن تكون عادة مستمرة ولا سنة قائمة بل لعارض هذا لا يضر، إذا رجعوا قال بعض إخوانهم: تفضلوا عندي، وأطعمهم ما تيسر أو قرأ أحدهم بعض القراءة لأنفسهم هذا لا بأس. أما أن يتخذوا هذا عادة بعدما يرجعون يرجعون إلى محل الميت أو إلى محل فلان أو فلان قاعدة، ليقرءوا القرآن ويثوبوه ويأكلوا مما أعد قبل الموت هذا لا أصل له، بل هو من البدع، والرسول عليه الصلاة والسلام قال: من أحدث في أمرنا هذا ما ليس منه فهو رد متفق على صحته، وقال عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد خرجه مسلم في صحيحه عن عائشة رضي الله عنها، وقال أيضًا عليه الصلاة والسلام: إياكم ومحدثات الأمور، فإن كل محدثة بدعة وكان يقول في خطبة الجمعة عليه الصلاة والسلام: أما بعد: فإن خير الحديث كتاب الله وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة رواه مسلم في الصحيح، زاد النسائي بإسناد جيد: وكل ضلالة في النار. فنصيحتي لإخواني هؤلاء أن لا يفعلوا هذا، وإذا فرغوا من دفن الميت كل يذهب إلى أهله وإلى رحله ويدعو لميتهم. أما قراءة القرآن للميت فليس لها أصل، وإن قال بذلك جمع من أهل العلم وقالوا: لا بأس لكن ليس له أصل معروف عن النبي ﷺ ولا عن الصحابة، وقد قال الله : فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ [النساء:59]، وقال سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10]. وبالنظر في كتاب الله وسنة رسوله ﷺ لا نعلم ما يدل على ذلك عند الرد إليهما، فليس من هدي النبي ﷺ وليس من هدي أصحابه، ثم فيه تكليف لمن يبذل هذه الأموال سواء كان أهل الميت أو غيرهم وشرع دين لم يأذن به الله، والله يقول سبحانه: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21]. فالواجب ترك هذه العادة والاشتغال بما ينفعه من الدعاء للميت في الطريق وفي البيت، الدعاء له الترحم عليه، وإذا أحب أحد يتصدق عنه من غير إلزام لأحد فلا بأس، الصدقة تنفع الميت، أو يتصدق عنه أهله، الصدقة تنفع الميت بأن يعطوا الفقراء صدقة أو ملابس من ملابس أو نقود أو طعام كل هذا طيب من فعله عن الميت، فهو مأجور إذا كان الميت مسلمًا. كذلك بعث الطعام لأهل الميت إذا صنع لهم جيرانهم أو أقاربهم طعامًا وبعثوه إلى أهل الميت لأنهم مشغولون بالمصيبة فهذا مشروع؛ لأنه ثبت عن رسول الله عليه الصلاة والسلام أنه لما أتى خبر موت جعفر بن أبي طالب  في الشام في مؤتة أمر أهله أن يصنعوا لهم طعامًا يصنعوا لأهله طعامًا، قال: اصنعوا لآل جعفر طعامًا فقد أتاهم ما يشغلهم فأمر ببعث الطعام إلى أهل جعفر ؛ لأن المصيبة قد شغلتهم عن صنع الطعام لأنفسهم، هذا لا بأس به بل هو مشروع. أما أهل الميت فلا، أما أهل الميت لا يقدمون الطعام للناس ولا يصنعونه للناس، ولا يكلفون بذلك، لا من مال الميت ولا من غير مال الميت، لكن لو نزل عليهم ضيف وأطعموه من طعامهم، أو أطعموه بما يناسبه لأنه ضيف، لا من أجل الميت لا من أجل اتخاذ عادة بل من أجل الضيف فلا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17233/حكم-الاجتماع-في-بيت-الميت-لقراءة-القران-وتناول-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_907/nour_90704.mp3","categories":["البدع والمحدثات","أحكام التعزية"]},{"id":18447,"question":"أخونا له سؤال آخر يقول فيه: إنني من جمهورية مالي، ولقد ألفت عند أهلنا عندما يموت الرجل أو المرأة يأتون بحافظ للقرآن لكي يقرءوا القرآن في منزل أهل الميت، وقالوا: إن هذه العملية المقصود منها هو نزول الرحمة على أهل الميت بعد المصيبة، فهل هذا العمل يجوز شرعًا؟ جزاكم الله خيرًا.","title":"حكم الاجتماع في بيت الميت وقراءة القرآن","answer":"الجواب: لا أعلم لهذا أصلًا، لا أعلم لهذا أصلًا في الشريعة، أما إذا فعلوه كشيء عادي غير مقصود، يقرءون القرآن لما في القرآن من الخير وطلب الأجر لا من أجل الموت ولا من أجل أن هذا البيت فيه شخص قد مات، فيقصدون من هذا أن هذا يعني يسليهم ويزيل حزنهم بطريقة خاصة وطريقة يعني مستعملة ومستمرة كأنه شيء مشروع، فهذا لا أعلم له أصلًا. أما إذا فعل بعض الأحيان أو عن غير قصد أو من أهل البيت حضر عندهم من يقرأ وقال: اقرأ علينا يا أخي، سمعنا من كلام الله، هذا كله طيب، أما أن يقصد ويتخذ عادة متبعة فيمن مات عنده ميت يحضر القراء أو قارئ يقرأ هذا لا أعلم له أصلًا وأخشى أن يكون بدعة.","link":"https://binbaz.org.sa/fatwas/17545/حكم-الاجتماع-في-بيت-الميت-وقراءة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_865/nour_86506.mp3","categories":["أحكام التعزية"]},{"id":18506,"question":"السائلة أختكم في الله أم عبد الله لها سؤالان، تقول في السؤال الأول: نرى البعض من الناس إذا توفي لهم قريب يجتمعون في بيت واحد، أي: يجتمع أفراد العائلة من إخوة وأخوات، وأعمام وخالات، ونجد أن أقاربهم ومعارفهم يرسلون لهم الطعام لمدة ثلاثة أيام، وأحيانًا يكون ذلك أكثر من ثلاثة أيام، فهل في ذلك شيء؟","title":"حكم إرسال الطعام لأهل الميت من الأقارب والجيران","answer":"الجواب: ليس في ذلك شيء، السنة أن أقارب الميت أو جيرانه يهدون لهم طعامًا .. يبعثون لهم طعامًا؛ لأنهم قد أتاهم ما يشغلهم، النبي ﷺ لما مات جعفر، لما قتل جعفر بن أبي طالب في مؤتة في الشام قال النبي ﷺ لأهل بيته: ابعثوا لأهل جعفر طعامًا قال لأهله: ابعثوا لأهل جعفر طعامًا فإنه قد أتاهم ما يشغلهم، فالسنة لجيرانهم أو أقاربهم أن يبعثوا لهم طعامًا أيام الحزن ثلاثة أيام أو أكثر، وإذا زارهم غيرهم وعزوهم فهذا أفضل، سنة التعزية، أما أهل الميت لا، ليس لأهل الميت أن يصنعوا شيئًا، لكن التعزية كونهم يزارون ويعزون فهذا سنة. نعم. المقدم: التعزية في التلفون سماحة الشيخ؟ الشيخ: لا بأس بالتلفون أو بالمكاتبة كله طيب. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17601/حكم-ارسال-الطعام-لاهل-الميت-من-الاقارب-والجيران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78607.mp3","categories":["أحكام التعزية"]},{"id":18802,"question":"السائل أبو أحمد يقول: سماحة الشيخ، هل العزاء محدد بمكان معين؟ وما حكم التعزية إذا تأخرت أكثر من يومين أو ثلاثة؟","title":"حكم تأخير التعزية عدة أيام","answer":"الجواب: ليس للعزاء مكان، ولا عدد من الأيام، لم يحدد لا أيام العزاء، ولا مكان العزاء، يعزيه في أي مكان في الطريق، في المسجد، في المقبرة، في بيته، من طريق الهاتف ما في بأس، وليس للأيام حد يعزيه في اليوم الأول، أو في اليوم الثاني، أو في اليوم الثالث، أو الرابع، والمستحب أن يبادر بالتعزية؛ لأن المصيبة في أولها أشد، فالمبادرة بالتعزية أفضل في أولها، في أول المصيبة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17937/حكم-تاخير-التعزية-عدة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79118.mp3","categories":["أحكام التعزية"]},{"id":18942,"question":"هذا سائل يقول: يا فضيلة الشيخ، قال لي بعض الأصدقاء: بأن شرب الدخان ليس حرامًا، وإنما هو مكروه، فأرجو من سماحتكم التوضيح في ذلك، مع ذكر الأدلة على تحريم شرب الدخان. جزاكم الله خيرًا.","title":"هل شرب الدخان مكروه أم حرام؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن شرب الدخان من المحرمات المعلومة؛ وما ذاك إلا لأضراره الكثيرة، والشريعة جاءت بتحريم كل ما يضر العبد في دينه ودنياه، والدخان أضراره كثيرة على العقل والبدن والمال والسمعة، فأضراره متعددة، فالواجب على كل مسلم تركه، والحذر منه، نعم.","link":"https://binbaz.org.sa/fatwas/18060/هل-شرب-الدخان-مكروه-ام-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88201.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":19025,"question":"من السودان الخرطوم المستمع (ع. أ. أ. أ) يسأل ويقول: هل يجوز لنا أن نذهب إلى منزل الإنسان الميت بعد دفنه؟ وما هو تفسير قوله ﷺ: اصنعوا لآل جعفر طعامًا جزاكم الله خيرًا.","title":"حكم الذهاب إلى أهل الميت للتعزية","answer":"الجواب: الذهاب إلى المنزل للتعزية مشروع، وإذا صادفت المعزى في غير المنزل في الطريق، أو في المسجد، وعزيته كفى، فالذهاب للمنزل ليس مقصودًا لذاته، وإنما المقصود الذهاب للتعزية. فإذا ذهبت إلى المنزل لتعزية أهل البيت فهذا مشروع، ومن باب جبر المصاب، والتأثر بموت أخيك، والحرص على جبر أهل المصيبة، يقول النبي ﷺ: مثل المؤمنين في توادهم، وتراحمهم، وتعاطفهم كمثل الجسد، إذا اشتكى منه عضو تداعى له سائر الجسد بالسهر والحمى، يقول النبي ﷺ: المؤمن للمؤمن كالبنيان يشد بعضه بعضًا، وشبك بين أصابعه، لكن إذا صادفت المعزى في الطريق، أو في المسجد، أو في بيت آخر؛ كفى ذلك والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18200/حكم-الذهاب-الى-اهل-الميت-للتعزية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_796/nour_79604.mp3","categories":["أحكام التعزية"]},{"id":19165,"question":"هذا المستمع (ع. ع. س) من ليبيا يسأل ويقول: هل السجاير - أي: الدخان - حرام أم حلال أم مكروه؟ جزاكم الله خيرًا.","title":"حكم الدخان","answer":"الجواب: الدخان فيه شر عظيم، ومضار كثيرة على الصحة والمال، وهو أيضًا من المعاصي التي تغضب الله  فالواجب تركه لما فيه من المضار الكثيرة، فهو إتلاف للمال في غير حق، وإضاعة المال بغير حق، وهو مضر بصحة العبد، ولا يجوز له أن يضر بنفسه، وأن يتعاطى ما يضره، وقد يخدر، وقد يسكر في بعض الأحيان، إذا أخره كثيرًا ثم تعاطاه قد يسكر به بعض الناس، وقد يتخدر بعض الناس به، فالمقصود أنه منكر وحرام، ولا يجوز تعاطيه، ولا بيعه، ولا شراؤه لما فيه من المضار الكثيرة. فعليك يا عبد الله أن تدعه، وأن تحذره، وعلى كل مسلم أن يحذره، ولا يجوز لأحد أن يتعاطى بيعه على الناس، وتوريده إلى الناس هذا منكر لا يجوز، وهو من التعاون على الإثم والعدوان، فنسأل الله للجميع الهداية. المقدم: اللهم آمين، اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18359/حكم-الدخان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_798/nour_79807.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":19175,"question":"في قضيتها الثانية تقول: خالي لا يصدق أن التدخين حرام، ويقول: لا أصدق أنه حرام إلا عندما أسمع من سماحة الشيخ عبد العزيز بن باز، أرجو أن توضحوا حكم التدخين، وتقدموا النصيحة لخالي؟ جزاكم الله خيرًا.","title":"هل التدخين حرام؟","answer":"الجواب: التدخين ثبت عندنا أنه محرم، وقد علمنا أسبابًا كثيرة لتحريمه من أضراره المتعددة، فهو محرم بلا شك؛ لأنه يشتمل على أضرار كثيرة بينها الأطباء وبينها من استعمله. فالواجب على كل مسلم تركه والحذر منه؛ لأن الله حرم على المؤمن أن يضر نفسه، فهو يقول سبحانه: وَلا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ [البقرة:195] ويقول جل علا: وَلا تَقْتُلُوا أَنفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا [النساء:29] . فالواجب على كل مؤمن وعلى كل مؤمنة الحذر من كل ما حرم الله، والحذر من كل ما يضر دين العبد وبدنه ودنياه. فالله أرحم بعباده منهم بأنفسهم، قد حرم عليهم ما يضرهم، قال النبي ﷺ: لا ضرر ولا ضرار وهذا التدخين ضار ضررًا بينًا، بإجماع أهل المعرفة من أهل الطب، وبإجماع من عرفه وجربه، وما فيه من الضرر العظيم. فنصيحتي لخالك أن يتقي الله، وأن يحذر هذا الخبيث، وأن يتوب إلى الله منه، حتى تعود له صحته، وحتى يسلم من غضب الله، وحتى يحفظ ماله أيضًا، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18347/هل-التدخين-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93207.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":19293,"question":"بسم الله الرحمن الرحيم، سماحة الشيخ عبدالعزيز بن عبدالله بن باز حفظه الله! السلام عليكم ورحمة الله وبركاته، وبعد:فأنا مستمع مصري لبرنامجكم الكريم، وأود أن أطرح على سماحتكم السؤال التالي: إن الدجاج الأبيض يضاف للعلف الذي يتناوله الدم، فهل هذا الدجاج صالح للأكل أم أنه حرام؛ لأنه قد ذكر في كتب الفقه أن الحيوانات والطيور التي تتغذى على القاذورات إلى أن يتغير ريحها يطلق عليها اسم الجلالة، وهي تعتبر نجاسة، فإذا حبست و غذيت بالطعام الطبيعي حتى تزول عنها الرائحة الكريهة يزول عنها اسم الجلالة، ولا تكون نجاسة؟ هل يدخل الدم ضمن ما يمكن أن نطلق عليه قاذورات أم لا؟ جزاكم الله خيرًا، والسلام عليكم ورحمة الله وبركاته، عبد رب النبي أحمد جابر .","title":"حكم أكل الحيوانات التي تأكل الدم","answer":"الجواب:  نعم، إذا كان الطير وهو الدجاج ونحوه، أو البهائم الأخرى كالغنم والبقر والإبل، إذا تغذت بالنجاسات تسمى جلالة؛ إذا غلب عليها ذلك، أما إذا كان الشيء يسيرًا من الدم أو غيره والغالب عليها الشيء الطيب من الطعام الطيب فإنها لا تسمى جلالة، ولا يضرها ذلك، ولا بأس بأكلها، فإذا كان الذي يجعل في علفها من الدم شيء يسير، فإنه لا يضر، إذا غلب عليها الطعام الطيب والشيء الطيب فإنها لا تعتبر جلالةً ولا تعتبر نجسة، فإذا غلب عليها القاذورات من النجاسات أو من الدماء فإنها تحبس مدة مناسبة، وتعلف الطيب ثم تطهر بعد ذلك. وإذا حبست الدجاجة ثلاثة أيام كفى ذلك كما كان ابن عمر يفعل ذلك  وإذا حبست الشاة أكثر من ذلك كسبعة أيام أو أكثر، والبقرة كذلك سبعة أيام أو أكثر، وتعلف الطيب زال حكم القاذورات، والله ولي التوفيق . نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18481/حكم-اكل-الحيوانات-التي-تاكل-الدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_893/nour_89302.mp3","categories":["أحكام التعزية","الأطعمة والأشربة"]},{"id":19497,"question":"من أسئلة هذا السائل يقول: بعد وفاة الميت بأسبوع يقوم أهل الميت بعمل وليمة ويسمونها: صدقة، فهل هذا العمل جائز ويصل إلى الميت؟","title":"حكم عمل وليمة بعد الأسبوع الأول من دفن الميت","answer":"الجواب: لا هذا بدعة ما يجوز، هذا مأتم لا يجوز، يقول جرير  ابن عبد الله البجلي الصحابي الجليل: «كنا نعد الاجتماع لأهل الميت وصنعة الطعام بعد الدفن من النياحة»، ما يصلح. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18743/حكم-عمل-وليمة-بعد-الاسبوع-الاول-من-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93925.mp3","categories":["البدع والمحدثات","أحكام التعزية"]}]
